.ported-style-page { min-height: 100svh; overflow-x: hidden; isolation: isolate; line-height: normal; }
.ported-style-page, .ported-style-page * { box-sizing: content-box; }
.ported-style-page [hidden] { display: none !important; }
.ported-style-page button { font: inherit; }
.ported-style-page a { color: inherit; }
.ported-style-page img, .ported-style-page svg, .ported-style-page video, .ported-style-page canvas { max-width: 100%; }
.ported-style-page pre, .ported-style-page code { overflow-wrap: anywhere; }
.ported-style-page--embedded .site-nav, .ported-style-page--embedded .skip-link, .ported-style-page--embedded .page-back-link, .ported-style-page--embedded .page-footer { display: none !important; }

/* Keep app-level utility classes from changing the legacy sample geometry. */
.ported-style-page :where(.hero, .page-hero) {
  display: block;
  flex-direction: initial;
  justify-content: initial;
  min-height: initial;
  padding: 0;
  text-align: initial;
}

.ported-style-page .section h2::before {
  content: none;
  display: none;
}

.ported-style-page .hero__eyebrow {
  text-transform: none;
}

.ported-style-page .page-nav {
  gap: normal;
  margin-top: 0;
  grid-template-columns: none;
}

.ported-style-page .page-nav a,
.ported-style-page .page-nav a > span,
.ported-style-page .page-nav__divider {
  min-height: 0;
  border: 0;
  border-radius: 0;
  padding: 0;
  font-weight: inherit;
}

.ported-style-page .page-nav span {
  min-height: 0;
  border: 0;
  border-radius: 0;
  padding: 0;
  font-weight: inherit;
}

.ported-style-page .page-nav a {
  justify-content: initial;
  flex-direction: row;
}

.ported-style-page .page-nav a,
.ported-style-page .page-nav a > span {
  background: transparent;
}

.ported-style-page .page-nav a > span {
  display: inline;
  flex-direction: row;
  justify-content: initial;
}

.ported-style-page:not(.ported-style-page--platform-core):not(.ported-style-page--runtime-signal) .page-nav {
  position: static !important;
  margin: 24px auto 0 !important;
  width: min(1160px, 94vw) !important;
  border-radius: 16px !important;
  padding-bottom: 0 !important;
  background: rgba(20, 20, 20, 0.75) !important;
  border: 1px solid rgba(255, 255, 255, 0.12) !important;
  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.15) !important;
}

.ported-style-page:not(.ported-style-page--platform-core):not(.ported-style-page--runtime-signal) .page-nav a {
  color: #fff !important;
  border-color: rgba(255, 255, 255, 0.15) !important;
  background: rgba(255, 255, 255, 0.08) !important;
}

.ported-style-page:not(.ported-style-page--platform-core):not(.ported-style-page--runtime-signal) .page-nav a:hover {
  background: rgba(255, 255, 255, 0.16) !important;
  border-color: rgba(255, 255, 255, 0.3) !important;
}

.ported-style-page:not(.ported-style-page--platform-core):not(.ported-style-page--runtime-signal) .page-nav a svg {
  stroke: #fff !important;
}

.ported-style-page:not(.ported-style-page--platform-core):not(.ported-style-page--runtime-signal) .page-nav .page-nav__label {
  color: rgba(255, 255, 255, 0.5) !important;
}

