/* shared legacy navigation styles ported to src */
.ported-style-page:not(.ported-style-page--platform-core):not(.ported-style-page--runtime-signal) {
  padding-top: 56px !important;
}
.ported-style-page .skip-link {
  position: fixed;
  top: -100%;
  left: 16px;
  z-index: 10000;
  background: #09090b;
  color: #fff;
  padding: 12px 24px;
  border-radius: 10px;
  font-weight: 600;
  font-size: 0.95rem;
  text-decoration: none;
  transition: top 0.2s ease;
}
.ported-style-page .skip-link:focus,
.ported-style-page .skip-link:focus-visible {
  top: 16px;
}
.ported-style-page [id] {
  scroll-margin-top: 72px;
}
.ported-style-page .site-nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: color-mix(in srgb, var(--bg, var(--paper, var(--surface, var(--canvas, #f4f4f5)))) 90%, transparent);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid color-mix(in srgb, currentColor 14%, transparent);
  padding: 0 24px;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  color: inherit;
}
.ported-style-page .site-nav__inner {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 56px;
}
.ported-style-page .site-nav__logo {
  font-family: 'Space Grotesk', sans-serif;
  font-weight: 700;
  font-size: 1.1rem;
  color: inherit;
  text-decoration: none;
  letter-spacing: -0.02em;
}
.ported-style-page .site-nav__links {
  display: flex;
  gap: 16px;
  list-style: none;
  margin: 0;
  padding: 0;
}
.ported-style-page .site-nav__links a {
  color: inherit;
  opacity: 0.7;
  text-decoration: none;
  font-size: 0.875rem;
  font-weight: 500;
  padding: 6px 14px;
  border-radius: 9999px;
  transition: opacity 0.2s ease, background 0.2s ease;
}
.ported-style-page .site-nav__links a:hover,
.ported-style-page .site-nav__links a:focus-visible {
  opacity: 1;
  background: color-mix(in srgb, currentColor 12%, transparent);
}
.ported-style-page .nav-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}
.ported-style-page .theme-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border: 1px solid color-mix(in srgb, currentColor 22%, transparent);
  border-radius: 50%;
  background: color-mix(in srgb, currentColor 8%, transparent);
  color: inherit;
  opacity: 0.78;
  cursor: pointer;
  transition: background 0.2s ease, opacity 0.2s ease, border-color 0.2s ease, transform 0.3s ease;
  flex-shrink: 0;
  padding: 0;
  font-family: inherit;
}
.ported-style-page .theme-toggle:hover {
  border-color: color-mix(in srgb, currentColor 40%, transparent);
  background: color-mix(in srgb, currentColor 14%, transparent);
  color: inherit;
  opacity: 1;
  transform: rotate(15deg);
}
.ported-style-page .mode-toggle {
  position: relative;
  overflow: hidden;
  width: auto;
  min-width: 88px;
  gap: 0;
  padding: 0 12px;
  border-radius: 999px;
}
.ported-style-page .mode-toggle:hover {
  transform: none;
}
.ported-style-page .mode-toggle__state {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
}
.ported-style-page .mode-toggle__state--to-dark {
  display: none;
}
.ported-style-page .mode-toggle__icon {
  position: static;
  flex-shrink: 0;
  transition: opacity 0.2s ease, transform 0.3s ease;
}
.ported-style-page .mode-toggle__icon--sun {
  transform: none;
  opacity: 1;
}
.ported-style-page .mode-toggle__text {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  line-height: 1;
  text-transform: uppercase;
}
.ported-style-page[data-color-mode="light"] .mode-toggle__state--to-light {
  display: none;
}
.ported-style-page[data-color-mode="light"] .mode-toggle__state--to-dark {
  display: inline-flex;
}
.ported-style-page[data-color-mode="light"] .mode-toggle__icon--moon {
  opacity: 1;
  transform: none;
}
.ported-style-page[data-color-mode="light"] .mode-toggle__icon--sun {
  opacity: 1;
  transform: none;
}
.ported-style-page .lang-dropdown {
  position: relative;
  flex-shrink: 0;
}
.ported-style-page .lang-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  height: 36px;
  padding: 0 12px;
  border: 1px solid color-mix(in srgb, currentColor 22%, transparent);
  border-radius: 9999px;
  background: color-mix(in srgb, currentColor 8%, transparent);
  color: inherit;
  opacity: 0.86;
  cursor: pointer;
  transition: background 0.2s ease, opacity 0.2s ease, border-color 0.2s ease;
  font-family: 'Space Grotesk', sans-serif;
  font-size: 0.8rem;
  font-weight: 600;
  letter-spacing: 0.04em;
}
.ported-style-page .lang-toggle::after {
  content: '';
  display: inline-block;
  width: 0;
  height: 0;
  border-left: 4px solid transparent;
  border-right: 4px solid transparent;
  border-top: 4px solid currentColor;
  margin-left: 2px;
  transition: transform 0.2s;
}
.ported-style-page .lang-dropdown.open .lang-toggle::after {
  transform: rotate(180deg);
}
.ported-style-page .lang-toggle:hover {
  border-color: color-mix(in srgb, currentColor 42%, transparent);
  background: color-mix(in srgb, currentColor 16%, transparent);
  color: inherit;
  opacity: 1;
}
.ported-style-page .lang-menu {
  display: none;
  position: absolute;
  top: calc(100% + 6px);
  right: 0;
  min-width: 140px;
  padding: 6px;
