/* ============================================
   HOLOGRAPHIC FLUID · PALETTE SWITCHER
   ============================================ */
.ported-style-page--holographic-fluid .hf-palette-switch {
    position: relative;
    z-index: 4;
    display: grid;
    grid-template-columns: auto 1fr auto;
    gap: 18px;
    align-items: center;
    margin: 0 0 28px;
    padding: 12px 18px;
    border-radius: 999px;
    background:
        linear-gradient(135deg, rgba(var(--c1-rgb), 0.06), rgba(var(--c4-rgb), 0.04) 60%, transparent),
        rgba(11, 15, 25, 0.55);
    border: 1px solid var(--panel-border);
    backdrop-filter: blur(18px) saturate(140%);
    -webkit-backdrop-filter: blur(18px) saturate(140%);
    box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.06),
        0 18px 50px rgba(0, 0, 0, 0.32),
        0 0 32px rgba(var(--c1-rgb), 0.08);
    transition: box-shadow 0.45s ease, border-color 0.45s ease, background 0.45s ease;
}
