    align-items: center;
    gap: 9px;
    font-family: 'Outfit', 'Noto Sans KR', sans-serif;
    font-size: 0.7rem;
    font-weight: 500;
    letter-spacing: 0.22em;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.55);
    white-space: nowrap;
}
.ported-style-page--holographic-fluid .hf-palette-switch__dot {
    width: 8px;
    height: 8px;
    border-radius: 999px;
    background: linear-gradient(135deg, var(--c1), var(--c4));
    box-shadow: 0 0 10px rgba(var(--c1-rgb), 0.6), 0 0 18px rgba(var(--c4-rgb), 0.4);
    animation: hf-palette-pulse 2.6s ease-in-out infinite;
