}
.ported-style-page--holographic-fluid .hf-palette-switch__hex:last-of-type {
    color: rgba(var(--c4-rgb), 0.95);
    text-shadow: 0 0 8px rgba(var(--c4-rgb), 0.32);
}
.ported-style-page--holographic-fluid .hf-palette-switch__plus {
