    }
    .ported-style-page--holographic-fluid .hf-palette-switch__readout {
        justify-content: center;
    }
}

/* MIST palette is pastel — white text on var(--c1)→var(--c3) gradient pills disappears.
   Switch those gradient backgrounds to dark text + heavier weight only when MIST is active. */
.ported-style-page--holographic-fluid[data-palette="mist"] .holo-btn--solid,
.ported-style-page--holographic-fluid[data-palette="mist"] .holo-badge--gradient,
.ported-style-page--holographic-fluid[data-palette="mist"] .price-card__badge,
.ported-style-page--holographic-fluid[data-palette="mist"] .price-card--featured .price-btn {
    color: #0b0f19;
    font-weight: 700;
    text-shadow: none;
}

/* ============================================
   HOLOGRAPHIC FLUID · EXTENDED COMPONENTS
   ============================================ */

.ported-style-page--holographic-fluid .section-header {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 16px;
    margin-bottom: 18px;
    flex-wrap: wrap;
}
.ported-style-page--holographic-fluid .section-header h2 {
    margin: 0;
    font-size: 1.5rem;
    font-weight: 500;
    letter-spacing: -0.01em;
}
.ported-style-page--holographic-fluid .section-header .section-sub {
    font-size: 0.78rem;
    opacity: 0.55;
    font-weight: 300;
}

.ported-style-page--holographic-fluid .glass-panel {
    padding: 32px;
    border-radius: 28px;
    background:
        linear-gradient(var(--panel-scrim), var(--panel-scrim)),
        var(--panel-tint);
    border: 1px solid var(--panel-border);
    backdrop-filter: blur(18px);
    -webkit-backdrop-filter: blur(18px);
    margin-bottom: 40px;
    animation: ported-holographic-fluid-fadeIn 1.6s ease-out;
    position: relative;
}

/* ===== Button Lab ===== */
.ported-style-page--holographic-fluid .btn-lab {
    display: flex;
    flex-wrap: wrap;
    gap: 14px;
    align-items: center;
}
.ported-style-page--holographic-fluid .holo-btn {
    position: relative;
    padding: 13px 26px;
    border-radius: 9999px;
    font: 500 0.92rem/1 'Outfit', 'Noto Sans KR', sans-serif;
    cursor: pointer;
    border: none;
    color: #fff;
    transition: transform .25s ease, box-shadow .25s ease, filter .25s ease, background .25s ease;
    letter-spacing: 0.01em;
    display: inline-flex;
    align-items: center;
    gap: 8px;
}
.ported-style-page--holographic-fluid .holo-btn svg { width: 14px; height: 14px; }
.ported-style-page--holographic-fluid .holo-btn--solid {
    background: linear-gradient(135deg, var(--c1), var(--c3));
    box-shadow: 0 10px 28px rgba(255, 126, 179, .35), 0 18px 42px rgba(79, 172, 254, .25);
}
.ported-style-page--holographic-fluid .holo-btn--solid:hover { transform: translateY(-2px); filter: brightness(1.12); }
.ported-style-page--holographic-fluid .holo-btn--ghost {
    background: rgba(255, 255, 255, .04);
    border: 1px solid rgba(255, 255, 255, .18);
    backdrop-filter: blur(14px);
}
.ported-style-page--holographic-fluid .holo-btn--ghost:hover { background: rgba(255, 255, 255, .1); transform: translateY(-2px); }
.ported-style-page--holographic-fluid .holo-btn--shimmer {
    color: #0b0f19;
    font-weight: 600;
    background: linear-gradient(110deg, var(--c1), var(--c2), var(--c3), var(--c4), var(--c1));
    background-size: 300% 100%;
    animation: ported-holographic-fluid-shimmerSlide 4.5s linear infinite;
    box-shadow: 0 8px 24px rgba(0, 242, 254, .25);
}
.ported-style-page--holographic-fluid .holo-btn--shimmer:hover { transform: translateY(-2px); }
@keyframes ported-holographic-fluid-shimmerSlide { to { background-position: -300% 0; } }
.ported-style-page--holographic-fluid .holo-btn--outline {
    background: transparent;
    position: relative;
    isolation: isolate;
}
.ported-style-page--holographic-fluid .holo-btn--outline::before {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: 9999px;
    padding: 1.5px;
    background: linear-gradient(135deg, var(--c1), var(--c4));
    -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
    mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
    -webkit-mask-composite: xor;
    mask-composite: exclude;
    pointer-events: none;
}
.ported-style-page--holographic-fluid .holo-btn--outline:hover { background: rgba(255, 255, 255, .04); }
.ported-style-page--holographic-fluid .holo-btn--neon {
    background: rgba(0, 0, 0, .25);
    border: 1px solid rgba(0, 242, 254, .45);
    color: #c8faff;
    text-shadow: 0 0 12px rgba(0, 242, 254, .8);
    box-shadow: 0 0 14px rgba(0, 242, 254, .35), inset 0 0 14px rgba(0, 242, 254, .15);
}
.ported-style-page--holographic-fluid .holo-btn--neon:hover { box-shadow: 0 0 22px rgba(0, 242, 254, .6), inset 0 0 22px rgba(0, 242, 254, .25); }
.ported-style-page--holographic-fluid .holo-btn--icon-only {
    width: 42px; height: 42px; padding: 0;
    justify-content: center;
    background: rgba(255, 255, 255, .05);
    border: 1px solid rgba(255, 255, 255, .12);
}
.ported-style-page--holographic-fluid .holo-btn--icon-only:hover { background: rgba(255, 255, 255, .12); transform: rotate(-8deg); }
.ported-style-page--holographic-fluid .holo-btn--icon-only svg { width: 16px; height: 16px; }

/* ===== Aurora Tabs ===== */
.ported-style-page--holographic-fluid .aurora-tabs {
    display: flex;
    gap: 4px;
    padding: 6px;
    background: rgba(0, 0, 0, .25);
    border-radius: 9999px;
    border: 1px solid rgba(255, 255, 255, .06);
    margin-bottom: 24px;
    width: fit-content;
    max-width: 100%;
    flex-wrap: wrap;
}
.ported-style-page--holographic-fluid .aurora-tabs button {
    position: relative;
    padding: 9px 20px;
    border: none;
    background: transparent;
    color: rgba(255, 255, 255, .65);
    font: 500 0.83rem/1 'Outfit', 'Noto Sans KR', sans-serif;
    border-radius: 9999px;
    cursor: pointer;
    transition: color .25s ease;
    white-space: nowrap;
}
.ported-style-page--holographic-fluid .aurora-tabs button.active {
    color: #fff;
    background: linear-gradient(135deg, rgba(255, 126, 179, .25), rgba(79, 172, 254, .25));
    box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .12), 0 6px 18px rgba(79, 172, 254, .2);
}
.ported-style-page--holographic-fluid .aurora-tabs button:not(.active):hover { color: #fff; }

.ported-style-page--holographic-fluid .tab-panel {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 16px;
    margin-top: 8px;
}
.ported-style-page--holographic-fluid .tab-tile {
    padding: 18px;
    border-radius: 16px;
    background: rgba(255, 255, 255, .04);
    border: 1px solid rgba(255, 255, 255, .06);
}
.ported-style-page--holographic-fluid .tab-tile__head {
    font-size: 0.7rem;
    opacity: 0.5;
    text-transform: uppercase;
    letter-spacing: 0.15em;
    margin-bottom: 8px;
}
.ported-style-page--holographic-fluid .tab-tile__val {
    font-size: 1.6rem;
    font-weight: 500;
    background: linear-gradient(135deg, var(--c1), var(--c4));
    background-clip: text;
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}
.ported-style-page--holographic-fluid .tab-tile__delta {
    font-size: 0.72rem;
    opacity: 0.7;
    margin-top: 4px;
    font-weight: 300;
}

/* ===== Form Lab ===== */
.ported-style-page--holographic-fluid .form-lab {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 20px;
}
.ported-style-page--holographic-fluid .form-field { display: flex; flex-direction: column; gap: 8px; }
.ported-style-page--holographic-fluid .form-field__label {
    font-size: 0.72rem;
    opacity: 0.6;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    font-weight: 500;
}
.ported-style-page--holographic-fluid .holo-input {
    position: relative;
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 12px 16px;
    border-radius: 14px;
    background: rgba(0, 0, 0, .25);
    border: 1px solid rgba(255, 255, 255, .08);
    transition: border-color .25s ease, box-shadow .25s ease;
}
.ported-style-page--holographic-fluid .holo-input:focus-within {
    border-color: rgba(0, 242, 254, .45);
    box-shadow: 0 0 0 4px rgba(0, 242, 254, .12);
}
.ported-style-page--holographic-fluid .holo-input svg { width: 16px; height: 16px; opacity: 0.55; flex-shrink: 0; }
.ported-style-page--holographic-fluid .holo-input input {
    background: transparent;
    border: none;
    outline: none;
    color: #fff;
    font: 400 0.9rem/1 'Outfit', 'Noto Sans KR', sans-serif;
    width: 100%;
}
.ported-style-page--holographic-fluid .holo-input input::placeholder { color: rgba(255, 255, 255, .35); }
.ported-style-page--holographic-fluid .holo-select {
    position: relative;
    padding: 12px 40px 12px 16px;
    border-radius: 14px;
    background: rgba(0, 0, 0, .25);
    border: 1px solid rgba(255, 255, 255, .08);
    color: #fff;
    font: 400 0.9rem/1 'Outfit', 'Noto Sans KR', sans-serif;
    cursor: pointer;
    appearance: none;
    background-image: linear-gradient(135deg, transparent 50%, rgba(255, 255, 255, .5) 50%, rgba(255, 255, 255, .5) 60%, transparent 60%),
                      linear-gradient(45deg, transparent 50%, rgba(255, 255, 255, .5) 50%, rgba(255, 255, 255, .5) 60%, transparent 60%);
    background-position: calc(100% - 18px) 50%, calc(100% - 13px) 50%;
    background-size: 6px 6px, 6px 6px;
    background-repeat: no-repeat;
}
.ported-style-page--holographic-fluid .holo-toggle {
    display: inline-flex;
    align-items: center;
    gap: 12px;
    cursor: pointer;
    padding: 6px 4px;
}
.ported-style-page--holographic-fluid .holo-toggle__track {
    width: 46px; height: 26px;
    border-radius: 9999px;
    background: rgba(255, 255, 255, .08);
    position: relative;
    transition: background .3s ease;
    flex-shrink: 0;
}
.ported-style-page--holographic-fluid .holo-toggle__thumb {
    position: absolute;
    top: 3px; left: 3px;
    width: 20px; height: 20px;
    border-radius: 50%;
    background: #fff;
    box-shadow: 0 2px 6px rgba(0, 0, 0, .25);
    transition: left .3s ease, background .3s ease, box-shadow .3s ease;
}
.ported-style-page--holographic-fluid .holo-toggle.on .holo-toggle__track {
    background: linear-gradient(110deg, var(--c1), var(--c3));
    box-shadow: 0 0 18px rgba(255, 126, 179, .35);
}
.ported-style-page--holographic-fluid .holo-toggle.on .holo-toggle__thumb { left: 23px; }
.ported-style-page--holographic-fluid .holo-toggle__caption { font-size: 0.85rem; opacity: 0.85; font-weight: 300; }

.ported-style-page--holographic-fluid .holo-slider {
    position: relative;
    height: 28px;
    display: flex;
    align-items: center;
}
.ported-style-page--holographic-fluid .holo-slider__track {
    height: 6px;
    width: 100%;
    border-radius: 9999px;
    background: rgba(255, 255, 255, .08);
    position: relative;
    overflow: hidden;
}
.ported-style-page--holographic-fluid .holo-slider__fill {
    position: absolute;
    top: 0; left: 0;
    height: 100%;
    width: 65%;
    background: linear-gradient(90deg, var(--c1), var(--c2), var(--c3), var(--c4));
    border-radius: 9999px;
    box-shadow: 0 0 14px rgba(255, 126, 179, .45);
}
.ported-style-page--holographic-fluid .holo-slider__thumb {
    position: absolute;
    top: 50%; left: 65%;
    transform: translate(-50%, -50%);
    width: 16px; height: 16px;
    border-radius: 50%;
    background: #fff;
    border: 2px solid rgba(255, 255, 255, .8);
    box-shadow: 0 0 14px rgba(0, 242, 254, .65), 0 0 0 6px rgba(0, 242, 254, .12);
}
.ported-style-page--holographic-fluid .holo-slider__values {
    display: flex;
    justify-content: space-between;
    font-size: 0.72rem;
    font-family: monospace;
    opacity: 0.55;
    margin-top: 8px;
}

/* ===== Stats ===== */
.ported-style-page--holographic-fluid .stats-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 16px;
}
.ported-style-page--holographic-fluid .stat-card {
    padding: 22px;
    border-radius: 20px;
    background: rgba(255, 255, 255, .03);
    border: 1px solid rgba(255, 255, 255, .07);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    position: relative;
    overflow: hidden;
    transition: transform .3s ease;
}
.ported-style-page--holographic-fluid .stat-card:hover { transform: translateY(-4px); }
.ported-style-page--holographic-fluid .stat-card::after {
    content: '';
    position: absolute;
    top: -40%; right: -40%;
    width: 140px; height: 140px;
    border-radius: 50%;
    filter: blur(40px);
    opacity: .5;
    pointer-events: none;
}
.ported-style-page--holographic-fluid .stat-card:nth-child(1)::after { background: var(--c1); }
.ported-style-page--holographic-fluid .stat-card:nth-child(2)::after { background: var(--c2); }
.ported-style-page--holographic-fluid .stat-card:nth-child(3)::after { background: var(--c3); }
.ported-style-page--holographic-fluid .stat-card:nth-child(4)::after { background: var(--c4); }
.ported-style-page--holographic-fluid .stat-card__label {
    font-size: 0.7rem;
    opacity: 0.6;
    text-transform: uppercase;
    letter-spacing: 0.13em;
    margin-bottom: 10px;
    font-weight: 500;
    position: relative;
    z-index: 1;
}
.ported-style-page--holographic-fluid .stat-card__value {
    font-size: 2.4rem;
    font-weight: 500;
    line-height: 1;
    letter-spacing: -0.02em;
    background: linear-gradient(135deg, #fff, rgba(255, 255, 255, .55));
    background-clip: text;
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    position: relative;
    z-index: 1;
}
.ported-style-page--holographic-fluid .stat-card__delta {
    margin-top: 8px;
    font-size: 0.76rem;
    font-weight: 400;
    display: inline-flex;
    align-items: center;
    gap: 4px;
    color: rgba(255, 255, 255, .75);
    position: relative;
    z-index: 1;
}
.ported-style-page--holographic-fluid .stat-card__delta--up { color: #7df0ff; }
.ported-style-page--holographic-fluid .stat-card__delta--down { color: #ffb0c8; }
.ported-style-page--holographic-fluid .stat-card__spark {
    margin-top: 14px;
    height: 24px;
    display: flex;
    align-items: flex-end;
    gap: 3px;
    position: relative;
    z-index: 1;
}
.ported-style-page--holographic-fluid .stat-card__spark span {
    flex: 1;
    border-radius: 2px;
    background: linear-gradient(180deg, var(--c4), var(--c3));
    opacity: 0.7;
}

/* ===== Loaders ===== */
.ported-style-page--holographic-fluid .loader-rack {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
    gap: 18px;
}
.ported-style-page--holographic-fluid .loader-cell {
    padding: 28px 18px 22px;
    border-radius: 20px;
    background: rgba(255, 255, 255, .03);
    border: 1px solid rgba(255, 255, 255, .07);
    text-align: center;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 18px;
}
.ported-style-page--holographic-fluid .loader-cell__label {
    font-size: 0.72rem;
    opacity: 0.6;
    text-transform: uppercase;
    letter-spacing: 0.12em;
}
.ported-style-page--holographic-fluid .ld-ring {
    width: 44px; height: 44px;
    border-radius: 50%;
    background: conic-gradient(from 0deg, transparent, var(--c1), var(--c2), var(--c3), var(--c4), transparent);
    -webkit-mask: radial-gradient(closest-side, transparent 62%, #000 64%);
    mask: radial-gradient(closest-side, transparent 62%, #000 64%);
    animation: ported-holographic-fluid-ldRingSpin 1.4s linear infinite;
}
@keyframes ported-holographic-fluid-ldRingSpin { to { transform: rotate(360deg); } }
.ported-style-page--holographic-fluid .ld-dots { display: flex; gap: 8px; }
.ported-style-page--holographic-fluid .ld-dots span {
    width: 10px; height: 10px;
    border-radius: 50%;
    background: linear-gradient(135deg, var(--c1), var(--c4));
    animation: ported-holographic-fluid-ldDots 1.1s ease-in-out infinite;
}
.ported-style-page--holographic-fluid .ld-dots span:nth-child(2) { animation-delay: 0.15s; }
.ported-style-page--holographic-fluid .ld-dots span:nth-child(3) { animation-delay: 0.3s; }
@keyframes ported-holographic-fluid-ldDots {
    0%, 100% { transform: scale(0.5); opacity: 0.4; }
    50% { transform: scale(1.1); opacity: 1; box-shadow: 0 0 12px rgba(255, 126, 179, .65); }
}
.ported-style-page--holographic-fluid .ld-wave { display: flex; gap: 4px; align-items: flex-end; height: 44px; }
.ported-style-page--holographic-fluid .ld-wave span {
    width: 5px;
    border-radius: 3px;
    background: linear-gradient(180deg, var(--c4), var(--c1));
    animation: ported-holographic-fluid-ldWave 1.1s ease-in-out infinite;
}
.ported-style-page--holographic-fluid .ld-wave span:nth-child(1) { animation-delay: 0s; }
.ported-style-page--holographic-fluid .ld-wave span:nth-child(2) { animation-delay: 0.1s; }
.ported-style-page--holographic-fluid .ld-wave span:nth-child(3) { animation-delay: 0.2s; }
.ported-style-page--holographic-fluid .ld-wave span:nth-child(4) { animation-delay: 0.3s; }
.ported-style-page--holographic-fluid .ld-wave span:nth-child(5) { animation-delay: 0.4s; }
@keyframes ported-holographic-fluid-ldWave {
    0%, 100% { height: 8px; }
    50% { height: 44px; }
}
.ported-style-page--holographic-fluid .ld-ripple {
    position: relative;
    width: 44px; height: 44px;
}
.ported-style-page--holographic-fluid .ld-ripple span {
    position: absolute;
    inset: 0;
    border-radius: 50%;
    border: 2px solid var(--c3);
    animation: ported-holographic-fluid-ldRipple 1.8s cubic-bezier(0, 0.2, 0.8, 1) infinite;
    opacity: 0;
}
.ported-style-page--holographic-fluid .ld-ripple span:nth-child(2) { animation-delay: -0.9s; border-color: var(--c1); }
@keyframes ported-holographic-fluid-ldRipple {
    0% { transform: scale(0.1); opacity: 1; }
    100% { transform: scale(1.4); opacity: 0; }
}

/* ===== Badges ===== */
.ported-style-page--holographic-fluid .badge-row {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    align-items: center;
}
.ported-style-page--holographic-fluid .holo-badge {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 6px 12px;
    border-radius: 9999px;
    font-size: 0.75rem;
    font-weight: 500;
    letter-spacing: 0.01em;
}
.ported-style-page--holographic-fluid .holo-badge--gradient {
    background: linear-gradient(110deg, var(--c1), var(--c3));
    color: #fff;
    box-shadow: 0 0 14px rgba(255, 126, 179, .35);
}
.ported-style-page--holographic-fluid .holo-badge--neon {
    background: rgba(0, 242, 254, .12);
    color: #b8f6ff;
    border: 1px solid rgba(0, 242, 254, .35);
    text-shadow: 0 0 8px rgba(0, 242, 254, .5);
}
.ported-style-page--holographic-fluid .holo-badge--glass {
    background: rgba(255, 255, 255, .06);
    color: #fff;
    border: 1px solid rgba(255, 255, 255, .14);
    backdrop-filter: blur(10px);
}
.ported-style-page--holographic-fluid .holo-badge--coral {
    background: rgba(255, 117, 140, .18);
    color: #ffbecb;
    border: 1px solid rgba(255, 117, 140, .35);
}
.ported-style-page--holographic-fluid .holo-badge--dot::before {
    content: '';
    width: 6px; height: 6px;
    border-radius: 50%;
    background: currentColor;
    box-shadow: 0 0 8px currentColor;
    animation: ported-holographic-fluid-badgeDot 1.4s ease-in-out infinite;
}
@keyframes ported-holographic-fluid-badgeDot {
    0%, 100% { opacity: 1; transform: scale(1); }
    50% { opacity: 0.5; transform: scale(0.7); }
}

/* ===== Live Session ===== */
.ported-style-page--holographic-fluid .live-grid {
    display: grid;
    grid-template-columns: 1.4fr 1fr;
    gap: 20px;
}
@media (max-width: 720px) {
    .ported-style-page--holographic-fluid .live-grid { grid-template-columns: 1fr; }
