        box-sizing: border-box;
      }
.ported-style-page--neon-drift {
        margin: 0;
        color: var(--text);
        font-family: 'IBM Plex Sans KR', sans-serif;
        background:
          radial-gradient(circle at 18% 22%, rgba(var(--accent-rgb), 0.35), transparent 34%),
          radial-gradient(circle at 78% 8%, rgba(var(--accent-rgb), 0.28), transparent 36%),
          radial-gradient(circle at 56% 86%, rgba(var(--accent-2-rgb), 0.24), transparent 38%),
