/* ── interface protocols: mini visuals per rule ── */
.ported-style-page--neon-drift .nd-tips {
  gap: 14px;
}
.ported-style-page--neon-drift .nd-tip {
  min-height: 188px;
  padding: 22px 18px 18px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  position: relative;
}
.ported-style-page--neon-drift .nd-tip__visual {
  height: 56px;
  border-radius: 12px;
  border: 1px solid rgba(129, 156, 170, 0.14);
  background:
    repeating-linear-gradient(90deg, rgba(220, 232, 238, 0.02) 0 1px, transparent 1px 32px),
    rgba(255, 255, 255, 0.012);
