  height: 2px;
  border-radius: 1px;
}
.ported-style-page--neon-drift .nd-tip-row--chrome { background: rgba(var(--accent-rgb), 0.78); width: 50%; box-shadow: 0 0 6px rgba(var(--accent-rgb), 0.32); }
.ported-style-page--neon-drift .nd-tip-row--data { background: rgba(var(--accent-2-rgb), 0.68); width: 86%; height: 1px; }
.ported-style-page--neon-drift .nd-tip-row--copy { background: rgba(220, 232, 238, 0.32); width: 70%; height: 1px; }
/* Rule 03: compact frame */
.ported-style-page--neon-drift .nd-tip__visual--frame {
  padding: 0;
}
.ported-style-page--neon-drift .nd-tip-frame {
  position: relative;
  width: 80%;
  height: 36px;
  border: 1px solid rgba(var(--accent-rgb), 0.42);
  border-radius: 6px;
  box-shadow: inset 0 0 8px rgba(var(--accent-rgb), 0.08), 0 0 8px rgba(var(--accent-rgb), 0.12);
