}
.ported-style-page--neon-drift .nd-neon-sign--coral {
  color: rgba(var(--accent-2-rgb), 0.94);
  background: rgba(var(--accent-2-rgb), 0.045);
}

/* ── responsive ── */
@media (max-width: 940px) {
  .ported-style-page--neon-drift .nd-product-panel {
    max-width: 100%;
  }
  .ported-style-page--neon-drift .nd-tubes {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .ported-style-page--neon-drift .nd-status-stack {
