  }
}
@media (max-width: 640px) {
  .ported-style-page--neon-drift .nd-product-panel__top {
    padding-right: 14px;
    height: auto;
    min-height: 50px;
    flex-wrap: wrap;
  }
  .ported-style-page--neon-drift .nd-product-panel__live {
    position: static;
    transform: none;
    margin-left: auto;
  }
  .ported-style-page--neon-drift .nd-product-rail {
    grid-template-columns: repeat(5, minmax(0, 1fr));
  }
  .ported-style-page--neon-drift .nd-tubes {
