  }
  .ported-style-page--neon-drift .nd-gauge__viz--dots {
    grid-template-columns: repeat(12, 1fr);
  }
}
@media (prefers-reduced-motion: reduce) {
  .ported-style-page--neon-drift .nd-product-panel__live em,
  .ported-style-page--neon-drift .nd-status-pulse,
  .ported-style-page--neon-drift .nd-gauge__scan-beam,
