.ported-style-page--terminal-core .net-panel__head { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 12px; font-size: 0.78rem; color: var(--warn); font-weight: 700; letter-spacing: 0.08em; }
.ported-style-page--terminal-core .net-panel__head span:last-child { color: var(--ink); font-size: 1.2rem; text-shadow: 0 0 10px rgba(185, 255, 190, .4); }
.ported-style-page--terminal-core .net-bars { display: flex; align-items: flex-end; gap: 3px; height: 60px; }
.ported-style-page--terminal-core .net-bars span { flex: 1; background: linear-gradient(180deg, var(--ink), #1e4f22); min-width: 4px; border-radius: 1px 1px 0 0; opacity: 0.85; animation: ported-terminal-core-netBar 1.6s ease-in-out infinite; transform-origin: bottom; }
@keyframes ported-terminal-core-netBar { 0%, 100% { transform: scaleY(0.4); } 50% { transform: scaleY(1); box-shadow: 0 0 8px var(--ink); } }
.ported-style-page--terminal-core .log-feed { border: 1px solid var(--line); background: #051509; border-radius: 6px; padding: 14px; max-height: 200px; overflow-y: auto; font-family: 'JetBrains Mono', monospace; }
.ported-style-page--terminal-core .log-line { display: flex; gap: 8px; font-size: 0.76rem; line-height: 1.6; padding: 2px 0; }
.ported-style-page--terminal-core .log-time { color: #4a7a52; flex-shrink: 0; }
.ported-style-page--terminal-core .log-level { flex-shrink: 0; width: 50px; font-weight: 700; }
.ported-style-page--terminal-core .log-level--info { color: var(--ink); }
.ported-style-page--terminal-core .log-level--ok { color: var(--warn); }
.ported-style-page--terminal-core .log-level--warn { color: #ffd75c; }
.ported-style-page--terminal-core .log-level--err { color: #ff9c7a; }
.ported-style-page--terminal-core .log-msg { color: #b9ffbe; opacity: 0.9; }

.ported-style-page--terminal-core .plan-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 14px; }
.ported-style-page--terminal-core .plan-card { padding: 22px 20px; border: 1px solid var(--line); border-radius: 8px; background: #0a170c; position: relative; }
.ported-style-page--terminal-core .plan-card--featured { border-color: var(--warn); background: #0e1f0b; box-shadow: 0 0 0 1px var(--warn), 0 0 24px rgba(212, 255, 92, .15); }
.ported-style-page--terminal-core .plan-card__name { font-size: 0.78rem; text-transform: uppercase; letter-spacing: 0.16em; color: var(--warn); font-weight: 700; margin-bottom: 8px; }
.ported-style-page--terminal-core .plan-card__name::before { content: '[ '; opacity: 0.5; }
.ported-style-page--terminal-core .plan-card__name::after { content: ' ]'; opacity: 0.5; }
.ported-style-page--terminal-core .plan-card__price { font-size: 2rem; font-weight: 800; color: var(--ink); text-shadow: 0 0 12px rgba(185, 255, 190, .35); line-height: 1; letter-spacing: -0.02em; margin-bottom: 4px; }
.ported-style-page--terminal-core .plan-card__price small { font-size: 0.8rem; color: #6fa37a; font-weight: 400; }
.ported-style-page--terminal-core .plan-card__cap { font-size: 0.75rem; color: #6fa37a; margin-bottom: 18px; }
.ported-style-page--terminal-core .plan-card ul { list-style: none; padding: 0; margin: 0 0 20px; display: flex; flex-direction: column; gap: 8px; }
.ported-style-page--terminal-core .plan-card li { font-size: 0.78rem; color: var(--ink); display: flex; gap: 8px; align-items: center; }
.ported-style-page--terminal-core .plan-card li::before { content: '+'; color: var(--warn); font-weight: 700; }
.ported-style-page--terminal-core .plan-card li.off { opacity: 0.4; }
.ported-style-page--terminal-core .plan-card li.off::before { content: '-'; color: #6fa37a; }
.ported-style-page--terminal-core .plan-card__btn { width: 100%; padding: 10px; background: transparent; border: 1px solid var(--line); color: var(--ink); font: 700 0.8rem 'JetBrains Mono', monospace; cursor: pointer; letter-spacing: 0.06em; text-transform: uppercase; transition: all .15s; }
.ported-style-page--terminal-core .plan-card__btn:hover { border-color: var(--warn); background: rgba(212, 255, 92, .08); color: var(--warn); }
.ported-style-page--terminal-core .plan-card--featured .plan-card__btn { background: var(--warn); color: #0a190c; border-color: var(--warn); box-shadow: 0 0 14px rgba(212, 255, 92, .35); }
.ported-style-page--terminal-core .plan-card--featured .plan-card__btn:hover { background: #ebffab; color: #0a190c; }

.ported-style-page--terminal-core .changelog { display: flex; flex-direction: column; gap: 12px; }
.ported-style-page--terminal-core .changelog-entry { display: grid; grid-template-columns: 110px 1fr; gap: 16px; padding: 12px 14px; border-left: 2px solid var(--line); background: #0a170c; }
.ported-style-page--terminal-core .changelog-entry--live { border-left-color: var(--warn); box-shadow: inset 2px 0 12px rgba(212, 255, 92, .15); }
.ported-style-page--terminal-core .changelog-entry__date { font-size: 0.75rem; color: var(--warn); font-weight: 700; letter-spacing: 0.05em; }
.ported-style-page--terminal-core .changelog-entry__date small { display: block; color: #6fa37a; font-size: 0.68rem; font-weight: 400; margin-top: 2px; letter-spacing: 0.04em; }
.ported-style-page--terminal-core .changelog-entry__title { font-size: 0.88rem; font-weight: 700; color: var(--ink); margin-bottom: 4px; }
.ported-style-page--terminal-core .changelog-entry__title::before { content: '> '; color: var(--warn); }
.ported-style-page--terminal-core .changelog-entry__body { font-size: 0.78rem; color: #8fc996; line-height: 1.65; }
@media (max-width: 640px) {
    .ported-style-page--terminal-core .changelog-entry { grid-template-columns: 1fr; gap: 6px; }
    .ported-style-page--terminal-core .term-section-block { padding: 18px 14px; }
}

/* ════════════════════════════════════════════════════════════════
   midnight-noir — quiet luxury · black lacquer + antique champagne
   ════════════════════════════════════════════════════════════════ */
.ported-style-page--midnight-noir {
  --bg: #07080B;
  --surface: #0C0E12;
  --surface-2: #121318;
  --surface-3: #17161A;
  --line: rgba(228, 207, 157, 0.12);
  --line-strong: rgba(228, 207, 157, 0.22);
  --line-soft: rgba(228, 207, 157, 0.06);
  --gold: #C6A15B;
  --gold-soft: #D8C28A;
  --gold-dim: #80683B;
  --text: #ECE4D4;
  --text-soft: #C9C2B5;
  --text-muted: #B5AEA1;
  --text-faint: #8C8678;
  --serif: 'Cormorant Garamond', 'Noto Serif KR', Georgia, serif;
  --sans: 'Inter', 'IBM Plex Sans KR', 'Noto Sans KR', -apple-system, BlinkMacSystemFont, sans-serif;
  --mono: 'IBM Plex Mono', 'JetBrains Mono', ui-monospace, monospace;
  --rise: cubic-bezier(0.22, 1, 0.36, 1);
}
.ported-style-page--midnight-noir * { box-sizing: border-box; }
.ported-style-page--midnight-noir {
  margin: 0;
  min-height: 100svh;
  color: var(--text);
  font-family: var(--sans);
  font-feature-settings: 'kern' 1, 'liga' 1;
  background:
    radial-gradient(ellipse 70% 55% at 22% 8%, rgba(228, 207, 157, 0.024), transparent 70%),
    radial-gradient(ellipse 50% 40% at 88% 92%, rgba(228, 207, 157, 0.014), transparent 70%),
    var(--bg);
  background-attachment: fixed;
}
.ported-style-page--midnight-noir::before {
  content: '';
  position: fixed;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  background:
    linear-gradient(180deg, rgba(0,0,0,0) 0%, rgba(0,0,0,0) 75%, rgba(0,0,0,0.18) 100%),
    radial-gradient(ellipse 130% 80% at 50% 50%, transparent 60%, rgba(0,0,0,0.32) 100%);
}
.ported-style-page--midnight-noir::after {
  content: '';
  position: fixed;
  inset: 0;
  z-index: 9998;
  pointer-events: none;
  opacity: 0.012;
  mix-blend-mode: overlay;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
  background-size: 200px 200px;
}
.ported-style-page--midnight-noir > div { position: relative; z-index: 2; }

.ported-style-page--midnight-noir .page {
  width: min(1180px, 92vw);
  margin: 0 auto;
  padding: 0 clamp(20px, 4vw, 48px) clamp(72px, 9vw, 110px);
}

/* === SITE NAV === */
.ported-style-page--midnight-noir .site-nav {
  border: none;
  background: transparent;
  margin-bottom: 0;
  padding-top: clamp(20px, 2.5vw, 32px);
}
.ported-style-page--midnight-noir .site-nav__inner {
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 16px 0;
  border-bottom: 1px solid var(--line);
}
.ported-style-page--midnight-noir .site-nav__logo {
  font-family: var(--serif);
  font-weight: 600;
  font-size: 0.95rem;
  font-style: italic;
  color: var(--text);
  text-decoration: none;
  letter-spacing: 0.04em;
  margin-right: auto;
}
.ported-style-page--midnight-noir .site-nav__logo::before { content: none; }
.ported-style-page--midnight-noir .site-nav__links {
  display: flex;
  gap: clamp(18px, 2.4vw, 32px);
  list-style: none;
  padding: 0;
  margin: 0;
}
.ported-style-page--midnight-noir .site-nav__links a {
  font-family: var(--sans);
  font-size: 0.7rem;
  font-weight: 500;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--text-muted);
  text-decoration: none;
  transition: color 400ms var(--rise);
}
.ported-style-page--midnight-noir .site-nav__links a:hover { color: var(--text); }
.ported-style-page--midnight-noir .nav-actions {
  display: flex;
  gap: 6px;
  align-items: center;
}
.ported-style-page--midnight-noir .nav-burger,
.ported-style-page--midnight-noir .theme-toggle,
.ported-style-page--midnight-noir .lang-toggle {
  background: transparent;
  border: none;
  color: var(--text-muted);
  padding: 6px 10px;
  cursor: pointer;
  font-family: var(--sans);
  font-size: 0.7rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  margin-top: 0;
  transition: color 400ms var(--rise);
}
.ported-style-page--midnight-noir .nav-burger:hover,
.ported-style-page--midnight-noir .theme-toggle:hover,
.ported-style-page--midnight-noir .lang-toggle:hover {
  color: var(--text);
  background: transparent;
}
.ported-style-page--midnight-noir .lang-dropdown { position: relative; }
.ported-style-page--midnight-noir .lang-menu {
  position: absolute;
  top: 100%;
  right: 0;
  margin-top: 6px;
  background: var(--surface);
  border: 1px solid var(--line);
  list-style: none;
  padding: 4px;
  min-width: 120px;
  opacity: 0;
  pointer-events: none;
  transform: translateY(-4px);
  transition: opacity 300ms var(--rise), transform 300ms var(--rise);
  z-index: 50;
}
.ported-style-page--midnight-noir .lang-dropdown.is-open .lang-menu,
.ported-style-page--midnight-noir .lang-dropdown:hover .lang-menu {
  opacity: 1;
  pointer-events: auto;
  transform: translateY(0);
}
.ported-style-page--midnight-noir .lang-menu button {
  width: 100%;
  background: transparent;
  border: none;
  color: var(--text-muted);
  padding: 9px 14px;
  font-size: 0.7rem;
  font-family: var(--sans);
  letter-spacing: 0.1em;
  text-align: left;
  cursor: pointer;
  margin-top: 0;
  transition: color 200ms var(--rise);
}
.ported-style-page--midnight-noir .lang-menu button:hover { color: var(--text); background: transparent; }

.ported-style-page--midnight-noir h1,
.ported-style-page--midnight-noir h2,
.ported-style-page--midnight-noir h3 {
  margin: 0;
  font-family: var(--serif);
  font-feature-settings: 'kern' 1, 'liga' 1, 'dlig' 1;
}

/* === HERO === */
.ported-style-page--midnight-noir .mn-hero {
  display: grid;
  grid-template-columns: minmax(0, 1.7fr) minmax(220px, 1fr);
  column-gap: clamp(40px, 6vw, 96px);
  align-items: end;
  padding: clamp(56px, 8vw, 96px) 0 clamp(40px, 5vw, 64px);
  animation: mn-rise 850ms var(--rise) both;
}
.ported-style-page--midnight-noir .mn-hero__main { max-width: 720px; }
.ported-style-page--midnight-noir .mn-hero__side {
  display: flex;
  flex-direction: column;
  gap: clamp(28px, 3.5vw, 44px);
  padding-bottom: 8px;
}
.ported-style-page--midnight-noir .mn-hero__panel {
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.ported-style-page--midnight-noir .mn-hero__panel-label {
  font-family: var(--sans);
  font-size: 0.6rem;
  font-weight: 500;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--gold);
}
.ported-style-page--midnight-noir .mn-hero__index {
  list-style: none;
  margin: 0;
  padding: 0;
  border-top: 1px solid var(--line);
}
.ported-style-page--midnight-noir .mn-hero__index li {
  display: grid;
  grid-template-columns: 28px 1fr;
  gap: 16px;
  padding: 9px 0;
  border-bottom: 1px solid var(--line-soft);
  font-family: var(--serif);
  font-style: italic;
  font-size: 0.95rem;
  color: var(--text-soft);
  letter-spacing: 0.005em;
  align-items: baseline;
}
.ported-style-page--midnight-noir .mn-hero__index-num {
  font-family: var(--serif);
  font-style: italic;
  font-size: 0.78rem;
  color: var(--gold);
  letter-spacing: 0.04em;
  font-feature-settings: 'tnum' 1;
}
.ported-style-page--midnight-noir .mn-hero__colophon {
  margin: 0;
  font-family: var(--sans);
  font-size: 0.78rem;
  line-height: 1.7;
  color: var(--text-muted);
  letter-spacing: 0.005em;
  padding-top: 12px;
  border-top: 1px solid var(--line);
}
.ported-style-page--midnight-noir .mn-hero__colophon i {
  font-family: var(--serif);
  font-style: italic;
  font-size: 0.92rem;
  color: var(--text);
}
.ported-style-page--midnight-noir .mn-hero__meta {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: clamp(28px, 3.5vw, 44px);
  font-family: var(--sans);
  font-size: 0.62rem;
  font-weight: 500;
  letter-spacing: 0.22em;
  text-transform: uppercase;
}
.ported-style-page--midnight-noir .mn-hero__num {
  color: var(--gold);
  font-feature-settings: 'tnum' 1;
}
.ported-style-page--midnight-noir .mn-hero__rule {
  width: 32px;
  height: 1px;
  background: var(--line-strong);
}
.ported-style-page--midnight-noir .mn-hero__cat { color: var(--text-muted); }
.ported-style-page--midnight-noir .mn-hero__title {
  font-family: var(--serif);
  font-size: clamp(4rem, 10.5vw, 9rem);
  font-weight: 600;
  line-height: 0.92;
  letter-spacing: -0.018em;
  color: var(--text);
  margin: 0;
  display: flex;
  flex-direction: column;
}
.ported-style-page--midnight-noir .mn-hero__title-line { display: block; }
.ported-style-page--midnight-noir .mn-hero__title-line--accent {
  font-style: italic;
  font-weight: 500;
  color: var(--gold-soft);
  letter-spacing: -0.01em;
}
.ported-style-page--midnight-noir .mn-hero__sub {
  font-family: var(--serif);
  font-style: italic;
  font-weight: 400;
  font-size: clamp(1.1rem, 1.7vw, 1.4rem);
  line-height: 1.6;
  color: var(--text-soft);
  margin: clamp(24px, 3vw, 40px) 0 0;
  max-width: 38ch;
  letter-spacing: 0.005em;
}
.ported-style-page--midnight-noir .mn-hero__foot {
  display: flex;
  gap: clamp(40px, 6vw, 72px);
  margin-top: clamp(36px, 5vw, 64px);
  padding-top: clamp(16px, 2vw, 22px);
  border-top: 1px solid var(--line);
  max-width: 420px;
}
.ported-style-page--midnight-noir .mn-hero__foot-item {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.ported-style-page--midnight-noir .mn-hero__foot-label {
  font-family: var(--sans);
  font-size: 0.62rem;
  font-weight: 500;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--text-muted);
}
.ported-style-page--midnight-noir .mn-hero__foot-value {
  font-family: var(--mono);
  font-size: 0.78rem;
  letter-spacing: 0.06em;
  color: var(--text);
  font-feature-settings: 'tnum' 1;
