/* === MANIFESTO === */
.ported-style-page--midnight-noir .mn-manifesto {
  display: grid;
  grid-template-columns: minmax(80px, 1fr) minmax(0, 7fr) minmax(80px, 1fr);
  gap: clamp(20px, 3vw, 40px);
  padding: clamp(48px, 7vw, 88px) 0;
  animation: mn-rise 850ms var(--rise) 100ms both;
}
.ported-style-page--midnight-noir .mn-manifesto__label {
  grid-column: 2;
  font-family: var(--sans);
  font-size: 0.62rem;
  font-weight: 500;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: clamp(16px, 2vw, 24px);
}
.ported-style-page--midnight-noir .mn-manifesto__text {
  grid-column: 2;
  font-family: var(--serif);
  font-style: italic;
  font-weight: 400;
  font-size: clamp(1.6rem, 3.6vw, 2.6rem);
  line-height: 1.42;
  letter-spacing: 0.005em;
  color: var(--text);
  margin: 0;
  max-width: 22ch;
}
.ported-style-page--midnight-noir .mn-manifesto__attr {
  grid-column: 2;
  margin-top: clamp(20px, 2.5vw, 28px);
  font-family: var(--sans);
  font-size: 0.7rem;
  font-weight: 500;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--text-muted);
}

/* === FOUR PRINCIPLES === */
.ported-style-page--midnight-noir .mn-principles {
  padding-top: clamp(40px, 5vw, 64px);
  border-top: 1px solid var(--line);
  animation: mn-rise 850ms var(--rise) 150ms both;
}
.ported-style-page--midnight-noir .mn-principles__head {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: clamp(28px, 4vw, 56px);
  align-items: baseline;
  margin-bottom: clamp(40px, 5vw, 64px);
}
.ported-style-page--midnight-noir .mn-principles__index {
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(1rem, 1.4vw, 1.2rem);
  color: var(--gold);
  letter-spacing: 0.06em;
}
.ported-style-page--midnight-noir .mn-principles__title {
  font-family: var(--serif);
  font-size: clamp(2rem, 4.4vw, 3.2rem);
  font-weight: 500;
  line-height: 1.05;
  letter-spacing: -0.012em;
  color: var(--text);
  margin: 0;
  max-width: 18ch;
}
.ported-style-page--midnight-noir .mn-principles__title i {
  font-style: italic;
  font-weight: 400;
  color: var(--gold-soft);
}
.ported-style-page--midnight-noir .mn-principles__grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: clamp(32px, 4.5vw, 56px) clamp(36px, 5vw, 72px);
  max-width: 940px;
}
.ported-style-page--midnight-noir .mn-principle {
  display: grid;
  grid-template-columns: auto 1fr;
  column-gap: clamp(18px, 2.2vw, 28px);
  row-gap: 14px;
}
.ported-style-page--midnight-noir .mn-principle__num {
  grid-row: 1 / 3;
  font-family: var(--serif);
  font-style: italic;
  font-weight: 500;
  font-size: 1rem;
  color: var(--gold);
  letter-spacing: 0.02em;
  padding-top: 6px;
  font-feature-settings: 'tnum' 1;
}
.ported-style-page--midnight-noir .mn-principle__title {
  font-family: var(--serif);
  font-size: clamp(1.25rem, 2vw, 1.5rem);
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: -0.005em;
  color: var(--text);
  margin: 0;
}
.ported-style-page--midnight-noir .mn-principle__text {
  font-family: var(--sans);
  font-size: 0.95rem;
  font-weight: 400;
  line-height: 1.78;
  color: var(--text-soft);
  margin: 0;
  letter-spacing: 0.005em;
  max-width: 38ch;
}

/* === PALETTE === */
.ported-style-page--midnight-noir .mn-palette {
  padding-top: clamp(40px, 5vw, 64px);
  margin-top: clamp(56px, 7vw, 88px);
  border-top: 1px solid var(--line);
  animation: mn-rise 850ms var(--rise) 200ms both;
}
.ported-style-page--midnight-noir .mn-palette__head {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: clamp(28px, 4vw, 56px);
  align-items: baseline;
  margin-bottom: clamp(32px, 4vw, 48px);
}
.ported-style-page--midnight-noir .mn-palette__index {
  font-family: var(--serif);
  font-style: italic;
