.ported-style-page--midnight-noir .page-nav a:first-child { justify-content: flex-start; }
.ported-style-page--midnight-noir .page-nav a:last-child { justify-content: flex-end; text-align: right; }
.ported-style-page--midnight-noir .page-nav a:hover { color: var(--text); }
