/* bento-bloom — Boram composition.
   Replaces the previous SOFT BENTO UI demo grid with a single, opinionated
   marketing page for a fictional soft Korean productivity app. Uses the
   bento grid technique throughout, with marigold accent appearing exactly
   once per page. */

.ported-style-page--bento-bloom {
  /* Soft pastel palette — four papers + one accent. */
  --bg: #f4eee2;                /* warm cream substrate */
  --substrate: #f8f3e6;
  --paper-sage: #a7d3b8;
  --paper-peach: #f1c6a6;
  --paper-lavender: #c9b9e3;
  --paper-cream: #f6efd9;
  --accent: #f4d56a;            /* marigold — used exactly once per page */

  --ink: #2b2620;
  --ink-muted: #6a5f4f;
  --ink-faint: #998c7a;

  --shadow: rgba(43, 38, 32, 0.16);
  --shadow-soft: rgba(43, 38, 32, 0.08);

  --font-display: 'Pretendard Variable', 'Pretendard', 'Outfit', 'Inter Display', system-ui, sans-serif;
  --font-body: 'Pretendard Variable', 'Pretendard', 'Inter', system-ui, sans-serif;
  --font-mono: 'IBM Plex Mono', 'JetBrains Mono', ui-monospace, monospace;

  --tracking-display: -0.01em;
  --tracking-headline: -0.005em;
  --tracking-body: 0;
  --tracking-mono: 0.18em;

  --measure-prose: 56ch;
  --measure-headline: 18ch;

  --space-section: clamp(72px, 9vw, 144px);
  --space-block: 32px;

  background: var(--bg);
  color: var(--ink);
  font-family: var(--font-body);
  min-height: 100vh;
}

.ported-style-page--bento-bloom * { box-sizing: border-box; margin: 0; padding: 0; }

.ported-style-page--bento-bloom .page {
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 clamp(20px, 4vw, 56px);
}

.ported-style-page--bento-bloom ::selection {
  background: var(--ink);
  color: var(--bg);
}

.ported-style-page--bento-bloom a { color: inherit; text-decoration: none; }

.ported-style-page--bento-bloom .br-mono {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: var(--tracking-mono);
  color: var(--ink-muted);
  display: inline-block;
}

/* ───────────────────────────────────────────────────────────────────────
   Hero — asymmetric: statement left + app preview bento right
   ─────────────────────────────────────────────────────────────────────── */

.ported-style-page--bento-bloom .br-hero {
  display: grid;
  grid-template-columns: 1fr 1.05fr;
  gap: clamp(36px, 6vw, 96px);
  align-items: center;
  padding: clamp(64px, 9vw, 132px) 0 var(--space-section);
}

.ported-style-page--bento-bloom .br-hero__lead {
  display: flex;
  flex-direction: column;
  gap: 26px;
}

.ported-style-page--bento-bloom .br-hero__title {
  font-family: var(--font-display);
  font-size: clamp(3rem, 8.5vw, 6.8rem);
  font-weight: 800;
  line-height: 0.96;
  letter-spacing: var(--tracking-display);
  color: var(--ink);
  max-width: var(--measure-headline);
  word-break: keep-all;
}

.ported-style-page--bento-bloom .br-hero__sub {
  font-family: var(--font-body);
  font-size: clamp(1rem, 1.35vw, 1.15rem);
  font-weight: 500;
  line-height: 1.7;
  color: var(--ink-muted);
  max-width: 36ch;
  word-break: keep-all;
}

.ported-style-page--bento-bloom .br-hero__cta-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 18px;
  margin-top: 6px;
}

.ported-style-page--bento-bloom .br-cta {
  display: inline-flex;
  align-items: center;
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 0.95rem;
  padding: 12px 22px;
  border-radius: 8px;
  background: var(--paper-sage);
  color: var(--ink);
  box-shadow: 5px 5px 0 var(--shadow);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.ported-style-page--bento-bloom .br-cta--primary { background: var(--paper-sage); }

.ported-style-page--bento-bloom .br-cta:hover {
  transform: translate(-2px, -2px);
  box-shadow: 7px 7px 0 var(--shadow);
}

/* ───────────────────────────────────────────────────────────────────────
   Hero preview — bento grid app screenshot
   ─────────────────────────────────────────────────────────────────────── */

.ported-style-page--bento-bloom .br-preview {
  display: grid;
  grid-template-columns: repeat(12, 1fr);
  grid-auto-rows: minmax(80px, auto);
  gap: 12px;
  padding: 20px;
  background: var(--substrate);
  border-radius: 16px;
  box-shadow:
    6px 6px 0 var(--shadow-soft),
    14px 14px 0 var(--shadow);
}

.ported-style-page--bento-bloom .br-preview__tile {
  border-radius: 10px;
  padding: 16px 18px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  box-shadow: 3px 3px 0 var(--shadow-soft);
}

.ported-style-page--bento-bloom .br-preview__tile--today {
  grid-column: span 8;
  grid-row: span 2;
  background: var(--paper-peach);
}

.ported-style-page--bento-bloom .br-preview__tile--mood {
  grid-column: span 4;
  background: var(--paper-lavender);
}

.ported-style-page--bento-bloom .br-preview__tile--streak {
  grid-column: span 4;
  background: var(--paper-sage);
}

.ported-style-page--bento-bloom .br-preview__tile--bloom {
  grid-column: span 4;
  grid-row: span 2;
  background: var(--paper-cream);
  align-items: center;
  justify-content: center;
  gap: 14px;
  position: relative;
}

.ported-style-page--bento-bloom .br-preview__bloom-label {
  font-family: var(--font-display);
  font-size: 13px;
  font-weight: 700;
  color: var(--ink);
  letter-spacing: -0.005em;
}

.ported-style-page--bento-bloom .br-preview__tile--memo {
  grid-column: span 12;
  background: #fff;
}

/* ───────────────────────────────────────────────────────────────────────
   Statement band — full-bleed sage punctuation between manifesto and features
   The page's single largest "moment" — gives the otherwise calm page a beat.
   ─────────────────────────────────────────────────────────────────────── */

.ported-style-page--bento-bloom .br-statement {
  position: relative;
  margin: 0 calc(-1 * clamp(20px, 4vw, 56px)) var(--space-section);
  padding: clamp(60px, 9vw, 120px) clamp(28px, 5vw, 96px);
  background: var(--paper-sage);
  border-radius: 0;
  overflow: hidden;
  display: flex;
  align-items: center;
  gap: clamp(32px, 6vw, 80px);
}

.ported-style-page--bento-bloom .br-statement__mascot {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

.ported-style-page--bento-bloom .br-statement__mascot .br-mascot {
  width: clamp(120px, 18vw, 220px);
  height: clamp(120px, 18vw, 220px);
  filter: drop-shadow(6px 6px 0 rgba(43, 38, 32, 0.15));
}

.ported-style-page--bento-bloom .br-statement__line {
  font-family: var(--font-display);
  font-size: clamp(2rem, 6vw, 4.4rem);
  font-weight: 800;
  line-height: 1.05;
  letter-spacing: var(--tracking-display);
  color: var(--ink);
  max-width: 18ch;
  word-break: keep-all;
}

.ported-style-page--bento-bloom .br-preview__caption {
  font-family: var(--font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--ink-muted);
}

.ported-style-page--bento-bloom .br-preview__title {
  font-family: var(--font-display);
  font-size: clamp(1.05rem, 1.5vw, 1.3rem);
  font-weight: 700;
  line-height: 1.25;
  color: var(--ink);
  word-break: keep-all;
}

.ported-style-page--bento-bloom .br-preview__hint {
  font-family: var(--font-body);
  font-size: 12px;
  color: var(--ink-muted);
  margin-top: auto;
}

.ported-style-page--bento-bloom .br-preview__big {
  font-family: var(--font-display);
  font-size: clamp(1.6rem, 3vw, 2.3rem);
  font-weight: 800;
  line-height: 1;
  color: var(--ink);
}

.ported-style-page--bento-bloom .br-preview__mood {
  display: flex;
  gap: 8px;
  margin-top: 4px;
}

.ported-style-page--bento-bloom .br-preview__mood-dot {
  width: 22px;
  height: 22px;
  border-radius: 50%;
}

.ported-style-page--bento-bloom .br-preview__memo-line {
  font-family: var(--font-body);
  font-size: 13px;
  font-weight: 500;
  color: var(--ink);
  line-height: 1.55;
}

.ported-style-page--bento-bloom .br-preview__memo-line--accent {
  background: linear-gradient(180deg, transparent 50%, var(--accent) 50%);
  display: inline-block;
  padding: 0 4px;
  width: fit-content;
}

/* ───────────────────────────────────────────────────────────────────────
   Manifesto — narrow measure, generous spacing
   ─────────────────────────────────────────────────────────────────────── */

.ported-style-page--bento-bloom .br-manifesto {
  max-width: var(--measure-prose);
  margin: 0 auto;
  padding: 0 0 var(--space-section);
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.ported-style-page--bento-bloom .br-manifesto__lede {
  font-family: var(--font-display);
  font-size: clamp(1.55rem, 3vw, 2.2rem);
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: var(--tracking-headline);
  color: var(--ink);
  word-break: keep-all;
}

.ported-style-page--bento-bloom .br-manifesto__body {
  font-family: var(--font-body);
  font-size: 17px;
  font-weight: 500;
  line-height: 1.65;
  color: var(--ink-muted);
  word-break: keep-all;
}

/* ───────────────────────────────────────────────────────────────────────
   Features — three alternating vignettes
   ─────────────────────────────────────────────────────────────────────── */

.ported-style-page--bento-bloom .br-features {
  padding: 0 0 var(--space-section);
}

.ported-style-page--bento-bloom .br-features__head { margin-bottom: 28px; }

.ported-style-page--bento-bloom .br-feature {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: clamp(32px, 5vw, 64px);
  align-items: center;
  padding: 48px 0;
  border-top: 1px solid rgba(43, 38, 32, 0.16);
}

.ported-style-page--bento-bloom .br-feature--right .br-feature__visual { order: 2; }
.ported-style-page--bento-bloom .br-feature--right .br-feature__text { order: 1; }

.ported-style-page--bento-bloom .br-feature__text {
  display: flex;
  flex-direction: column;
  gap: 14px;
  max-width: 38ch;
}

.ported-style-page--bento-bloom .br-feature__title {
  font-family: var(--font-display);
  font-size: clamp(1.7rem, 3.4vw, 2.6rem);
  font-weight: 800;
  line-height: 1.05;
  letter-spacing: var(--tracking-display);
  color: var(--ink);
  word-break: keep-all;
}

.ported-style-page--bento-bloom .br-feature__body {
  font-family: var(--font-body);
  font-size: 15.5px;
  font-weight: 500;
  line-height: 1.7;
  color: var(--ink-muted);
  word-break: keep-all;
}

/* ───────────────────────────────────────────────────────────────────────
   Vignettes — feature-specific bento compositions
   ─────────────────────────────────────────────────────────────────────── */

.ported-style-page--bento-bloom .br-vignette {
  position: relative;
  border-radius: 14px;
  padding: 28px 24px;
  box-shadow:
    6px 6px 0 var(--shadow-soft),
    12px 12px 0 var(--shadow);
  min-height: 240px;
  overflow: hidden;
}

.ported-style-page--bento-bloom .br-vignette--peach { background: var(--paper-peach); }
.ported-style-page--bento-bloom .br-vignette--lavender { background: var(--paper-lavender); }
.ported-style-page--bento-bloom .br-vignette--sage { background: var(--paper-sage); }

.ported-style-page--bento-bloom .br-vignette__caption {
  font-family: var(--font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: rgba(43, 38, 32, 0.55);
  display: block;
  margin-bottom: 10px;
}

.ported-style-page--bento-bloom .br-vignette__line {
  display: flex;
  gap: 12px;
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: rgba(43, 38, 32, 0.55);
  margin-bottom: 14px;
}

.ported-style-page--bento-bloom .br-vignette__entry {
  font-family: var(--font-display);
  font-size: 18px;
  font-weight: 500;
  line-height: 1.55;
  color: var(--ink);
  margin-bottom: 6px;
}

.ported-style-page--bento-bloom .br-vignette__entry--soft {
  color: rgba(43, 38, 32, 0.6);
}

.ported-style-page--bento-bloom .br-vignette__pen {
  position: absolute;
  right: 22px;
  bottom: 22px;
  width: 4px;
  height: 38px;
  background: var(--ink);
  border-radius: 2px;
  transform: rotate(28deg);
}

.ported-style-page--bento-bloom .br-vignette__pen::after {
  content: '';
  position: absolute;
  top: -8px;
  left: -2px;
  width: 8px;
  height: 10px;
  background: var(--ink);
  clip-path: polygon(0 100%, 50% 0, 100% 100%);
}

.ported-style-page--bento-bloom .br-vignette__moods {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 8px;
  margin: 8px 0 16px;
}

.ported-style-page--bento-bloom .br-vignette__mood-cell {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

.ported-style-page--bento-bloom .br-vignette__mood-chip {
  width: 100%;
  aspect-ratio: 1;
  max-width: 36px;
  border-radius: 50%;
  box-shadow: 2px 2px 0 rgba(43, 38, 32, 0.12);
}

.ported-style-page--bento-bloom .br-vignette__mood-day {
  font-family: var(--font-mono);
  font-size: 11px;
  color: rgba(43, 38, 32, 0.6);
}

.ported-style-page--bento-bloom .br-vignette__note {
  font-family: var(--font-body);
  font-size: 13.5px;
  font-weight: 500;
  color: rgba(43, 38, 32, 0.7);
  margin-top: 8px;
}

.ported-style-page--bento-bloom .br-vignette__garden {
  position: relative;
  height: 130px;
}

.ported-style-page--bento-bloom .br-vignette__friend {
  position: absolute;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  font-family: var(--font-display);
  font-size: 12px;
  font-weight: 600;
  color: var(--ink);
}

.ported-style-page--bento-bloom .br-vignette__friend--1 { left: 8%; top: 4px; }
.ported-style-page--bento-bloom .br-vignette__friend--2 { left: 38%; top: -6px; }
.ported-style-page--bento-bloom .br-vignette__friend--3 { left: 70%; top: 12px; }

.ported-style-page--bento-bloom .br-vignette__sprout {
  position: absolute;
  right: 4%;
  top: 56px;
  font-size: 16px;
}

/* ───────────────────────────────────────────────────────────────────────
   Materials & rules
   ─────────────────────────────────────────────────────────────────────── */

.ported-style-page--bento-bloom .br-materials {
  display: flex;
  flex-direction: column;
  gap: 48px;
  padding: 0 0 var(--space-section);
}

.ported-style-page--bento-bloom .br-materials__head {
  display: flex;
  flex-direction: column;
  gap: 14px;
  max-width: 46ch;
}

.ported-style-page--bento-bloom .br-materials__title {
  font-family: var(--font-display);
  font-size: clamp(1.7rem, 3.6vw, 2.4rem);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: var(--tracking-display);
  color: var(--ink);
  word-break: keep-all;
}

.ported-style-page--bento-bloom .br-swatches {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
}

.ported-style-page--bento-bloom .br-swatch {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.ported-style-page--bento-bloom .br-swatch__chip {
  aspect-ratio: 4 / 5;
  border-radius: 8px;
  box-shadow: 4px 4px 0 var(--shadow);
}

.ported-style-page--bento-bloom .br-swatch__meta strong {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 14px;
  color: var(--ink);
  display: block;
}

.ported-style-page--bento-bloom .br-swatch__meta code {
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--ink-faint);
  display: block;
  margin-top: 2px;
}

.ported-style-page--bento-bloom .br-swatch__role {
  display: block;
  font-family: var(--font-mono);
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--accent);
  margin-top: 4px;
}

.ported-style-page--bento-bloom .br-rules {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: var(--space-block);
}

.ported-style-page--bento-bloom .br-rule {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 24px;
  border-radius: 10px;
  box-shadow:
    5px 5px 0 var(--shadow-soft),
    10px 10px 0 var(--shadow);
}

.ported-style-page--bento-bloom .br-rule--sage { background: var(--paper-sage); }
.ported-style-page--bento-bloom .br-rule--peach { background: var(--paper-peach); }
.ported-style-page--bento-bloom .br-rule--lavender { background: var(--paper-lavender); }

.ported-style-page--bento-bloom .br-rule__title {
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: var(--tracking-headline);
  color: var(--ink);
  word-break: keep-all;
  margin: 4px 0 4px;
}

.ported-style-page--bento-bloom .br-rule__body {
  font-family: var(--font-body);
  font-size: 14.5px;
  font-weight: 500;
  line-height: 1.65;
  color: rgba(43, 38, 32, 0.75);
  word-break: keep-all;
}

/* ───────────────────────────────────────────────────────────────────────
   AI prompt — paper-fold disclosure
   ─────────────────────────────────────────────────────────────────────── */

.ported-style-page--bento-bloom .prompt { padding: 0 0 var(--space-section); }

.ported-style-page--bento-bloom .prompt-fold > summary {
  list-style: none;
  cursor: pointer;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;
  padding: 14px 20px;
  background: var(--paper-peach);
  border-radius: 8px;
  box-shadow: 4px 4px 0 var(--shadow);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.ported-style-page--bento-bloom .prompt-fold > summary::-webkit-details-marker { display: none; }

.ported-style-page--bento-bloom .prompt-fold > summary:hover {
  transform: translate(-2px, -2px);
  box-shadow: 6px 6px 0 var(--shadow);
}

.ported-style-page--bento-bloom .prompt-fold__label {
  font-family: var(--font-display);
  font-size: clamp(1.05rem, 2vw, 1.25rem);
  font-weight: 700;
  color: var(--ink);
}

.ported-style-page--bento-bloom .prompt-fold__hint {
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: rgba(43, 38, 32, 0.55);
}

.ported-style-page--bento-bloom .prompt-fold[open] > summary {
  margin-bottom: 20px;
  background: var(--paper-sage);
}

.ported-style-page--bento-bloom .prompt pre {
  white-space: pre-wrap;
  word-wrap: break-word;
  font-family: var(--font-body);
  font-size: 14px;
  font-weight: 500;
  line-height: 1.75;
  color: var(--ink);
  padding: 28px 28px 32px;
  border-radius: 10px;
  background: var(--paper-cream);
  box-shadow:
    8px 8px 0 var(--paper-lavender),
    16px 16px 0 var(--shadow);
}

.ported-style-page--bento-bloom .prompt button {
  margin-top: 24px;
  padding: 11px 26px;
  border-radius: 8px;
  border: none;
  background: var(--paper-lavender);
  color: var(--ink);
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 0.9rem;
  letter-spacing: 0.04em;
  cursor: pointer;
  transition: transform 0.22s ease, box-shadow 0.22s ease;
  box-shadow: 4px 4px 0 var(--shadow);
}

.ported-style-page--bento-bloom .prompt button:hover {
  transform: translate(-2px, -2px);
  box-shadow: 6px 6px 0 var(--shadow);
}

/* ───────────────────────────────────────────────────────────────────────
   Chrome — site-nav typography, page-back-link, page-footer, page-nav
   ─────────────────────────────────────────────────────────────────────── */

.ported-style-page--bento-bloom .site-nav__logo {
  font-family: var(--font-display);
  font-weight: 800;
  letter-spacing: var(--tracking-display);
  color: var(--ink);
}

.ported-style-page--bento-bloom .site-nav__links a,
.ported-style-page--bento-bloom .lang-toggle,
.ported-style-page--bento-bloom .lang-menu button {
  font-family: var(--font-body);
  font-weight: 600;
  color: var(--ink);
}

.ported-style-page--bento-bloom .page-back-link {
  position: fixed;
  top: 20px;
  left: 20px;
  z-index: 100;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 14px;
  background: #fff;
  border: 1px solid rgba(43, 38, 32, 0.1);
  border-radius: 8px;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink);
  box-shadow: 3px 3px 0 var(--shadow);
}

.ported-style-page--bento-bloom .page-back-link svg { width: 12px; height: 12px; }

.ported-style-page--bento-bloom .page-footer {
  text-align: center;
  padding: 28px 20px 64px;
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--ink-faint);
}

.ported-style-page--bento-bloom .page-footer a { color: var(--ink-muted); }

/* Page-nav — overrides the global dark-glass band. The shared .ported-style-page
   rule strips grid-template-columns, so we must re-establish the 2-col layout
   here and rebuild each <a>'s flex internals. */
.ported-style-page.ported-style-page--bento-bloom:not(.ported-style-page--platform-core):not(.ported-style-page--runtime-signal) .page-nav {
  display: grid !important;
  grid-template-columns: 1fr 1fr !important;
  gap: 14px !important;
  padding: 16px !important;
  background: var(--paper-cream) !important;
  border: 1px solid rgba(43, 38, 32, 0.12) !important;
  border-radius: 14px !important;
  box-shadow: 4px 4px 0 var(--shadow) !important;
}

.ported-style-page.ported-style-page--bento-bloom:not(.ported-style-page--platform-core):not(.ported-style-page--runtime-signal) .page-nav a {
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  gap: 14px !important;
  padding: 16px 18px !important;
  min-height: 72px !important;
  color: var(--ink) !important;
  background: #fff !important;
  border: 1px solid rgba(43, 38, 32, 0.12) !important;
  border-radius: 10px !important;
  font-family: var(--font-display) !important;
  font-weight: 700 !important;
  box-shadow: 3px 3px 0 var(--shadow) !important;
  transition: transform 0.2s ease, box-shadow 0.2s ease !important;
}

.ported-style-page.ported-style-page--bento-bloom:not(.ported-style-page--platform-core):not(.ported-style-page--runtime-signal) .page-nav a:last-of-type {
  flex-direction: row-reverse !important;
  text-align: right !important;
}

.ported-style-page.ported-style-page--bento-bloom:not(.ported-style-page--platform-core):not(.ported-style-page--runtime-signal) .page-nav a > span {
  display: flex !important;
  flex-direction: column !important;
  align-items: flex-start !important;
  gap: 4px !important;
  flex: 1 !important;
  line-height: 1.2 !important;
}

.ported-style-page.ported-style-page--bento-bloom:not(.ported-style-page--platform-core):not(.ported-style-page--runtime-signal) .page-nav a:last-of-type > span {
  align-items: flex-end !important;
}

.ported-style-page.ported-style-page--bento-bloom:not(.ported-style-page--platform-core):not(.ported-style-page--runtime-signal) .page-nav a:hover {
  transform: translate(-1px, -1px) !important;
  background: var(--paper-peach) !important;
  box-shadow: 5px 5px 0 var(--shadow) !important;
}

.ported-style-page.ported-style-page--bento-bloom:not(.ported-style-page--platform-core):not(.ported-style-page--runtime-signal) .page-nav a svg {
  width: 16px !important;
  height: 16px !important;
  flex-shrink: 0 !important;
  stroke: var(--ink) !important;
}

.ported-style-page.ported-style-page--bento-bloom:not(.ported-style-page--platform-core):not(.ported-style-page--runtime-signal) .page-nav__divider {
  display: none !important;
}

.ported-style-page.ported-style-page--bento-bloom:not(.ported-style-page--platform-core):not(.ported-style-page--runtime-signal) .page-nav .page-nav__label {
  font-family: var(--font-mono) !important;
  font-size: 0.7rem !important;
  font-weight: 500 !important;
  color: rgba(43, 38, 32, 0.55) !important;
  letter-spacing: 0.14em !important;
  text-transform: uppercase !important;
}

@media (max-width: 640px) {
  .ported-style-page.ported-style-page--bento-bloom:not(.ported-style-page--platform-core):not(.ported-style-page--runtime-signal) .page-nav {
    grid-template-columns: 1fr !important;
    gap: 10px !important;
  }
}

/* ───────────────────────────────────────────────────────────────────────
   Responsive
   ─────────────────────────────────────────────────────────────────────── */

@media (max-width: 960px) {
  .ported-style-page--bento-bloom .br-hero {
    grid-template-columns: 1fr;
    gap: 48px;
  }
  .ported-style-page--bento-bloom .br-hero__title { max-width: 16ch; }
  .ported-style-page--bento-bloom .br-feature {
    grid-template-columns: 1fr;
    gap: 24px;
  }
  .ported-style-page--bento-bloom .br-feature--right .br-feature__visual { order: 1; }
  .ported-style-page--bento-bloom .br-feature--right .br-feature__text { order: 2; }
  .ported-style-page--bento-bloom .br-swatches { grid-template-columns: repeat(5, 1fr); gap: 10px; }
}

@media (max-width: 600px) {
  .ported-style-page--bento-bloom .br-swatches { grid-template-columns: repeat(3, 1fr); }
  .ported-style-page--bento-bloom .br-vignette__moods { gap: 4px; }
}


/* earth-atelier */
