/* liquid-metal — neutral stainless palette (no blue cast) */
.ported-style-page--liquid-metal {
        --bg: #0a0a0c;
        --bg-deep: #050505;
        --ink: #0c0c0c;
        --text: #ececec;
        --chrome: #b0b0b0;
        --chrome-hi: #f0f0f0;
        --chrome-lo: #6c6c6c;
        --chrome-deep: #2a2a2a;
        --specular: #fafafa;
        --steel-warm: #c8c8c8;
        --line: rgba(220, 220, 220, 0.14);
        --line-strong: rgba(220, 220, 220, 0.3);
      }
.ported-style-page--liquid-metal * { box-sizing: border-box; }
.ported-style-page--liquid-metal {
        margin: 0;
        color: var(--text);
        font-family: 'Noto Sans KR', 'Sora', sans-serif;
        background:
          radial-gradient(ellipse 90% 50% at 50% 8%, rgba(255,255,255,0.05), transparent 65%),
          radial-gradient(ellipse 60% 30% at 50% 100%, rgba(255,255,255,0.025), transparent 60%),
          linear-gradient(180deg, #0c0c0c 0%, #050505 100%);
        background-attachment: fixed;
        min-height: 100svh;
        position: relative;
      }
.ported-style-page--liquid-metal::before {
        content: '';
        position: fixed;
        inset: 0;
        pointer-events: none;
        z-index: 0;
        background-image: repeating-linear-gradient(180deg, rgba(240, 240, 240, 0.014) 0 1px, transparent 1px 4px);
        mix-blend-mode: screen;
      }
.ported-style-page--liquid-metal::after {
        content: '';
        position: fixed;
        left: 0; right: 0;
        bottom: 0;
        height: 30vh;
        pointer-events: none;
        z-index: 0;
        background: linear-gradient(180deg, transparent 0%, rgba(0,0,0,0.6) 100%);
      }
.ported-style-page--liquid-metal > div { position: relative; z-index: 1; }
.ported-style-page--liquid-metal .shell {
        width: min(1120px, 92vw);
        margin: 0 auto;
        padding: 28px 20px 80px;
      }
.ported-style-page--liquid-metal .top {
        display: flex;
        justify-content: space-between;
        align-items: center;
      }
.ported-style-page--liquid-metal .top a { color: var(--chrome); text-decoration: none; }
.ported-style-page--liquid-metal .hero {
        margin-top: 20px;
        border: 1px solid var(--line);
        border-top-color: rgba(240, 240, 240, 0.18);
        border-bottom-color: rgba(0,0,0,0.6);
        border-radius: 4px;
        padding: clamp(28px, 5vw, 56px);
        background:
          linear-gradient(168deg,
            rgba(46,46,46,0.7) 0%,
            rgba(26,26,26,0.55) 30%,
            rgba(14,14,14,0.85) 75%,
            rgba(8,8,8,0.95) 100%
          );
        position: relative;
        overflow: hidden;
        display: grid;
        grid-template-columns: minmax(0, 1fr) auto;
        gap: clamp(20px, 3vw, 40px);
        align-items: start;
        box-shadow:
          inset 0 1px 0 rgba(240, 240, 240, 0.08),
          inset 0 -1px 0 rgba(0,0,0,0.5),
          0 16px 48px rgba(0,0,0,0.55),
          0 4px 12px rgba(0,0,0,0.35);
      }
.ported-style-page--liquid-metal .hero::after {
        content: '';
        position: absolute;
        top: 0; left: 8%; right: 8%;
        height: 1px;
        background: linear-gradient(90deg, transparent, var(--specular), transparent);
        opacity: 0.55;
        pointer-events: none;
      }
.ported-style-page--liquid-metal .hero::before {
        content: '';
        position: absolute;
        top: -50%;
        left: -20%;
        width: 140%;
        height: 100%;
        background: linear-gradient(
          105deg,
          transparent 30%,
          rgba(255, 255, 255, 0.03) 40%,
          rgba(255, 255, 255, 0.08) 45%,
          rgba(255, 255, 255, 0.03) 50%,
          transparent 60%
        );
        transform: rotate(-15deg);
        pointer-events: none;
        animation: ported-liquid-metal-sweep 8s ease-in-out infinite;
      }
.ported-style-page--liquid-metal .hero-content { position: relative; z-index: 1; }
/* — HERO META BAND — */
.ported-style-page--liquid-metal .hero-meta {
        grid-column: 1 / -1;
        display: flex;
        align-items: center;
        gap: 12px;
        padding-bottom: 18px;
        margin-bottom: 4px;
        border-bottom: 1px solid var(--line);
        font-family: 'Sora', sans-serif;
        font-size: 0.66rem;
        font-weight: 500;
        letter-spacing: 0.32em;
        text-transform: uppercase;
        color: var(--chrome-lo);
        position: relative;
        z-index: 2;
      }
.ported-style-page--liquid-metal .hero-meta__serial {
        background: linear-gradient(180deg, var(--chrome-hi), var(--chrome));
        -webkit-background-clip: text;
        -webkit-text-fill-color: transparent;
        background-clip: text;
      }
.ported-style-page--liquid-metal .hero-meta__dot {
        width: 5px;
        height: 5px;
        border-radius: 50%;
        background: linear-gradient(180deg, var(--chrome-hi), var(--chrome-lo));
        box-shadow: 0 0 0 1px rgba(255,255,255,0.06);
      }
.ported-style-page--liquid-metal .hero-meta__edition {
        margin-left: auto;
        color: var(--chrome-lo);
      }

/* — HERO CTA — */
.ported-style-page--liquid-metal .hero-cta {
        display: flex;
        gap: 12px;
        margin-top: 28px;
        flex-wrap: wrap;
      }

