/* aurora-gradient — editorial refinement */
.ported-style-page--aurora-gradient {
  --bg: #07071a;
  --bg-soft: #0c0c22;
  --text: #e9eaf3;
  --ink-1: rgba(233, 234, 243, 0.96);
  --ink-2: rgba(233, 234, 243, 0.66);
  --ink-3: rgba(233, 234, 243, 0.42);
  --ink-4: rgba(233, 234, 243, 0.22);
  --hairline: rgba(233, 234, 243, 0.08);
  --hairline-bright: rgba(233, 234, 243, 0.16);
  --accent: #9d7bff;
  --accent-2: #6fe7f5;
  --accent-3: #ff8eb1;
  --accent-rgb: 157, 123, 255;
  --accent-2-rgb: 111, 231, 245;
  --accent-3-rgb: 255, 142, 177;
  --accent-soft: #c8b4ff;
  --line: var(--hairline);
  --mono: 'JetBrains Mono', 'IBM Plex Mono', ui-monospace, monospace;
  --serif: 'Cormorant Garamond', 'Noto Serif KR', serif;
  --sans: 'Plus Jakarta Sans', 'Noto Sans KR', sans-serif;
}
.ported-style-page--aurora-gradient * { box-sizing: border-box; }
.ported-style-page--aurora-gradient {
  margin: 0;
  color: var(--ink-1);
  font-family: var(--sans);
  background: var(--bg);
  min-height: 100svh;
  overflow-x: hidden;
  position: relative;
}
.ported-style-page--aurora-gradient::after {
  content: '';
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 2;
  mix-blend-mode: overlay;
  opacity: 0.06;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='2' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
}
.ported-style-page--aurora-gradient .aurora {
  position: fixed;
  inset: 0;
  z-index: 0;
  overflow: hidden;
  pointer-events: none;
}
.ported-style-page--aurora-gradient .aurora::before,
.ported-style-page--aurora-gradient .aurora::after {
  content: '';
  position: absolute;
  border-radius: 50%;
  filter: blur(140px);
  animation: ported-aurora-gradient-drift 16s ease-in-out infinite alternate;
}
.ported-style-page--aurora-gradient .aurora::before {
  width: 720px;
  height: 460px;
  top: -14%;
  left: 6%;
  background: linear-gradient(135deg, rgba(var(--accent-rgb), 0.42), rgba(var(--accent-2-rgb), 0.22));
  opacity: 0.85;
}
.ported-style-page--aurora-gradient .aurora::after {
  width: 600px;
  height: 600px;
  bottom: -12%;
  right: -2%;
  background: linear-gradient(225deg, rgba(var(--accent-3-rgb), 0.32), rgba(var(--accent-rgb), 0.22));
  animation-delay: -8s;
  animation-direction: alternate-reverse;
  opacity: 0.85;
}
.ported-style-page--aurora-gradient .aurora-mid {
  position: fixed;
  width: 540px;
  height: 380px;
  top: 28%;
  left: 50%;
  transform: translateX(-50%);
  border-radius: 50%;
  background: radial-gradient(ellipse, rgba(var(--accent-2-rgb), 0.22), transparent 70%);
  filter: blur(120px);
  pointer-events: none;
  z-index: 0;
  animation: ported-aurora-gradient-pulse 10s ease-in-out infinite alternate;
}
.ported-style-page--aurora-gradient .shell {
  position: relative;
  z-index: 3;
  width: min(1180px, 92vw);
  margin: 0 auto;
  padding: 56px 24px 120px;
}
.ported-style-page--aurora-gradient .top {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.ported-style-page--aurora-gradient .top a { color: var(--ink-1); text-decoration: none; }

/* ---------- hero ---------- */
