/* mono-type — light mode override */
.ported-style-page--mono-type[data-color-mode="light"] {
        --bg: #f4f3ef;
        --text: #1a1a1a;
        --accent: #1a1a1a;
        --muted: #5a5a5a;
        --muted-soft: #8a8a8a;
        --line: rgba(0, 0, 0, 0.18);
        --line-soft: rgba(0, 0, 0, 0.1);
      }
.ported-style-page--mono-type[data-color-mode="light"] .mono-paper {
        background: #fbfaf6;
        background-image:
          linear-gradient(90deg, rgba(0,0,0,0.05) 1px, transparent 1px),
          linear-gradient(rgba(0,0,0,0.05) 1px, transparent 1px);
      }
.ported-style-page--mono-type[data-color-mode="light"] .mono-paper::before {
        color: #1a1a1a;
      }
.ported-style-page--mono-type[data-color-mode="light"] .mono-paper::after {
        color: #5a5a5a;
      }
.ported-style-page--mono-type[data-color-mode="light"] .mono-paper__footer {
        border-top-color: rgba(0,0,0,0.22);
      }
.ported-style-page--mono-type[data-color-mode="light"] .specimen-line {
        border-top-color: rgba(0,0,0,0.3);
      }
.ported-style-page--mono-type[data-color-mode="light"] .lead,
.ported-style-page--mono-type[data-color-mode="light"] .hero-specimen .lead {
        color: #3a3a3a;
      }
.ported-style-page--mono-type[data-color-mode="light"] .annotated__block {
        background-image:
          linear-gradient(transparent calc(1.95em - 1px), rgba(0,0,0,0.12) calc(1.95em - 1px), rgba(0,0,0,0.12) 1.95em);
      }
.ported-style-page--mono-type[data-color-mode="light"] .tab-ruler__tick {
        background: rgba(0,0,0,0.3);
      }
.ported-style-page--mono-type[data-color-mode="light"] .tab-ruler__tick--major {
        background: rgba(0,0,0,0.55);
      }
.ported-style-page--mono-type[data-color-mode="light"] .tab-ruler__tick-label {
        color: rgba(0,0,0,0.55);
      }
.ported-style-page--mono-type[data-color-mode="light"] .status-bar {
        background: rgba(0,0,0,0.025);
      }
.ported-style-page--mono-type[data-color-mode="light"] .status-bar__sep {
        color: rgba(0,0,0,0.28);
      }
.ported-style-page--mono-type[data-color-mode="light"] .typing-cursor {
        background: #1a1a1a;
      }
.ported-style-page--mono-type[data-color-mode="light"] .code-poetry__line::before {
        color: rgba(0,0,0,0.45);
        border-right-color: rgba(0,0,0,0.14);
      }
.ported-style-page--mono-type[data-color-mode="light"] .code-poetry__string { color: #4a4a4a; }
.ported-style-page--mono-type[data-color-mode="light"] .code-poetry__comment { color: rgba(0,0,0,0.45); }
.ported-style-page--mono-type[data-color-mode="light"] .code-poetry__line:hover { background: rgba(0,0,0,0.03); }
.ported-style-page--mono-type[data-color-mode="light"] .strike { color: rgba(0,0,0,0.55); }
.ported-style-page--mono-type[data-color-mode="light"] .correction { border-bottom-color: rgba(0,0,0,0.5); }
.ported-style-page--mono-type[data-color-mode="light"] pre { color: #4a4a4a; }
.ported-style-page--mono-type[data-color-mode="light"] .mono-paper__footer-sep { color: rgba(0,0,0,0.3); }
.ported-style-page--mono-type[data-color-mode="light"] .page-back-link {
