.ported-style-page--mono-type[data-color-mode="light"] .page-nav__divider { background: rgba(0,0,0,0.16); }


/* ── console-launch components ── */
.ported-style-page--console-launch .cmp-section {
        border: 1px solid var(--line);
        border-radius: 14px;
        background: var(--panel);
        margin-bottom: 18px;
        overflow: hidden;
      }
.ported-style-page--console-launch .cmp-section__head {
        display: flex;
        align-items: center;
        gap: 8px;
        padding: 10px 14px;
        background: var(--surface);
        border-bottom: 1px solid var(--line);
        font-family: 'JetBrains Mono', monospace;
        font-size: 0.78rem;
      }
.ported-style-page--console-launch .cmp-section__prompt {
        color: var(--accent);
        font-weight: 700;
      }
.ported-style-page--console-launch .cmp-section__cmd {
        color: var(--text);
      }
.ported-style-page--console-launch .cmp-section__crumb {
        margin-left: auto;
        color: var(--muted);
        font-size: 0.72rem;
        letter-spacing: 0.04em;
      }
.ported-style-page--console-launch .cmp-grid {
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 14px;
        padding: 16px;
      }
.ported-style-page--console-launch .cmp-card {
        border: 1px solid var(--line);
        border-radius: 10px;
        background: var(--surface);
        padding: 14px;
        display: flex;
        flex-direction: column;
        gap: 12px;
      }
.ported-style-page--console-launch .cmp-card--wide {
        grid-column: 1 / -1;
      }
.ported-style-page--console-launch .cmp-card__head {
        display: flex;
        align-items: baseline;
        gap: 10px;
        padding-bottom: 8px;
        border-bottom: 1px dashed var(--line);
      }
.ported-style-page--console-launch .cmp-card__name {
        font-family: 'JetBrains Mono', monospace;
        font-size: 0.82rem;
        font-weight: 700;
        color: var(--text);
      }
.ported-style-page--console-launch .cmp-card__path {
        font-family: 'JetBrains Mono', monospace;
        font-size: 0.7rem;
        color: var(--muted);
        letter-spacing: 0.02em;
      }
.ported-style-page--console-launch .cmp-card__body {
        font-family: 'JetBrains Mono', monospace;
      }
.ported-style-page--console-launch .cmp-card__body--row {
        display: flex;
        flex-wrap: wrap;
        gap: 8px;
        align-items: center;
      }
.ported-style-page--console-launch .cmp-card__body--stack {
        display: flex;
        flex-direction: column;
        gap: 10px;
      }
.ported-style-page--console-launch .cmp-card__body--wrap {
        display: flex;
        flex-wrap: wrap;
        gap: 8px;
        align-items: center;
      }
.ported-style-page--console-launch .cmp-card__body--stat {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 10px;
      }

/* Buttons */
.ported-style-page--console-launch .cmp-btn {
        display: inline-flex;
        align-items: center;
        gap: 6px;
        padding: 8px 14px;
        border-radius: 8px;
        font-family: 'JetBrains Mono', monospace;
        font-size: 0.82rem;
        font-weight: 600;
        letter-spacing: 0.02em;
        cursor: pointer;
        transition: transform 120ms ease, background 120ms ease, border-color 120ms ease;
        border: 1px solid transparent;
      }
.ported-style-page--console-launch .cmp-btn:hover { transform: translateY(-1px); }
.ported-style-page--console-launch .cmp-btn:disabled,
.ported-style-page--console-launch .cmp-btn[disabled] {
        cursor: not-allowed;
        opacity: 0.55;
        transform: none;
      }
.ported-style-page--console-launch .cmp-btn--primary {
        background: var(--accent);
        color: var(--bg);
        border-color: var(--accent);
      }
.ported-style-page--console-launch .cmp-btn--primary:hover {
        background: var(--accent-soft);
        border-color: var(--accent-soft);
      }
.ported-style-page--console-launch .cmp-btn--ghost {
        background: transparent;
        color: var(--text);
        border-color: var(--line);
      }
