.ported-style-page--console-launch .cmp-stat__delta--down { color: #f43f5e; }
.ported-style-page--console-launch .cmp-stat__delta--flat { color: var(--muted); }

/* Progress + spinner */
.ported-style-page--console-launch .cmp-progress {
        display: grid;
