/* framer-motion */
.ported-style-page--framer-motion {
        --bg: #09090b;
        --surface: rgba(255, 255, 255, 0.05);
        --surface-hover: rgba(255, 255, 255, 0.08);
        --text: #fafafa;
        --text-muted: #a1a1aa;
        --border: rgba(255, 255, 255, 0.1);
        --border-hover: rgba(255, 255, 255, 0.2);
        --accent: #8b5cf6;
        --accent-2: #06b6d4;
        --gradient-text: linear-gradient(to right, #8b5cf6, #06b6d4);
        --glow: rgba(139, 92, 246, 0.15);
        --dot-color: rgba(255, 255, 255, 0.07);
      }
.ported-style-page--framer-motion * { box-sizing: border-box; margin: 0; padding: 0; }
.ported-style-page--framer-motion {
        background: var(--bg);
        color: var(--text);
        font-family: 'Inter', 'Noto Sans KR', sans-serif;
        font-size: 15px;
        font-weight: 400;
        line-height: 1.6;
        min-height: 100svh;
      }
.ported-style-page--framer-motion .dot-grid {
        position: fixed;
        inset: 0;
        z-index: 0;
        pointer-events: none;
        background-image: radial-gradient(circle, var(--dot-color) 1px, transparent 1px);
        background-size: 24px 24px;
      }
.ported-style-page--framer-motion .spotlight {
        position: fixed;
        top: -20%;
        left: 50%;
        transform: translateX(-50%);
        width: 800px;
        height: 600px;
        background: radial-gradient(ellipse at center, rgba(139, 92, 246, 0.12) 0%, rgba(6, 182, 212, 0.06) 40%, transparent 70%);
        z-index: 0;
        pointer-events: none;
      }
.ported-style-page--framer-motion .shell {
        position: relative;
        z-index: 1;
        width: min(1100px, 92vw);
        margin: 0 auto;
        padding: 28px 20px 100px;
      }
.ported-style-page--framer-motion .hero {
        text-align: center;
        padding: clamp(40px, 8vw, 80px) 0 clamp(32px, 6vw, 60px);
      }
.ported-style-page--framer-motion .hero-badge {
        display: inline-flex;
        align-items: center;
        gap: 6px;
        padding: 6px 16px;
        border-radius: 999px;
        border: 1px solid var(--border);
        background: var(--surface);
        font-size: 0.8rem;
        font-weight: 500;
        color: var(--text-muted);
        margin-bottom: 24px;
        animation: ported-framer-motion-fadeUp 0.6s ease both;
      }
.ported-style-page--framer-motion .hero-badge-dot {
        width: 6px;
        height: 6px;
        border-radius: 50%;
        background: var(--accent);
