      }
.ported-style-page--framer-motion h1 {
        font-family: 'Plus Jakarta Sans', 'Noto Sans KR', sans-serif;
        font-size: clamp(2.2rem, 6vw, 4rem);
        font-weight: 800;
        line-height: 1.08;
        letter-spacing: -0.025em;
        animation: ported-framer-motion-fadeUp 0.6s ease 0.1s both;
      }
.ported-style-page--framer-motion .hero-lead {
        margin-top: 20px;
        font-size: 1.05rem;
        line-height: 1.7;
        color: var(--text-muted);
        max-width: 580px;
        margin-left: auto;
        margin-right: auto;
        animation: ported-framer-motion-fadeUp 0.6s ease 0.2s both;
      }
.ported-style-page--framer-motion .hero-pills {
        margin-top: 28px;
        display: flex;
        flex-wrap: wrap;
        justify-content: center;
        gap: 10px;
        animation: ported-framer-motion-fadeUp 0.6s ease 0.3s both;
      }
.ported-style-page--framer-motion .hero-pill {
        display: inline-flex;
        align-items: center;
        gap: 6px;
        padding: 7px 16px;
        border-radius: 999px;
        border: 1px solid var(--border);
        background: var(--surface);
        font-size: 0.82rem;
        font-weight: 500;
        color: var(--text-muted);
        transition: all 0.3s ease;
      }
.ported-style-page--framer-motion .hero-pill:hover {
        border-color: var(--border-hover);
        background: var(--surface-hover);
        color: var(--text);
      }
.ported-style-page--framer-motion .hero-pill code {
