      }
.ported-style-page--framer-motion .bento {
        display: grid;
        grid-template-columns: repeat(3, 1fr);
        gap: 16px;
        margin-top: 8px;
      }
.ported-style-page--framer-motion .bento-card {
        position: relative;
        border-radius: 16px;
        border: 1px solid var(--border);
        background: var(--surface);
        backdrop-filter: blur(12px);
        -webkit-backdrop-filter: blur(12px);
        padding: clamp(20px, 3vw, 32px);
        overflow: hidden;
        transition: border-color 0.3s ease, background 0.3s ease, box-shadow 0.3s ease;
      }
.ported-style-page--framer-motion .bento-card::before {
        content: '';
        position: absolute;
        inset: -1px;
        border-radius: 17px;
        padding: 1px;
        background: linear-gradient(135deg, transparent, transparent);
        -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
        -webkit-mask-composite: xor;
        mask-composite: exclude;
        pointer-events: none;
        transition: background 0.4s ease;
      }
.ported-style-page--framer-motion .bento-card:hover {
        border-color: transparent;
        background: var(--surface-hover);
        
        box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3), 0 0 60px var(--glow);
      }
.ported-style-page--framer-motion .bento-card:hover::before {
        background: linear-gradient(135deg, var(--accent), var(--accent-2));
      }
.ported-style-page--framer-motion .bento-card.featured {
        grid-column: span 2;
      }
.ported-style-page--framer-motion .bento-card.featured::after {
        content: '';
        position: absolute;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
        width: 80%;
        height: 80%;
        background: radial-gradient(ellipse, var(--glow) 0%, transparent 70%);
        z-index: -1;
        pointer-events: none;
      }
.ported-style-page--framer-motion .card-icon {
        width: 40px;
        height: 40px;
        border-radius: 10px;
        border: 1px solid var(--border);
