      }
.ported-style-page--framer-motion .mini-card:nth-child(1) { animation-delay: 0s; }
.ported-style-page--framer-motion .mini-card:nth-child(2) { animation-delay: 0.5s; }
.ported-style-page--framer-motion .mini-card:nth-child(3) { animation-delay: 1s; }
.ported-style-page--framer-motion h2 {
