        animation: ported-framer-motion-fadeUp 0.6s ease 0.75s both;
      }
.ported-style-page--framer-motion pre {
        margin: 14px 0 0;
        white-space: pre-wrap;
        line-height: 1.7;
        color: var(--text-muted);
        font-size: 0.88rem;
        font-family: 'Inter', 'Noto Sans KR', sans-serif;
      }
.ported-style-page--framer-motion button {
        margin-top: 16px;
        border: 1px solid var(--border);
        background: var(--surface);
        color: var(--text);
        border-radius: 999px;
        padding: 10px 22px;
        cursor: pointer;
        font-size: 0.85rem;
        font-weight: 600;
        font-family: 'Inter', 'Noto Sans KR', sans-serif;
        transition: background 0.3s ease, border-color 0.3s ease, box-shadow 0.3s ease, color 0.3s ease;
