@keyframes ported-framer-motion-fadeUp {
        from {
          opacity: 0;
          transform: translateY(24px) scale(0.95);
        }
        to {
          opacity: 1;
          transform: translateY(0) scale(1);
        }
      }
@keyframes ported-framer-motion-gradientMove {
        0% { background-position: 0% 50%; }
        100% { background-position: 300% 50%; }
      }
@keyframes ported-framer-motion-miniPulse {
        0%, 100% { border-color: var(--border); }
        50% { border-color: var(--border-hover); }
      }
@keyframes ported-framer-motion-floatOrb1 {
        0%   { transform: translate(0, 0) rotate(0deg); }
        25%  { transform: translate(80px, -60px) rotate(90deg); }
        50%  { transform: translate(-40px, -120px) rotate(180deg); }
        75%  { transform: translate(-100px, -40px) rotate(270deg); }
        100% { transform: translate(0, 0) rotate(360deg); }
      }
@keyframes ported-framer-motion-floatOrb2 {
        0%   { transform: translate(0, 0) rotate(0deg); }
        25%  { transform: translate(-70px, -80px) rotate(-90deg); }
        50%  { transform: translate(60px, -140px) rotate(-180deg); }
        75%  { transform: translate(90px, -30px) rotate(-270deg); }
        100% { transform: translate(0, 0) rotate(-360deg); }
      }
@keyframes ported-framer-motion-floatOrb3 {
        0%   { transform: translate(0, 0) rotate(0deg); }
        25%  { transform: translate(-50px, 40px) rotate(60deg); }
        50%  { transform: translate(100px, -50px) rotate(120deg); }
        75%  { transform: translate(30px, -100px) rotate(240deg); }
        100% { transform: translate(0, 0) rotate(360deg); }
      }
@keyframes ported-framer-motion-floatOrb4 {
        0%   { transform: translate(0, 0) rotate(0deg); }
        25%  { transform: translate(60px, 50px) rotate(-120deg); }
        50%  { transform: translate(-80px, -60px) rotate(-240deg); }
        75%  { transform: translate(40px, -90px) rotate(-300deg); }
        100% { transform: translate(0, 0) rotate(-360deg); }
