.ported-style-page--claymorphism .clay-character .clay-char-cheek--r { right: 10px; }
.ported-style-page--claymorphism .clay-character .clay-char-mouth { bottom: 18px; width: 18px; height: 9px; }
.ported-style-page--claymorphism .clay-character .clay-char-mouth--small {
