.ported-style-page--claymorphism .clay-character .clay-char-arm--up.clay-char-arm--r { transform: rotate(32deg); }
.ported-style-page--claymorphism .clay-character .clay-char-foot { width: 30px; height: 18px; bottom: -6px; }
.ported-style-page--claymorphism .clay-character .clay-char-foot--l { left: 22px; }
.ported-style-page--claymorphism .clay-character .clay-char-foot--r { right: 22px; }

/* character color variants */
