  background: radial-gradient(circle at 38% 32%, #fff0e0 0%, #ffc8a0 100%);
}
.ported-style-page--claymorphism .clay-character--yellow .clay-char-foot {
  background: linear-gradient(160deg, #ffb0a5, #ff8b7e);
