}
.ported-style-page--claymorphism .clay-character--mint .clay-char-body,
.ported-style-page--claymorphism .clay-character--mint .clay-char-arm {
  background: linear-gradient(160deg, #b0ecd0, #7edbb0);
}
.ported-style-page--claymorphism .clay-character--mint .clay-char-head {
  background: radial-gradient(circle at 38% 32%, #ffe9e3 0%, #ffb0a5 100%);
}
.ported-style-page--claymorphism .clay-character--mint .clay-char-foot {
  background: linear-gradient(160deg, #ddd0ff, #c4a8ff);
  box-shadow: 4px 4px 8px rgba(196, 168, 255, 0.3), inset 3px 3px 6px rgba(255, 255, 255, 0.5), inset -3px -3px 6px rgba(0, 0, 0, 0.08);
