  width: 54px;
  height: 54px;
  border-radius: 18px;
  font-size: 1.6rem;
}

/* responsive */
@media (max-width: 860px) {
  .ported-style-page--claymorphism .hero {
    grid-template-columns: 1fr;
    text-align: center;
  }
  .ported-style-page--claymorphism .hero-copy { text-align: center; }
  .ported-style-page--claymorphism .hero .lead { text-align: center; margin: 0 auto 20px; max-width: 600px; }
  .ported-style-page--claymorphism .hero-tags { justify-content: center; }
  .ported-style-page--claymorphism .hero-stage { min-height: 260px; order: -1; }
  .ported-style-page--claymorphism .clay-character-wrap {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    row-gap: 56px;
  }
  .ported-style-page--claymorphism .clay-recipe-row {
    grid-template-columns: 44px 1fr;
    grid-template-areas: "swatch prop" "swatch code";
    gap: 8px 16px;
    row-gap: 4px;
  }
  .ported-style-page--claymorphism .clay-recipe-swatch { grid-area: swatch; }
  .ported-style-page--claymorphism .clay-recipe-prop { grid-area: prop; }
  .ported-style-page--claymorphism .clay-recipe-code { grid-area: code; }
}
@media (max-width: 600px) {
  .ported-style-page--claymorphism .clay-character-wrap {
    grid-template-columns: 1fr;
    row-gap: 60px;
  }
  .ported-style-page--claymorphism .clay-ball { width: 64px; height: 64px; }
  .ported-style-page--claymorphism .clay-mix-ball { width: 60px !important; height: 60px !important; }
  .ported-style-page--claymorphism .clay-mix-result { width: 76px; height: 76px; }
  .ported-style-page--claymorphism .hero-stage__shape--blob { width: 120px; height: 120px; }
  .ported-style-page--claymorphism .hero-stage__shape--square { width: 70px; height: 70px; }
  .ported-style-page--claymorphism .hero-stage__shape--pill { width: 92px; height: 40px; }
}
@media (prefers-reduced-motion: reduce) {
  .ported-style-page--claymorphism .hero-stage__shape { animation: none !important; }
}

