/* risograph-print */
.ported-style-page--risograph-print {
        --bg: #f5f0e8;
        --ink-1: #ff6b6b;
        --ink-2: #4ecdc4;
        --ink-3: #2c3e50;
        --overprint: #8b5e3c;
        --paper: #ede6d6;
        --line: rgba(44, 62, 80, 0.15);
        --card-bg: rgba(237, 230, 214, 0.85);
      }
.ported-style-page--risograph-print * { box-sizing: border-box; }
.ported-style-page--risograph-print {
        margin: 0;
        color: var(--ink-3);
        font-family: 'Space Mono', monospace;
        background: var(--bg);
        min-height: 100svh;
        position: relative;
      }
.ported-style-page--risograph-print::after {
        content: '';
        position: fixed;
        inset: 0;
        z-index: 9998;
        pointer-events: none;
        opacity: 0.06;
        background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)'/%3E%3C/svg%3E");
        background-repeat: repeat;
        background-size: 256px;
      }
.ported-style-page--risograph-print .halftone-bg {
        position: fixed;
        inset: 0;
        pointer-events: none;
        z-index: 0;
        background-image: radial-gradient(circle, var(--ink-2) 0.5px, transparent 0.5px);
        background-size: 8px 8px;
        opacity: 0.06;
      }
.ported-style-page--risograph-print .shell {
        position: relative;
        z-index: 1;
        width: min(1080px, 92vw);
        margin: 0 auto;
        padding: 28px 20px 80px;
      }
.ported-style-page--risograph-print h1,
.ported-style-page--risograph-print h2 {
        font-family: 'Space Grotesk', sans-serif;
        margin: 0;
      }
.ported-style-page--risograph-print h1 {
        font-size: clamp(2.2rem, 6vw, 5rem);
        line-height: 1.05;
        color: var(--ink-3);
        letter-spacing: -0.03em;
        font-weight: 700;
      }
.ported-style-page--risograph-print h2 {
        font-size: 1.3rem;
        font-weight: 700;
        letter-spacing: -0.01em;
      }
.ported-style-page--risograph-print .reg-marks {
        display: flex;
        justify-content: space-between;
        align-items: center;
        padding: 12px 0;
        margin-bottom: 8px;
      }
.ported-style-page--risograph-print .reg-mark {
        width: 24px;
        height: 24px;
        position: relative;
      }
.ported-style-page--risograph-print .reg-mark::before,
.ported-style-page--risograph-print .reg-mark::after {
        content: '';
        position: absolute;
      }
.ported-style-page--risograph-print .reg-mark::before {
        top: 50%;
        left: 0;
        width: 100%;
        height: 1px;
        background: var(--ink-3);
        transform: translateY(-50%);
      }
.ported-style-page--risograph-print .reg-mark::after {
        left: 50%;
        top: 0;
        width: 1px;
        height: 100%;
        background: var(--ink-3);
        transform: translateX(-50%);
      }
.ported-style-page--risograph-print .reg-mark-circle {
        position: absolute;
        top: 50%;
        left: 50%;
        width: 12px;
        height: 12px;
        border: 1px solid var(--ink-3);
        border-radius: 50%;
        transform: translate(-50%, -50%);
      }
.ported-style-page--risograph-print .reg-marks__info {
        font-size: 0.7rem;
        color: var(--ink-3);
        opacity: 0.5;
        font-family: 'Space Mono', monospace;
        text-transform: uppercase;
        letter-spacing: 0.08em;
      }
.ported-style-page--risograph-print .hero {
        margin-top: 12px;
        position: relative;
