        position: relative;
        display: inline-block;
        font-family: 'Space Grotesk', sans-serif;
        font-size: clamp(2.4rem, 7vw, 5.5rem);
        font-weight: 700;
        line-height: 1.05;
        letter-spacing: -0.03em;
        color: var(--ink-3);
        text-shadow:
          -1.5px 1.5px 0 rgba(255, 107, 107, 0.55),
          2px -1px 0 rgba(78, 205, 196, 0.55);
      }
.ported-style-page--risograph-print .hero__subtitle {
        margin-top: 16px;
        font-family: 'Space Mono', monospace;
        font-size: clamp(0.85rem, 2vw, 1rem);
        line-height: 1.7;
        color: var(--ink-3);
        max-width: 640px;
        opacity: 0.8;
      }
.ported-style-page--risograph-print .hero__edition {
        position: absolute;
        top: 16px;
        right: 20px;
        font-family: 'Space Mono', monospace;
        font-size: 0.75rem;
        color: var(--ink-1);
        letter-spacing: 0.05em;
        text-transform: uppercase;
        opacity: 0.8;
      }
.ported-style-page--risograph-print .hero__halftone-corner {
        position: absolute;
        bottom: -20px;
