        font-family: 'Space Grotesk', sans-serif;
        font-size: 0.74rem;
        font-weight: 700;
        letter-spacing: 0.15em;
        text-transform: uppercase;
        transform: rotate(-4deg);
        opacity: 0.85;
        background: rgba(255, 107, 107, 0.06);
        box-shadow:
          inset 0 0 0 1px var(--ink-1),
          inset 0 0 8px rgba(255, 107, 107, 0.15);
      }
.ported-style-page--risograph-print .press-log__body {
        display: grid;
        grid-template-columns: 1.6fr 1fr;
        gap: 28px;
      }
.ported-style-page--risograph-print .press-log__checks {
        list-style: none;
        margin: 0;
        padding: 0;
        display: flex;
        flex-direction: column;
        gap: 0;
      }
.ported-style-page--risograph-print .press-log__row {
        display: grid;
        grid-template-columns: 28px 1fr auto;
        align-items: center;
        gap: 12px;
        padding: 6px 0;
        font-family: 'Space Mono', monospace;
        font-size: 0.82rem;
        color: var(--ink-3);
        opacity: 0.45;
        border-bottom: 1px dotted rgba(44, 62, 80, 0.12);
      }
.ported-style-page--risograph-print .press-log__row:last-child { border-bottom: none; }
.ported-style-page--risograph-print .press-log__row--done { opacity: 0.92; }
.ported-style-page--risograph-print .press-log__row--active {
        opacity: 1;
        color: var(--ink-1);
        font-weight: 700;
      }
.ported-style-page--risograph-print .press-log__row--active .press-log__check {
        color: var(--ink-1);
        animation: ported-risograph-print-pulse 1.4s ease-in-out infinite;
      }
.ported-style-page--risograph-print .press-log__check {
        font-family: 'Space Grotesk', sans-serif;
        font-size: 1.1rem;
        text-align: center;
        line-height: 1;
        color: var(--ink-3);
      }
.ported-style-page--risograph-print .press-log__row--done .press-log__check { color: var(--ink-2); }
.ported-style-page--risograph-print .press-log__time {
        font-size: 0.74rem;
        opacity: 0.7;
        letter-spacing: 0.04em;
      }
.ported-style-page--risograph-print .press-log__gauges {
        display: flex;
        flex-direction: column;
        gap: 12px;
        padding-left: 20px;
        border-left: 1px dashed var(--line);
      }
.ported-style-page--risograph-print .press-gauge { display: flex; flex-direction: column; gap: 5px; }
.ported-style-page--risograph-print .press-gauge__top {
        display: flex;
        justify-content: space-between;
        align-items: baseline;
      }
.ported-style-page--risograph-print .press-gauge__label {
        font-family: 'Space Mono', monospace;
        font-size: 0.68rem;
        color: var(--ink-3);
        opacity: 0.7;
        letter-spacing: 0.05em;
      }
.ported-style-page--risograph-print .press-gauge__val {
        font-family: 'Space Grotesk', sans-serif;
        font-size: 0.85rem;
        font-weight: 700;
        color: var(--ink-3);
        letter-spacing: -0.02em;
      }
.ported-style-page--risograph-print .press-gauge__bar {
        height: 10px;
        background: var(--bg);
        border: 1.5px solid var(--ink-3);
        overflow: hidden;
        position: relative;
      }
.ported-style-page--risograph-print .press-gauge__bar::after {
        content: '';
        position: absolute;
        inset: 0;
        background-image: repeating-linear-gradient(
          90deg,
          transparent 0,
          transparent 9px,
          rgba(44, 62, 80, 0.15) 9px,
          rgba(44, 62, 80, 0.15) 10px
        );
        pointer-events: none;
      }
.ported-style-page--risograph-print .press-gauge__fill { height: 100%; position: relative; }
.ported-style-page--risograph-print .press-gauge__fill--ink1  { background-color: var(--ink-1); }
.ported-style-page--risograph-print .press-gauge__fill--ink2  { background-color: var(--ink-2); }
.ported-style-page--risograph-print .press-gauge__fill--paper { background-color: var(--overprint); opacity: 0.7; }
.ported-style-page--risograph-print .press-log__signature {
        margin-top: 4px;
        padding-top: 14px;
        border-top: 1px dashed var(--line);
        display: flex;
        flex-direction: column;
        gap: 2px;
      }
.ported-style-page--risograph-print .press-log__sig-label {
        font-family: 'Space Mono', monospace;
        font-size: 0.66rem;
        text-transform: uppercase;
        letter-spacing: 0.1em;
        opacity: 0.5;
        color: var(--ink-3);
      }
.ported-style-page--risograph-print .press-log__sig-glyph {
        width: 130px;
        height: 28px;
        color: var(--ink-1);
        margin-top: 2px;
      }
.ported-style-page--risograph-print .press-log__sig-name {
        font-family: 'Space Grotesk', sans-serif;
        font-size: 0.78rem;
        font-weight: 600;
        color: var(--ink-3);
        opacity: 0.75;
      }
.ported-style-page--risograph-print .press-log__foot {
        margin-top: 14px;
        padding-top: 12px;
        border-top: 1px dashed var(--line);
        display: flex;
        gap: 18px;
        flex-wrap: wrap;
        font-family: 'Space Mono', monospace;
        font-size: 0.62rem;
        color: var(--ink-3);
        opacity: 0.45;
        text-transform: uppercase;
        letter-spacing: 0.1em;
      }
.ported-style-page--risograph-print .press-log__foot-tag::before { content: '· '; opacity: 0.6; }
.ported-style-page--risograph-print .press-log__foot-tag:first-child::before { content: ''; }

@keyframes ported-risograph-print-pulse {
        0%, 100% { opacity: 1; transform: translateX(0); }
        50% { opacity: 0.5; transform: translateX(1px); }
      }

/* ═══ Run Specification Sheet ═══ */
.ported-style-page--risograph-print .spec-sheet {
        margin-top: 24px;
        background: var(--bg);
        border: 2px solid var(--ink-3);
        border-radius: 4px;
        padding: 22px 24px;
        position: relative;
        overflow: hidden;
      }
.ported-style-page--risograph-print .spec-sheet::before {
        content: '';
        position: absolute;
        inset: 0;
        background-image: radial-gradient(circle, var(--ink-3) 0.4px, transparent 0.4px);
        background-size: 5px 5px;
        opacity: 0.025;
        pointer-events: none;
      }
.ported-style-page--risograph-print .spec-sheet__head {
        display: flex;
        justify-content: space-between;
        align-items: center;
        gap: 16px;
        padding-bottom: 14px;
        border-bottom: 2px solid var(--ink-3);
        margin-bottom: 12px;
      }
.ported-style-page--risograph-print .spec-sheet__label {
        font-family: 'Space Grotesk', sans-serif;
        font-size: 0.95rem;
        font-weight: 700;
        color: var(--ink-3);
        letter-spacing: -0.01em;
      }
.ported-style-page--risograph-print .spec-sheet__barcode {
        display: flex;
        align-items: center;
        gap: 1.5px;
        height: 28px;
      }
.ported-style-page--risograph-print .spec-sheet__barcode span {
        height: 100%;
        background: var(--ink-3);
        display: inline-block;
      }
.ported-style-page--risograph-print .spec-sheet__barcode em {
        margin-left: 10px;
        font-style: normal;
        font-family: 'Space Mono', monospace;
        font-size: 0.7rem;
        color: var(--ink-3);
        letter-spacing: 0.08em;
      }
.ported-style-page--risograph-print .spec-table {
        width: 100%;
        border-collapse: collapse;
        font-family: 'Space Mono', monospace;
        font-size: 0.78rem;
      }
.ported-style-page--risograph-print .spec-table tr { border-bottom: 1px dashed var(--line); }
.ported-style-page--risograph-print .spec-table tr:last-child { border-bottom: none; }
.ported-style-page--risograph-print .spec-table th {
        text-align: left;
        padding: 10px 12px 10px 0;
        font-weight: 400;
        font-family: 'Space Mono', monospace;
        text-transform: uppercase;
        letter-spacing: 0.08em;
        font-size: 0.66rem;
        color: var(--ink-3);
        opacity: 0.55;
        vertical-align: middle;
        width: 14%;
      }
.ported-style-page--risograph-print .spec-table th.spec-table__th2 {
        border-left: 1px dashed var(--line);
        padding-left: 18px;
      }
.ported-style-page--risograph-print .spec-table td {
        padding: 10px 12px;
        color: var(--ink-3);
        font-family: 'Space Grotesk', sans-serif;
        font-size: 0.88rem;
        font-weight: 500;
        letter-spacing: -0.005em;
        vertical-align: middle;
      }
.ported-style-page--risograph-print .spec-bar {
        display: inline-block;
        width: 80px;
        height: 8px;
        background: var(--paper);
        border: 1.5px solid var(--ink-3);
        position: relative;
        vertical-align: middle;
        margin-right: 8px;
        overflow: hidden;
      }
.ported-style-page--risograph-print .spec-bar__fill { display: block; height: 100%; }
.ported-style-page--risograph-print .spec-bar__fill--ink1 { background: var(--ink-1); }
.ported-style-page--risograph-print .spec-bar__fill--ink2 { background: var(--ink-2); }
.ported-style-page--risograph-print .spec-bar__fill--op   { background: var(--overprint); }
.ported-style-page--risograph-print .spec-em {
        font-style: normal;
        font-family: 'Space Mono', monospace;
        font-size: 0.74rem;
        color: var(--ink-3);
        opacity: 0.7;
        letter-spacing: 0.03em;
      }

/* ═══ Editorial Zine Spread ═══ */
.ported-style-page--risograph-print .zine-spread {
        margin-top: 24px;
        position: relative;
        background: var(--paper);
        border: 2px solid var(--ink-3);
        border-radius: 4px;
        padding: 36px clamp(28px, 5vw, 56px) 40px;
        overflow: hidden;
      }
.ported-style-page--risograph-print .zine-spread__grain {
        position: absolute;
        inset: 0;
        background-image: radial-gradient(circle, var(--ink-3) 0.35px, transparent 0.35px);
        background-size: 5px 5px;
        opacity: 0.045;
        pointer-events: none;
      }
.ported-style-page--risograph-print .zine-spread__head {
        display: flex;
        justify-content: space-between;
        align-items: center;
        padding-bottom: 18px;
        border-bottom: 1px solid var(--line);
        margin-bottom: 18px;
        font-family: 'Space Mono', monospace;
        font-size: 0.66rem;
        text-transform: uppercase;
        letter-spacing: 0.12em;
        color: var(--ink-3);
        opacity: 0.55;
      }
.ported-style-page--risograph-print .zine-spread__column {
        flex: 1;
        text-align: center;
        opacity: 0.85;
      }
.ported-style-page--risograph-print .zine-spread__folio--right { text-align: right; }
.ported-style-page--risograph-print .zine-spread__title {
        font-family: 'Space Grotesk', sans-serif !important;
        font-size: clamp(1.6rem, 3.6vw, 2.6rem) !important;
        font-weight: 700;
        letter-spacing: -0.025em;
        line-height: 1.15;
        color: var(--ink-3);
        margin: 0 0 8px 0 !important;
        position: relative;
        z-index: 1;
        max-width: 760px;
      }
.ported-style-page--risograph-print .zine-spread__title em {
        font-style: italic;
        color: var(--ink-1);
        text-shadow: 1.2px -1.2px 0 rgba(78, 205, 196, 0.5);
      }
.ported-style-page--risograph-print .zine-spread__byline {
        font-family: 'Space Mono', monospace;
        font-size: 0.72rem;
        color: var(--ink-3);
        opacity: 0.55;
        letter-spacing: 0.04em;
        margin-bottom: 22px;
      }
.ported-style-page--risograph-print .zine-spread__cols {
        display: grid;
        grid-template-columns: 1fr 0.85fr 1fr;
        gap: 28px;
        position: relative;
        z-index: 1;
      }
.ported-style-page--risograph-print .zine-spread__col {
        display: flex;
        flex-direction: column;
        gap: 14px;
      }
.ported-style-page--risograph-print .zine-spread__para {
        font-family: 'Space Mono', monospace;
        font-size: 0.85rem;
        line-height: 1.75;
        color: var(--ink-3);
        margin: 0;
        opacity: 0.88;
      }
.ported-style-page--risograph-print .zine-spread__para strong {
        color: var(--ink-1);
        font-weight: 700;
      }
.ported-style-page--risograph-print .zine-spread__para--lead { position: relative; }
.ported-style-page--risograph-print .zine-spread__dropcap {
        float: left;
        font-family: 'Space Grotesk', sans-serif;
        font-size: 4.2rem;
        font-weight: 700;
        line-height: 0.85;
        margin: 4px 8px 0 0;
        color: var(--ink-1);
        text-shadow:
          -1.5px 1.5px 0 rgba(78, 205, 196, 0.55),
          2px -1px 0 rgba(44, 62, 80, 0.2);
        letter-spacing: -0.04em;
      }
.ported-style-page--risograph-print .zine-spread__dc-target { font-family: inherit; }
.ported-style-page--risograph-print .zine-spread__pull {
        position: relative;
        padding: 16px 4px;
        border-top: 2px solid var(--ink-3);
        border-bottom: 2px solid var(--ink-3);
        align-self: center;
      }
.ported-style-page--risograph-print .zine-spread__pull-mark {
        position: absolute;
        top: -14px;
        left: -2px;
        background: var(--paper);
        padding: 0 6px;
        font-family: 'Space Grotesk', sans-serif;
        font-size: 1.2rem;
        font-weight: 700;
        color: var(--ink-1);
      }
.ported-style-page--risograph-print .zine-spread__pull blockquote {
        margin: 0;
        font-family: 'Space Grotesk', sans-serif;
        font-size: clamp(1.05rem, 2vw, 1.3rem);
        font-weight: 600;
        line-height: 1.25;
        letter-spacing: -0.01em;
        color: var(--ink-3);
      }
.ported-style-page--risograph-print .zine-spread__pull blockquote em {
        font-style: italic;
        color: var(--ink-1);
        text-shadow: 1px -1px 0 rgba(78, 205, 196, 0.55);
      }
.ported-style-page--risograph-print .zine-spread__pull-attr {
        margin-top: 10px;
        font-family: 'Space Mono', monospace;
        font-size: 0.66rem;
        color: var(--ink-3);
        opacity: 0.6;
        letter-spacing: 0.06em;
      }
.ported-style-page--risograph-print .zine-spread__footnotes {
        list-style: none;
        padding: 10px 0 0;
        margin: 8px 0 0 0;
        display: flex;
        flex-direction: column;
        gap: 6px;
        border-top: 1px dotted var(--line);
      }
.ported-style-page--risograph-print .zine-spread__footnotes li {
        font-family: 'Space Mono', monospace;
        font-size: 0.7rem;
        color: var(--ink-3);
        opacity: 0.6;
        line-height: 1.5;
        display: flex;
        gap: 8px;
        align-items: baseline;
      }
.ported-style-page--risograph-print .zine-spread__footnotes sup {
        color: var(--ink-1);
        font-weight: 700;
        font-size: 0.7rem;
      }
.ported-style-page--risograph-print .zine-spread__margin {
        position: absolute;
        display: flex;
        align-items: center;
        gap: 6px;
        color: var(--ink-1);
        opacity: 0.85;
        transform: rotate(-2deg);
        z-index: 2;
        pointer-events: none;
      }
.ported-style-page--risograph-print .zine-spread__margin--left  { top: 38%; left: 6px; flex-direction: row; }
.ported-style-page--risograph-print .zine-spread__margin--right {
        top: 56%;
        right: 6px;
        flex-direction: row;
        color: var(--ink-2);
        transform: rotate(3deg);
      }
.ported-style-page--risograph-print .zine-spread__arrow { width: 50px; height: 14px; }
.ported-style-page--risograph-print .zine-spread__margin-text {
        font-family: 'Space Mono', monospace;
        font-size: 0.7rem;
        font-style: italic;
        letter-spacing: 0.02em;
        white-space: nowrap;
        background: var(--paper);
        padding: 0 4px;
      }
.ported-style-page--risograph-print .zine-spread__margin-text--teal { color: var(--ink-2); }

/* ═══ Catalog of Mini Zine Covers ═══ */
.ported-style-page--risograph-print .catalog { margin-top: 24px; }
.ported-style-page--risograph-print .catalog__head {
        display: flex;
        justify-content: space-between;
        align-items: baseline;
        margin-bottom: 14px;
        padding: 0 4px;
      }
.ported-style-page--risograph-print .catalog__label {
        font-family: 'Space Mono', monospace;
        font-size: 0.72rem;
        text-transform: uppercase;
        letter-spacing: 0.1em;
        color: var(--ink-3);
        opacity: 0.55;
      }
.ported-style-page--risograph-print .catalog__counter {
        font-family: 'Space Mono', monospace;
        font-size: 0.7rem;
        color: var(--ink-1);
        letter-spacing: 0.06em;
      }
.ported-style-page--risograph-print .catalog__grid {
        display: grid;
        grid-template-columns: repeat(4, 1fr);
        gap: 14px;
      }
.ported-style-page--risograph-print .cover {
        position: relative;
        aspect-ratio: 3 / 4;
        border: 2px solid var(--ink-3);
        border-radius: 4px;
        padding: 14px 14px 16px;
        overflow: hidden;
        display: flex;
        flex-direction: column;
        justify-content: space-between;
        transition: transform 0.3s ease, box-shadow 0.3s ease;
        animation: ported-risograph-print-rise 0.6s ease both;
      }
.ported-style-page--risograph-print .cover:nth-child(1) { animation-delay: 0.05s; }
.ported-style-page--risograph-print .cover:nth-child(2) { animation-delay: 0.1s; }
.ported-style-page--risograph-print .cover:nth-child(3) { animation-delay: 0.15s; }
.ported-style-page--risograph-print .cover:nth-child(4) { animation-delay: 0.2s; }
.ported-style-page--risograph-print .cover:nth-child(5) { animation-delay: 0.25s; }
.ported-style-page--risograph-print .cover:nth-child(6) { animation-delay: 0.3s; }
.ported-style-page--risograph-print .cover:nth-child(7) { animation-delay: 0.35s; }
.ported-style-page--risograph-print .cover:nth-child(8) { animation-delay: 0.4s; }
.ported-style-page--risograph-print .cover:hover {
        transform: translateY(-3px) rotate(0deg) !important;
        box-shadow: 4px 6px 0 var(--ink-3);
      }
.ported-style-page--risograph-print .cover--red       { background: var(--ink-1); color: var(--paper); }
.ported-style-page--risograph-print .cover--teal      { background: var(--ink-2); color: var(--ink-3); }
.ported-style-page--risograph-print .cover--paper     { background: var(--paper); color: var(--ink-3); }
.ported-style-page--risograph-print .cover--overprint { background: var(--overprint); color: var(--paper); }
.ported-style-page--risograph-print .cover--ink3      { background: var(--ink-3); color: var(--paper); }
.ported-style-page--risograph-print .cover--rot-left  { transform: rotate(-1.4deg); }
.ported-style-page--risograph-print .cover--rot-right { transform: rotate(1.4deg); }
.ported-style-page--risograph-print .cover__halftone {
        position: absolute;
        inset: 0;
        background-image: radial-gradient(circle, currentColor 0.7px, transparent 0.7px);
        background-size: 6px 6px;
        opacity: 0.18;
        mix-blend-mode: multiply;
        pointer-events: none;
      }
.ported-style-page--risograph-print .cover--red .cover__halftone       { color: var(--paper); opacity: 0.32; mix-blend-mode: screen; }
.ported-style-page--risograph-print .cover--ink3 .cover__halftone      { color: var(--ink-1); opacity: 0.22; mix-blend-mode: screen; }
.ported-style-page--risograph-print .cover--overprint .cover__halftone { color: var(--paper); opacity: 0.28; mix-blend-mode: screen; }
.ported-style-page--risograph-print .cover__halftone--dense {
        background-size: 3px 3px;
        opacity: 0.12;
      }
.ported-style-page--risograph-print .cover__no {
        font-family: 'Space Mono', monospace;
        font-size: 0.68rem;
        letter-spacing: 0.1em;
        opacity: 0.85;
        position: relative;
        z-index: 1;
      }
.ported-style-page--risograph-print .cover__title {
        font-family: 'Space Grotesk', sans-serif;
        font-size: clamp(1.6rem, 4vw, 2.2rem);
        font-weight: 700;
        letter-spacing: -0.03em;
        line-height: 0.95;
        margin: 16px 0 0;
        text-shadow:
          -1px 1px 0 rgba(44, 62, 80, 0.18),
          1px -1px 0 rgba(255, 255, 255, 0.18);
        position: relative;
        z-index: 1;
      }
.ported-style-page--risograph-print .cover__title--alt   { font-size: clamp(1.3rem, 3.2vw, 1.7rem); line-height: 1; }
.ported-style-page--risograph-print .cover__title--small { font-size: clamp(1.1rem, 2.6vw, 1.5rem); line-height: 1.05; }
.ported-style-page--risograph-print .cover__title--light {
        text-shadow:
          -1px 1px 0 var(--ink-1),
          1.5px -1.5px 0 var(--ink-2);
      }
.ported-style-page--risograph-print .cover__sub {
        font-family: 'Space Mono', monospace;
        font-size: 0.66rem;
        line-height: 1.45;
        opacity: 0.82;
        margin-top: auto;
        max-width: 92%;
        position: relative;
        z-index: 1;
      }
.ported-style-page--risograph-print .cover__sub--light { opacity: 0.7; }
.ported-style-page--risograph-print .cover__stamp {
        position: absolute;
        right: 10px;
        bottom: 10px;
        font-family: 'Space Mono', monospace;
        font-size: 0.56rem;
        font-weight: 700;
        letter-spacing: 0.12em;
        padding: 3px 6px;
        border: 1px solid currentColor;
        opacity: 0.72;
        z-index: 2;
        transform: rotate(-2deg);
        background: transparent;
      }
.ported-style-page--risograph-print .cover__stamp--light { color: var(--paper); }

/* ═══ Studio History Timeline ═══ */
.ported-style-page--risograph-print .riso-history {
        margin-top: 24px;
        background: var(--paper);
        border: 2px solid var(--ink-3);
        border-radius: 4px;
        padding: 28px clamp(20px, 4vw, 36px) 32px;
        position: relative;
        overflow: hidden;
      }
.ported-style-page--risograph-print .riso-history::after {
        content: '';
        position: absolute;
        inset: 0;
        background-image: radial-gradient(circle, var(--ink-2) 0.35px, transparent 0.35px);
        background-size: 6px 6px;
        opacity: 0.04;
        pointer-events: none;
      }
