/* paper-cut — Goki Folio composition.
   Replaces the previous technique-catalogue with a single, opinionated portfolio
   that uses the paper-cut palette and discipline end to end. */

.ported-style-page--paper-cut {
  /* Palette — five papers, one accent. The accent appears exactly once. */
  --bg: #efe7d6;
  --substrate: #f4ecd9;
  --paper-1: #ffffff;
  --paper-2: #e8c5a5;
  --paper-3: #8eb59b;
  --paper-4: #486b8c;
  --paper-accent: #c84a32;

  --text: #221d16;
  --ink-muted: #5a4f3f;
  --ink-faint: #8c8273;

  --shadow: rgba(34, 29, 22, 0.20);
  --shadow-soft: rgba(34, 29, 22, 0.10);
  --shadow-light: rgba(34, 29, 22, 0.06);

  /* Type — Pretendard for Korean-first reading, Outfit for Latin display polish,
     IBM Plex Mono for metadata. Pretendard handles both Korean and Latin cleanly,
     so it leads every stack. */
  --font-display: 'Pretendard Variable', 'Pretendard', 'Outfit', 'Inter Display', system-ui, sans-serif;
  --font-body: 'Pretendard Variable', 'Pretendard', 'Inter', system-ui, sans-serif;
  --font-mono: 'IBM Plex Mono', 'JetBrains Mono', ui-monospace, monospace;

  /* Letter-spacing tuned for mixed Korean / Latin — Korean does not tolerate the
     tight tracking Latin display can. -0.01em on display is the maximum. */
  --tracking-display: -0.01em;
  --tracking-headline: -0.005em;
  --tracking-body: 0;
  --tracking-mono: 0.18em;

  --measure-prose: 56ch;
  --measure-narrow: 40ch;
  --measure-headline: 22ch;

  --space-section: clamp(72px, 9vw, 144px);
  --space-block: 36px;

  background: var(--bg);
  color: var(--text);
  font-family: var(--font-body);
  min-height: 100vh;
}

.ported-style-page--paper-cut * { box-sizing: border-box; margin: 0; padding: 0; }

.ported-style-page--paper-cut .shell {
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 clamp(20px, 4vw, 56px);
}

.ported-style-page--paper-cut ::selection {
  background: var(--text);
  color: var(--bg);
}

.ported-style-page--paper-cut a {
  color: inherit;
  text-decoration: none;
}

/* ───────────────────────────────────────────────────────────────────────
   Hero — asymmetric, statement headline + layered paper scene
   ─────────────────────────────────────────────────────────────────────── */

.ported-style-page--paper-cut .gf-hero {
  display: grid;
  grid-template-columns: 1.05fr 1fr;
  gap: clamp(36px, 6vw, 96px);
  align-items: center;
  padding: clamp(64px, 9vw, 132px) 0 var(--space-section);
}

.ported-style-page--paper-cut .gf-hero__lead {
  display: flex;
  flex-direction: column;
  gap: 28px;
}

.ported-style-page--paper-cut .gf-hero__title {
  font-family: var(--font-display);
  font-size: clamp(2.6rem, 7.6vw, 5.6rem);
  font-weight: 800;
  line-height: 0.98;
  letter-spacing: var(--tracking-display);
  color: var(--text);
  max-width: var(--measure-headline);
  word-break: keep-all;
}

.ported-style-page--paper-cut .gf-hero__sub {
  font-family: var(--font-body);
  font-size: clamp(1rem, 1.35vw, 1.15rem);
  font-weight: 500;
  line-height: 1.7;
  letter-spacing: var(--tracking-body);
  color: var(--ink-muted);
  max-width: 36ch;
  word-break: keep-all;
}

.ported-style-page--paper-cut .gf-hero__cta-row {
  display: flex;
  align-items: center;
  gap: 20px;
  flex-wrap: wrap;
  margin-top: 6px;
}

.ported-style-page--paper-cut .gf-cta {
  display: inline-flex;
  align-items: center;
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 0.95rem;
  letter-spacing: -0.005em;
  color: var(--text);
  padding: 10px 18px;
  background: var(--paper-2);
  border-radius: 6px;
  box-shadow: 4px 4px 0 var(--shadow);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.ported-style-page--paper-cut .gf-cta:hover {
  transform: translate(-2px, -2px);
  box-shadow: 6px 6px 0 var(--shadow);
}

.ported-style-page--paper-cut .gf-hero__visual {
  width: 100%;
}

/* ───────────────────────────────────────────────────────────────────────
   Hero scene — layered paper composition
   ─────────────────────────────────────────────────────────────────────── */

.ported-style-page--paper-cut .gf-scene {
  position: relative;
  width: 100%;
  aspect-ratio: 4 / 5;
  background: var(--substrate);
  overflow: hidden;
  border-radius: 6px;
  box-shadow:
    8px 8px 0 var(--shadow-soft),
    18px 18px 0 var(--shadow);
}

.ported-style-page--paper-cut .gf-scene__sky {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, #f4ecd9 0%, #e8c5a5 55%, #d8a984 100%);
}

.ported-style-page--paper-cut .gf-scene__sun {
  position: absolute;
  top: 14%;
  right: 18%;
  width: 24%;
  aspect-ratio: 1;
  background: #fff;
  border-radius: 50%;
  box-shadow: 4px 4px 0 var(--shadow-soft);
}

.ported-style-page--paper-cut .gf-scene__mountain {
  position: absolute;
  left: 0;
  right: 0;
}

.ported-style-page--paper-cut .gf-scene__mountain--far {
  bottom: 38%;
  height: 46%;
  background: var(--paper-3);
  clip-path: polygon(0 100%, 0 55%, 14% 38%, 28% 60%, 42% 30%, 58% 55%, 74% 22%, 88% 48%, 100% 35%, 100% 100%);
  box-shadow: 0 4px 0 rgba(0, 0, 0, 0.06);
}

.ported-style-page--paper-cut .gf-scene__mountain--mid {
  bottom: 22%;
  height: 42%;
  background: var(--paper-4);
  clip-path: polygon(0 100%, 0 70%, 18% 42%, 36% 70%, 52% 38%, 68% 64%, 84% 28%, 100% 56%, 100% 100%);
  box-shadow: 0 4px 0 rgba(0, 0, 0, 0.10);
}

.ported-style-page--paper-cut .gf-scene__mountain--fg {
  bottom: 0;
  height: 32%;
  background: var(--text);
  clip-path: polygon(0 100%, 0 30%, 24% 56%, 50% 18%, 76% 48%, 100% 28%, 100% 100%);
}

.ported-style-page--paper-cut .gf-scene__pine {
  position: absolute;
  bottom: 24%;
  width: 0;
  height: 0;
  border-left: calc(var(--pine-size) / 2) solid transparent;
  border-right: calc(var(--pine-size) / 2) solid transparent;
  border-bottom: calc(var(--pine-size) * 1.4) solid var(--text);
}

.ported-style-page--paper-cut .gf-scene__poppy {
  position: absolute;
  left: 38%;
  bottom: 14%;
  width: 8px;
  height: 8px;
  background: var(--paper-accent);
  border-radius: 50%;
  box-shadow: 0 0 0 3px var(--paper-2);
}

/* ───────────────────────────────────────────────────────────────────────
   Mono caption — used everywhere as the small editorial label
   ─────────────────────────────────────────────────────────────────────── */

.ported-style-page--paper-cut .gf-mono {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: var(--tracking-mono);
  color: var(--ink-muted);
  display: inline-block;
}

/* ───────────────────────────────────────────────────────────────────────
   Manifesto — narrow measure, generous spacing, display lede
   ─────────────────────────────────────────────────────────────────────── */

.ported-style-page--paper-cut .gf-manifesto {
  max-width: var(--measure-prose);
  margin: 0 auto;
  padding: 0 0 var(--space-section);
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.ported-style-page--paper-cut .gf-manifesto__lede {
  font-family: var(--font-display);
  font-size: clamp(1.55rem, 3vw, 2.2rem);
  font-weight: 600;
  line-height: 1.32;
  letter-spacing: var(--tracking-headline);
  color: var(--text);
  word-break: keep-all;
}

.ported-style-page--paper-cut .gf-manifesto__body {
  font-family: var(--font-body);
  font-size: 16px;
  font-weight: 500;
  line-height: 1.7;
  color: var(--ink-muted);
  word-break: keep-all;
}

/* ───────────────────────────────────────────────────────────────────────
   Selected works — three alternating rows
   ─────────────────────────────────────────────────────────────────────── */

.ported-style-page--paper-cut .gf-works {
  padding: 0 0 var(--space-section);
}

.ported-style-page--paper-cut .gf-works__head {
  margin-bottom: 24px;
}

.ported-style-page--paper-cut .gf-work {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: clamp(32px, 5vw, 64px);
  align-items: center;
  padding: 48px 0;
  border-top: 1px solid rgba(34, 29, 22, 0.20);
}

.ported-style-page--paper-cut .gf-work--right .gf-work__piece { order: 2; }
.ported-style-page--paper-cut .gf-work--right .gf-work__text { order: 1; }

.ported-style-page--paper-cut .gf-work__piece {
  /* Each piece is wrapped in a paper-on-paper surface treatment. */
  border-radius: 4px;
  box-shadow:
    6px 6px 0 var(--shadow-soft),
    12px 12px 0 var(--shadow);
  overflow: hidden;
}

.ported-style-page--paper-cut .gf-work__text {
  display: flex;
  flex-direction: column;
  gap: 14px;
  max-width: 38ch;
}

.ported-style-page--paper-cut .gf-work__title {
  font-family: var(--font-display);
  font-size: clamp(1.7rem, 3.4vw, 2.6rem);
  font-weight: 800;
  line-height: 1.05;
  letter-spacing: var(--tracking-display);
  color: var(--text);
  word-break: keep-all;
}

.ported-style-page--paper-cut .gf-work__caption {
  font-family: var(--font-display);
  font-size: 18px;
  font-weight: 500;
  line-height: 1.4;
  color: var(--ink-muted);
  word-break: keep-all;
}

.ported-style-page--paper-cut .gf-work__body {
  font-family: var(--font-body);
  font-size: 15px;
  font-weight: 500;
  line-height: 1.7;
  color: var(--ink-muted);
  word-break: keep-all;
}

/* ───────────────────────────────────────────────────────────────────────
   Work pieces — three unique compositions
   ─────────────────────────────────────────────────────────────────────── */

.ported-style-page--paper-cut .gf-piece {
  position: relative;
  width: 100%;
  aspect-ratio: 5 / 4;
  overflow: hidden;
}

/* Harbour at Five */
.ported-style-page--paper-cut .gf-piece--harbour { background: #d4e2dc; }
.ported-style-page--paper-cut .gf-harbour__sun {
  position: absolute;
  top: 14%; right: 20%;
  width: 20%; aspect-ratio: 1;
  background: var(--paper-2);
  border-radius: 50%;
}
.ported-style-page--paper-cut .gf-harbour__band { position: absolute; left: 0; right: 0; }
.ported-style-page--paper-cut .gf-harbour__band--1 { top: 54%; bottom: 36%; background: var(--paper-3); }
.ported-style-page--paper-cut .gf-harbour__band--2 { top: 64%; bottom: 24%; background: var(--paper-4); }
.ported-style-page--paper-cut .gf-harbour__band--3 { top: 78%; bottom: 10%; background: var(--text); }
.ported-style-page--paper-cut .gf-harbour__boat {
  position: absolute;
  width: 0; height: 0;
  border-left: 12px solid transparent;
  border-right: 12px solid transparent;
  border-bottom: 14px solid var(--text);
}
.ported-style-page--paper-cut .gf-harbour__boat--a { left: 24%; bottom: 20%; }
.ported-style-page--paper-cut .gf-harbour__boat--b {
  left: 58%; bottom: 24%;
  border-left-width: 9px;
  border-right-width: 9px;
  border-bottom-width: 10px;
}

/* Meadow, after Rain */
.ported-style-page--paper-cut .gf-piece--meadow { background: var(--paper-2); }
.ported-style-page--paper-cut .gf-meadow__sky {
  position: absolute;
  left: 0; right: 0; top: 0;
  height: 50%;
  background: var(--substrate);
}
.ported-style-page--paper-cut .gf-meadow__hill {
  position: absolute;
  left: 0; right: 0;
  bottom: 38%;
  height: 24%;
  background: var(--paper-3);
  clip-path: polygon(0 100%, 0 60%, 30% 30%, 60% 70%, 100% 40%, 100% 100%);
}
.ported-style-page--paper-cut .gf-meadow__ground {
  position: absolute;
  left: 0; right: 0;
  bottom: 0;
  height: 40%;
  background: var(--text);
  clip-path: polygon(0 100%, 0 40%, 100% 26%, 100% 100%);
}
.ported-style-page--paper-cut .gf-meadow__poppy {
  position: absolute;
  width: 12px;
  height: 12px;
  background: var(--paper-accent);
  border-radius: 50%;
}

/* Night Census */
.ported-style-page--paper-cut .gf-piece--city { background: #3a4a5e; }
.ported-style-page--paper-cut .gf-city__moon {
  position: absolute;
  top: 14%; left: 18%;
  width: 14%; aspect-ratio: 1;
  background: var(--substrate);
  border-radius: 50%;
}
.ported-style-page--paper-cut .gf-city__skyline {
  position: absolute;
  inset: 38% 0 0 0;
  background: var(--text);
  clip-path: polygon(
    0 100%, 0 60%, 8% 60%, 8% 30%, 18% 30%, 18% 50%, 28% 50%, 28% 18%,
    40% 18%, 40% 46%, 52% 46%, 52% 24%, 64% 24%, 64% 52%, 78% 52%, 78% 14%,
    92% 14%, 92% 44%, 100% 44%, 100% 100%
  );
}
.ported-style-page--paper-cut .gf-city__window {
  position: absolute;
  width: 4px; height: 4px;
  background: var(--paper-2);
}

/* ───────────────────────────────────────────────────────────────────────
   Materials & rules
   ─────────────────────────────────────────────────────────────────────── */

.ported-style-page--paper-cut .gf-materials {
  display: flex;
  flex-direction: column;
  gap: 48px;
  padding: 0 0 var(--space-section);
}

.ported-style-page--paper-cut .gf-materials__head {
  display: flex;
  flex-direction: column;
  gap: 14px;
  max-width: 46ch;
}

.ported-style-page--paper-cut .gf-materials__title {
  font-family: var(--font-display);
  font-size: clamp(1.7rem, 3.6vw, 2.4rem);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: var(--tracking-display);
  color: var(--text);
  word-break: keep-all;
}

.ported-style-page--paper-cut .gf-swatches {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
}

.ported-style-page--paper-cut .gf-swatch {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.ported-style-page--paper-cut .gf-swatch__chip {
  aspect-ratio: 4 / 5;
  border-radius: 4px;
  box-shadow: 4px 4px 0 var(--shadow);
  border: 1px solid var(--shadow-light);
}

.ported-style-page--paper-cut .gf-swatch__meta {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.ported-style-page--paper-cut .gf-swatch__meta strong {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 14px;
  color: var(--text);
}

.ported-style-page--paper-cut .gf-swatch__meta code {
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.04em;
  color: var(--ink-faint);
}

.ported-style-page--paper-cut .gf-rules {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: var(--space-block);
}

.ported-style-page--paper-cut .gf-rule {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 24px;
  background: var(--substrate);
  border-radius: 4px;
  box-shadow:
    5px 5px 0 var(--shadow-soft),
    10px 10px 0 var(--shadow);
}

.ported-style-page--paper-cut .gf-rule__title {
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: var(--tracking-headline);
  color: var(--text);
  word-break: keep-all;
  margin: 4px 0 4px;
}

.ported-style-page--paper-cut .gf-rule__body {
  font-family: var(--font-body);
  font-size: 14.5px;
  font-weight: 500;
  line-height: 1.7;
  color: var(--ink-muted);
  word-break: keep-all;
}

/* ───────────────────────────────────────────────────────────────────────
   Contact
   ─────────────────────────────────────────────────────────────────────── */

.ported-style-page--paper-cut .gf-contact {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding-top: 32px;
  padding-bottom: var(--space-section);
  border-top: 1px solid rgba(34, 29, 22, 0.22);
}

.ported-style-page--paper-cut .gf-contact__email {
  font-family: var(--font-display);
  font-size: clamp(1.8rem, 4vw, 2.8rem);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: var(--tracking-display);
  color: var(--text);
  max-width: 24ch;
  word-break: break-all;
}

.ported-style-page--paper-cut .gf-contact__note {
  font-family: var(--font-body);
  font-size: 14.5px;
  font-weight: 500;
  line-height: 1.65;
  color: var(--ink-muted);
  max-width: 46ch;
  word-break: keep-all;
}

/* ───────────────────────────────────────────────────────────────────────
   AI prompt — paper-fold disclosure (rebuilt to match the rest of the page)
   ─────────────────────────────────────────────────────────────────────── */

.ported-style-page--paper-cut .prompt {
  padding: 0 0 var(--space-section);
}

.ported-style-page--paper-cut .prompt-fold > summary {
  list-style: none;
  cursor: pointer;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;
  padding: 14px 20px;
  background: var(--paper-2);
  border-radius: 6px;
  box-shadow: 4px 4px 0 var(--shadow);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.ported-style-page--paper-cut .prompt-fold > summary::-webkit-details-marker { display: none; }

.ported-style-page--paper-cut .prompt-fold > summary:hover {
  transform: translate(-2px, -2px);
  box-shadow: 6px 6px 0 var(--shadow);
}

.ported-style-page--paper-cut .prompt-fold__label {
  font-family: var(--font-display);
  font-size: clamp(1.1rem, 2.2vw, 1.3rem);
  font-weight: 700;
  letter-spacing: var(--tracking-headline);
  color: var(--text);
}

.ported-style-page--paper-cut .prompt-fold__hint {
  font-family: var(--font-mono);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: rgba(34, 29, 22, 0.5);
}

.ported-style-page--paper-cut .prompt-fold[open] > summary {
  margin-bottom: 20px;
  background: var(--paper-3);
}

.ported-style-page--paper-cut .prompt-fold[open] .prompt-fold__label { color: #fff; }
.ported-style-page--paper-cut .prompt-fold[open] .prompt-fold__hint { color: rgba(255, 255, 255, 0.75); }

.ported-style-page--paper-cut .prompt pre {
  position: relative;
  white-space: pre-wrap;
  word-wrap: break-word;
  font-family: var(--font-body);
  font-size: 14px;
  font-weight: 500;
  line-height: 1.75;
  color: var(--text);
  padding: 28px 28px 32px;
  border-radius: 4px;
  background: var(--paper-2);
  box-shadow:
    8px 8px 0 var(--paper-3),
    16px 16px 0 var(--shadow);
}

.ported-style-page--paper-cut .prompt button {
  margin-top: 24px;
  padding: 11px 26px;
  border-radius: 6px;
  border: none;
  background: var(--paper-4);
  color: #fff;
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 0.9rem;
  letter-spacing: 0.04em;
  cursor: pointer;
  transition: transform 0.22s ease, box-shadow 0.22s ease;
  box-shadow: 4px 4px 0 var(--shadow);
}

.ported-style-page--paper-cut .prompt button:hover {
  transform: translate(-2px, -2px);
  box-shadow: 6px 6px 0 var(--shadow);
}

/* ───────────────────────────────────────────────────────────────────────
   Chrome — site-nav typography, page-back-link, page-footer, page-nav
   ─────────────────────────────────────────────────────────────────────── */

.ported-style-page--paper-cut .site-nav__logo {
  font-family: var(--font-display);
  font-weight: 800;
  letter-spacing: var(--tracking-display);
  font-size: 1.05rem;
  color: var(--text);
}

.ported-style-page--paper-cut .site-nav__links a,
.ported-style-page--paper-cut .lang-toggle,
.ported-style-page--paper-cut .lang-menu button {
  font-family: var(--font-body);
  font-weight: 600;
  letter-spacing: 0.02em;
  color: var(--text);
}

.ported-style-page--paper-cut .page-back-link {
  position: fixed;
  top: 20px;
  left: 20px;
  z-index: 100;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 14px;
  background: var(--paper-1);
  border: 1px solid var(--shadow-light);
  border-radius: 6px;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--text);
  text-decoration: none;
  box-shadow: 3px 3px 0 var(--shadow);
  transition: transform 0.18s ease, box-shadow 0.18s ease;
}

.ported-style-page--paper-cut .page-back-link:hover {
  transform: translate(-1px, -1px);
  box-shadow: 4px 4px 0 var(--shadow);
}

.ported-style-page--paper-cut .page-back-link svg {
  width: 12px;
  height: 12px;
}

.ported-style-page--paper-cut .page-footer {
  text-align: center;
  padding: 28px 20px 64px;
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--ink-faint);
}

.ported-style-page--paper-cut .page-footer a {
  color: var(--ink-muted);
  text-decoration: none;
}

/* Page-nav — replaces the dark-glass band the showcase ships globally. The
   shared .ported-style-page rule strips grid-template-columns, so we must
   re-establish the 2-col layout here and rebuild each <a>'s flex internals. */
.ported-style-page.ported-style-page--paper-cut:not(.ported-style-page--platform-core):not(.ported-style-page--runtime-signal) .page-nav {
  display: grid !important;
  grid-template-columns: 1fr 1fr !important;
  gap: 14px !important;
  padding: 16px !important;
  background: var(--paper-1) !important;
  border: 1px solid rgba(0, 0, 0, 0.12) !important;
  border-radius: 12px !important;
  box-shadow: 4px 4px 0 var(--shadow) !important;
}

.ported-style-page.ported-style-page--paper-cut:not(.ported-style-page--platform-core):not(.ported-style-page--runtime-signal) .page-nav a {
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  gap: 14px !important;
  padding: 16px 18px !important;
  min-height: 72px !important;
  color: var(--text) !important;
  background: var(--paper-2) !important;
  border: 1px solid rgba(0, 0, 0, 0.12) !important;
  border-radius: 10px !important;
  font-family: var(--font-display) !important;
  font-weight: 700 !important;
  letter-spacing: var(--tracking-headline) !important;
  box-shadow: 3px 3px 0 var(--shadow) !important;
  transition: transform 0.2s ease, box-shadow 0.2s ease !important;
}

.ported-style-page.ported-style-page--paper-cut:not(.ported-style-page--platform-core):not(.ported-style-page--runtime-signal) .page-nav a:last-of-type {
  flex-direction: row-reverse !important;
  text-align: right !important;
}

.ported-style-page.ported-style-page--paper-cut:not(.ported-style-page--platform-core):not(.ported-style-page--runtime-signal) .page-nav a > span {
  display: flex !important;
  flex-direction: column !important;
  align-items: flex-start !important;
  gap: 4px !important;
  flex: 1 !important;
  line-height: 1.2 !important;
}

.ported-style-page.ported-style-page--paper-cut:not(.ported-style-page--platform-core):not(.ported-style-page--runtime-signal) .page-nav a:last-of-type > span {
  align-items: flex-end !important;
}

.ported-style-page.ported-style-page--paper-cut:not(.ported-style-page--platform-core):not(.ported-style-page--runtime-signal) .page-nav a:hover {
  transform: translate(-1px, -1px) !important;
  background: var(--paper-3) !important;
  border-color: var(--text) !important;
  box-shadow: 5px 5px 0 var(--shadow) !important;
}

.ported-style-page.ported-style-page--paper-cut:not(.ported-style-page--platform-core):not(.ported-style-page--runtime-signal) .page-nav a svg {
  width: 16px !important;
  height: 16px !important;
  flex-shrink: 0 !important;
  stroke: var(--text) !important;
}

.ported-style-page.ported-style-page--paper-cut:not(.ported-style-page--platform-core):not(.ported-style-page--runtime-signal) .page-nav__divider {
  display: none !important;
}

.ported-style-page.ported-style-page--paper-cut:not(.ported-style-page--platform-core):not(.ported-style-page--runtime-signal) .page-nav .page-nav__label {
  font-family: var(--font-mono) !important;
  font-size: 0.7rem !important;
  font-weight: 500 !important;
  color: rgba(34, 29, 22, 0.55) !important;
  letter-spacing: 0.14em !important;
  text-transform: uppercase !important;
}

@media (max-width: 640px) {
  .ported-style-page.ported-style-page--paper-cut:not(.ported-style-page--platform-core):not(.ported-style-page--runtime-signal) .page-nav {
    grid-template-columns: 1fr !important;
    gap: 10px !important;
  }
}

/* ───────────────────────────────────────────────────────────────────────
   Responsive
   ─────────────────────────────────────────────────────────────────────── */

@media (max-width: 960px) {
  .ported-style-page--paper-cut .gf-hero {
    grid-template-columns: 1fr;
    gap: 48px;
  }
  .ported-style-page--paper-cut .gf-hero__title {
    max-width: 18ch;
  }
  .ported-style-page--paper-cut .gf-work {
    grid-template-columns: 1fr;
    gap: 28px;
  }
  .ported-style-page--paper-cut .gf-work--right .gf-work__piece { order: 1; }
  .ported-style-page--paper-cut .gf-work--right .gf-work__text { order: 2; }
  .ported-style-page--paper-cut .gf-swatches { grid-template-columns: repeat(5, 1fr); gap: 10px; }
}

@media (max-width: 600px) {
  .ported-style-page--paper-cut .gf-swatches { grid-template-columns: repeat(3, 1fr); }
  .ported-style-page--paper-cut .gf-hero__sub { font-size: 0.95rem; }
}



/* Product × Swiss — figma-inspired soft product editorial. Class prefix `ps-`. */
.ported-style-page--fusion-product-swiss,
.ported-style-page--fusion-product-swiss * {
  box-sizing: border-box;
}

.ported-style-page--fusion-product-swiss {
  --ps-paper: #ffffff;
  --ps-paper-soft: #fafafa;
  --ps-canvas: #ffffff;
  --ps-ink: #0d0d0e;
  --ps-ink-soft: #25262a;
  --ps-muted: #6a6c72;
  --ps-line: #e6e7ea;
  --ps-line-soft: #eef0f3;
  --ps-wash: #f4f5f7;
  --ps-yellow: #ffd84d;
  --ps-blue: #73d7ff;
  --ps-coral: #ff765f;
  --ps-green: #78d88c;
  --ps-lilac: #cbb7ff;
  --ps-violet: #6c5cff;
  --ps-shadow-sm: 0 1px 2px rgba(15, 17, 22, 0.04), 0 2px 6px rgba(15, 17, 22, 0.04);
  --ps-shadow-md: 0 12px 32px rgba(15, 17, 22, 0.06), 0 4px 10px rgba(15, 17, 22, 0.04);
  --ps-shadow-lg: 0 30px 70px rgba(15, 17, 22, 0.10), 0 10px 24px rgba(15, 17, 22, 0.05);
  --ps-display-font: 'Instrument Sans', 'Plus Jakarta Sans', 'IBM Plex Sans KR', 'Noto Sans JP', sans-serif;
  --ps-body-font: 'Plus Jakarta Sans', 'IBM Plex Sans KR', 'Noto Sans JP', sans-serif;
  --ps-mono-font: 'JetBrains Mono', 'IBM Plex Mono', monospace;
  min-height: 100svh;
  background:
    radial-gradient(820px 520px at 6% -6%, rgba(108, 92, 255, 0.06), transparent 72%),
    radial-gradient(900px 560px at 108% 12%, rgba(115, 215, 255, 0.07), transparent 72%),
    radial-gradient(680px 480px at -8% 96%, rgba(203, 183, 255, 0.05), transparent 72%),
    var(--ps-paper);
  color: var(--ps-ink);
  font-family: var(--ps-body-font);
  -webkit-font-smoothing: antialiased;
  letter-spacing: -0.004em;
}

.ported-style-page--fusion-product-swiss a {
  text-decoration: none;
}

.ported-style-page--fusion-product-swiss :where(h1, h2, h3, p, ol, dl, dd, dt, ul, li) {
  margin: 0;
  padding: 0;
}

.ported-style-page--fusion-product-swiss ul,
.ported-style-page--fusion-product-swiss ol {
  list-style: none;
}

.ported-style-page--fusion-product-swiss button {
  cursor: pointer;
  font-family: inherit;
}

.ported-style-page--fusion-product-swiss .page-back-link {
  position: fixed;
  top: 18px;
  left: 18px;
  z-index: 60;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 36px;
  padding: 0 14px;
  border: 1px solid var(--ps-line);
  border-radius: 999px;
  background: rgba(255, 253, 250, 0.9);
  color: var(--ps-ink);
  font-size: 0.82rem;
  font-weight: 600;
  box-shadow: var(--ps-shadow-sm);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

.ported-style-page--fusion-product-swiss .page-back-link,
.ported-style-page--fusion-product-swiss .page-back-link:visited {
  color: var(--ps-ink) !important;
  background: rgba(255, 253, 250, 0.9) !important;
  border-color: var(--ps-line) !important;
}

.ported-style-page--fusion-product-swiss .page-back-link svg {
  width: 14px;
  height: 14px;
  stroke: var(--ps-ink) !important;
}

/* Shell ------------------------------------------------------------ */
.ps-shell {
  width: min(1240px, calc(100vw - 40px));
  margin: 0 auto;
  padding: 28px 0 80px;
}

/* Nav -------------------------------------------------------------- */
.ps-nav {
  position: sticky;
  top: 14px;
  z-index: 30;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  min-height: 60px;
  padding: 8px 8px 8px 18px;
  border: 1px solid var(--ps-line);
  border-radius: 999px;
  background: rgba(253, 249, 240, 0.78);
  backdrop-filter: blur(20px) saturate(140%);
  -webkit-backdrop-filter: blur(20px) saturate(140%);
  box-shadow: var(--ps-shadow-sm);
}

.ps-brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--ps-ink);
  font-family: var(--ps-display-font);
  font-size: 0.95rem;
  font-weight: 700;
  letter-spacing: -0.01em;
}

.ps-brand__mark {
  display: grid;
  grid-template-columns: repeat(2, 9px);
  grid-template-rows: repeat(2, 9px);
  gap: 2px;
  width: 20px;
  height: 20px;
}

.ps-brand__mark i {
  display: block;
  border-radius: 2px;
}

.ps-brand__mark i:nth-child(1) {
  grid-row: span 2;
  border-top-left-radius: 999px;
  border-top-right-radius: 999px;
  background: var(--ps-coral);
}

.ps-brand__mark i:nth-child(2) {
  border-radius: 999px;
  background: var(--ps-yellow);
}

.ps-brand__mark i:nth-child(3) {
  border-bottom-left-radius: 999px;
  border-bottom-right-radius: 999px;
  background: var(--ps-blue);
}

.ps-nav__links {
  display: inline-flex;
  align-items: center;
  gap: 2px;
}

.ps-nav__links a {
  display: inline-flex;
  align-items: center;
  min-height: 32px;
  padding: 0 12px;
  border-radius: 999px;
  color: var(--ps-muted);
  font-size: 0.86rem;
  font-weight: 600;
  transition: background 160ms ease, color 160ms ease;
}

.ps-nav__links a:hover,
.ps-nav__links a:focus-visible {
  background: rgba(15, 17, 22, 0.05);
  color: var(--ps-ink);
}

.ps-nav__actions {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.ps-nav .lang-dropdown {
  position: relative;
}

.ps-nav .lang-toggle {
  min-height: 34px;
  padding: 0 12px;
  border: 1px solid var(--ps-line);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.6);
  color: var(--ps-ink);
  font-size: 0.83rem;
  font-weight: 600;
}

.ps-nav .lang-menu {
  position: absolute;
  top: calc(100% + 8px);
  right: 0;
  z-index: 20;
  display: none;
  min-width: 132px;
  margin: 0;
  padding: 6px;
  list-style: none;
  border: 1px solid var(--ps-line);
  border-radius: 14px;
  background: var(--ps-canvas);
  box-shadow: var(--ps-shadow-md);
}

.ps-nav .lang-dropdown.open .lang-menu {
  display: grid;
  gap: 2px;
}

.ps-nav .lang-menu button {
  width: 100%;
  min-height: 32px;
  padding: 0 10px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: var(--ps-ink);
  font-size: 0.84rem;
  font-weight: 600;
  text-align: left;
}

.ps-nav .lang-menu button:hover,
.ps-nav .lang-menu button.active {
  background: rgba(255, 216, 77, 0.3);
}

.ps-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 40px;
  padding: 0 18px;
  border: 1px solid var(--ps-line);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.78);
  color: var(--ps-ink);
  font-size: 0.88rem;
  font-weight: 600;
  letter-spacing: -0.005em;
  box-shadow: var(--ps-shadow-sm);
  transition: transform 180ms ease, box-shadow 220ms ease, background 200ms ease;
}

.ps-btn:hover,
.ps-btn:focus-visible {
  transform: translateY(-1px);
  box-shadow: var(--ps-shadow-md);
}

.ps-btn--dark {
  border-color: var(--ps-ink);
  background: var(--ps-ink);
  color: var(--ps-paper-soft);
}

.ported-style-page--fusion-product-swiss a.ps-btn--dark,
.ported-style-page--fusion-product-swiss a.ps-btn--dark:visited {
  color: var(--ps-paper-soft) !important;
}

.ps-btn--ghost {
  border-color: transparent;
  background: transparent;
  box-shadow: none;
}

.ps-btn--ghost:hover {
  background: rgba(0, 0, 0, 0.04);
  box-shadow: none;
}

.ps-btn--outline {
  background: rgba(255, 255, 255, 0.6);
}

/* Hero (top heading band) ----------------------------------------- */
.ps-hero {
  padding: 96px 0 64px;
  max-width: 1100px;
}

.ps-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--ps-coral);
  font-family: var(--ps-mono-font);
  font-size: 0.76rem;
  font-weight: 600;
  letter-spacing: 0.01em;
  text-transform: uppercase;
}

.ps-eyebrow::before {
  content: '';
  display: inline-block;
  width: 28px;
  height: 1px;
  background: currentColor;
  opacity: 0.6;
}

.ps-eyebrow--alt {
  color: var(--ps-violet);
}

.ps-display {
  margin-top: 22px;
  font-family: var(--ps-display-font);
  font-size: clamp(3.2rem, 7.4vw, 7rem);
  font-weight: 600;
  line-height: 1.0;
  letter-spacing: -0.026em;
  color: var(--ps-ink);
  font-style: normal;
}

.ps-display em {
  font-style: italic;
  font-weight: 600;
  letter-spacing: -0.018em;
}

.ps-hero__foot {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) auto;
  align-items: end;
  gap: 36px;
  margin-top: 36px;
}

.ps-lead {
  max-width: 620px;
  color: var(--ps-ink-soft);
  font-size: clamp(1.05rem, 1.2vw, 1.18rem);
  font-weight: 450;
  line-height: 1.55;
}

.ps-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-self: end;
}

/* Canvas (Figma file) --------------------------------------------- */
.ps-canvas {
  position: relative;
  border: 1px solid var(--ps-line);
  border-radius: 22px;
  background: var(--ps-canvas);
  box-shadow: var(--ps-shadow-lg);
  overflow: hidden;
  margin-top: 16px;
}

.ps-canvas__chrome {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-height: 52px;
  padding: 0 16px;
  border-bottom: 1px solid var(--ps-line-soft);
  background: linear-gradient(180deg, #fbfbfc, #f6f7f9);
}

.ps-canvas__chrome-left,
.ps-canvas__chrome-right {
  display: inline-flex;
  align-items: center;
  gap: 14px;
}

.ps-traffic {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.ps-traffic i {
  width: 11px;
  height: 11px;
  border-radius: 999px;
  background: #d9d1bf;
}

.ps-traffic i:nth-child(1) { background: #ff5f57; }
.ps-traffic i:nth-child(2) { background: #ffbd2e; }
.ps-traffic i:nth-child(3) { background: #28c940; }

.ps-file {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding-left: 8px;
}

.ps-file__icon {
  display: grid;
  grid-template-columns: repeat(2, 7px);
  grid-template-rows: repeat(2, 7px);
  gap: 2px;
  width: 16px;
  height: 16px;
}

.ps-file__icon i {
  display: block;
  border-radius: 2px;
}

.ps-file__icon i:nth-child(1) { background: var(--ps-coral); }
.ps-file__icon i:nth-child(2) { background: var(--ps-yellow); }
.ps-file__icon i:nth-child(3) { background: var(--ps-blue); }
.ps-file__icon i:nth-child(4) { background: var(--ps-green); }

.ps-file__text {
  display: inline-flex;
  align-items: baseline;
  gap: 10px;
}

.ps-file__text strong {
  color: var(--ps-ink);
  font-size: 0.86rem;
  font-weight: 650;
  letter-spacing: -0.01em;
}

.ps-file__text small {
  color: var(--ps-muted);
  font-size: 0.74rem;
  font-weight: 500;
}

.ps-presence {
  display: inline-flex;
}

.ps-presence__avatar {
  display: inline-grid;
  place-items: center;
  width: 26px;
  height: 26px;
  border: 2px solid #ffffff;
  border-radius: 999px;
  font-size: 0.7rem;
  font-weight: 700;
  color: #fff;
}

.ps-presence__avatar + .ps-presence__avatar {
  margin-left: -8px;
}

.ps-presence__avatar--0 { background: var(--ps-violet); }
.ps-presence__avatar--1 { background: var(--ps-coral); }
.ps-presence__avatar--2 { background: var(--ps-green); color: #1d3a26; }

.ps-zoom {
  color: var(--ps-muted);
  font-family: var(--ps-mono-font);
  font-size: 0.75rem;
  font-weight: 600;
}

.ps-canvas__share {
  min-height: 30px;
  padding: 0 12px;
  border: 0;
  border-radius: 999px;
  background: var(--ps-ink);
  color: var(--ps-paper-soft);
  font-size: 0.78rem;
  font-weight: 600;
}

.ps-canvas__body {
  display: grid;
  grid-template-columns: 196px minmax(0, 1fr) 232px;
  min-height: 540px;
}

/* Rail (pages + layers) ------------------------------------------- */
.ps-rail,
.ps-inspector {
  padding: 18px 14px;
  background: var(--ps-paper-soft);
  border-right: 1px solid var(--ps-line-soft);
}

.ps-inspector {
  border-right: 0;
  border-left: 1px solid var(--ps-line-soft);
}

.ps-rail__label {
  margin: 4px 4px 8px;
  color: var(--ps-muted);
  font-family: var(--ps-mono-font);
  font-size: 0.66rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.ps-rail__label + .ps-rail__label {
  margin-top: 18px;
}

.ps-rail__pages,
.ps-rail__layers {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.ps-rail__pages li,
.ps-rail__layers li {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 30px;
  padding: 0 10px;
  border-radius: 8px;
  color: var(--ps-ink-soft);
  font-size: 0.82rem;
  font-weight: 500;
}

.ps-rail__pages li span {
  color: var(--ps-muted);
  font-size: 0.7rem;
}

.ps-rail__pages li.is-active,
.ps-rail__layers li.is-active {
  background: rgba(108, 92, 255, 0.12);
  color: var(--ps-violet);
  font-weight: 600;
}

.ps-rail__pages li.is-active span {
  color: var(--ps-violet);
}

.ps-layer-icon {
  display: inline-grid;
  place-items: center;
  width: 18px;
  height: 18px;
  border-radius: 4px;
  background: rgba(0, 0, 0, 0.05);
  color: var(--ps-muted);
  font-family: var(--ps-mono-font);
  font-size: 0.7rem;
  font-weight: 600;
  line-height: 1;
}

.ps-layer-icon--frame { background: rgba(108, 92, 255, 0.16); color: var(--ps-violet); }
.ps-layer-icon--text { background: rgba(15, 17, 22, 0.06); color: var(--ps-ink); }
.ps-layer-icon--component { background: rgba(255, 118, 95, 0.18); color: #b54836; }
.ps-layer-icon--group { background: rgba(115, 215, 255, 0.22); color: #1a7090; }

/* Stage / artboard ------------------------------------------------- */
.ps-stage {
  position: relative;
  min-height: 540px;
  background:
    radial-gradient(circle, rgba(15, 17, 22, 0.08) 1px, transparent 1.5px) 0 0 / 18px 18px,
    #fafbfd;
  overflow: hidden;
}

.ps-ruler {
  position: absolute;
  inset: 0 0 auto 0;
  height: 22px;
  background:
    linear-gradient(180deg, #fcfcfd, #f4f5f8 100%);
  border-bottom: 1px solid var(--ps-line-soft);
  background-image:
    repeating-linear-gradient(90deg, rgba(15, 17, 22, 0.14) 0 1px, transparent 1px 40px);
  background-size: auto, auto;
}

.ps-artboard {
  position: absolute;
  top: 56px;
  left: 38px;
  right: 38px;
  bottom: 38px;
  border-radius: 12px;
  background: transparent;
}

.ps-artboard__tag {
  position: absolute;
  top: -22px;
  left: 4px;
  color: var(--ps-violet);
  font-family: var(--ps-mono-font);
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.02em;
}

.ps-mini {
  position: relative;
  overflow: hidden;
  border-radius: 12px;
  background: var(--ps-canvas);
  box-shadow:
    0 1px 0 rgba(15, 17, 22, 0.05),
    0 24px 60px rgba(15, 17, 22, 0.08),
    0 8px 20px rgba(15, 17, 22, 0.05);
}

.ps-mini__nav {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 36px;
  padding: 0 16px;
  border-bottom: 1px solid var(--ps-line-soft);
}

.ps-mini__nav span {
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: rgba(15, 17, 22, 0.12);
}

.ps-mini__nav em {
  margin-left: auto;
  color: var(--ps-muted);
  font-size: 0.7rem;
  font-style: normal;
}

.ps-mini__body {
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(0, 0.95fr);
  gap: 24px;
  padding: 26px 26px 28px;
}

.ps-mini__copy {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.ps-mini__chip {
  align-self: flex-start;
  padding: 5px 10px;
  border-radius: 999px;
  background: rgba(108, 92, 255, 0.12);
  color: var(--ps-violet);
  font-family: var(--ps-mono-font);
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  text-transform: uppercase;
}

.ps-mini__copy h3 {
  font-family: var(--ps-display-font);
  font-size: clamp(1.35rem, 2.1vw, 1.85rem);
  font-weight: 600;
  line-height: 1.06;
  letter-spacing: -0.02em;
  color: var(--ps-ink);
}

.ps-mini__copy p {
  color: var(--ps-muted);
  font-size: 0.88rem;
  font-weight: 450;
  line-height: 1.5;
}

.ps-mini__buttons {
  display: inline-flex;
  gap: 8px;
  margin-top: 6px;
}

.ps-mini__cta {
  display: inline-flex;
  align-items: center;
  min-height: 30px;
  padding: 0 12px;
  border-radius: 999px;
  background: var(--ps-ink);
  color: var(--ps-paper-soft);
  font-size: 0.76rem;
  font-weight: 600;
}

.ps-mini__cta--ghost {
  background: transparent;
  color: var(--ps-ink);
  border: 1px solid var(--ps-line);
}

.ps-mini__product {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  grid-auto-rows: 60px;
  gap: 10px;
}

.ps-mini__card {
  position: relative;
  border-radius: 12px;
  padding: 10px;
  overflow: hidden;
}

.ps-mini__card--lilac {
  grid-row: span 2;
  background: linear-gradient(160deg, #d8c8ff 0%, #c0a8ff 100%);
}

.ps-mini__card--lilac span {
  display: block;
  height: 6px;
  background: rgba(255, 255, 255, 0.6);
  border-radius: 999px;
  margin-top: 6px;
}

.ps-mini__card--lilac span:first-child {
  width: 65%;
  margin-top: 0;
}
.ps-mini__card--lilac span:nth-child(2) { width: 80%; }
.ps-mini__card--lilac span:nth-child(3) { width: 45%; }

.ps-mini__card--yellow {
  background: linear-gradient(160deg, #ffe27a, #ffcb3a);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.ps-mini__card--yellow em {
  color: #4b3700;
  font-size: 0.78rem;
  font-weight: 700;
  font-style: normal;
  letter-spacing: -0.01em;
}

.ps-mini__card--yellow span {
  height: 4px;
  background: rgba(90, 62, 0, 0.32);
  border-radius: 999px;
}

.ps-mini__card--blue {
  background: linear-gradient(160deg, #a4e7ff, #6cccff);
  display: flex;
  align-items: center;
  gap: 6px;
}

.ps-mini__card--blue i {
  display: block;
  width: 10px;
  height: 10px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.85);
}

.ps-mini__card--blue i:nth-child(2) { background: rgba(255, 255, 255, 0.55); }
.ps-mini__card--blue i:nth-child(3) { background: rgba(255, 255, 255, 0.3); }

.ps-mini__card--green {
  background: linear-gradient(160deg, #a4ebb6, #6cd486);
  display: grid;
  place-items: center;
}

.ps-mini__card--green span {
  width: 70%;
  height: 24px;
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.6);
  position: relative;
}

.ps-mini__card--green span::after {
  content: '';
  position: absolute;
  left: 4px;
  right: 4px;
  bottom: 4px;
  height: 6px;
  background: rgba(20, 70, 35, 0.55);
  border-radius: 999px;
  clip-path: polygon(0 60%, 18% 30%, 36% 70%, 56% 20%, 74% 50%, 100% 10%, 100% 100%, 0 100%);
}

/* Selection box --------------------------------------------------- */
.ps-selection {
  position: absolute;
  right: 90px;
  bottom: 78px;
  width: 198px;
  height: 130px;
  border: 1.5px solid var(--ps-violet);
  border-radius: 6px;
  pointer-events: none;
}

.ps-selection__handle {
  position: absolute;
  width: 9px;
  height: 9px;
  background: var(--ps-canvas);
  border: 1.5px solid var(--ps-violet);
  border-radius: 2px;
}

.ps-selection__handle--tl { top: -5px; left: -5px; }
.ps-selection__handle--tr { top: -5px; right: -5px; }
.ps-selection__handle--bl { bottom: -5px; left: -5px; }
.ps-selection__handle--br { bottom: -5px; right: -5px; }

.ps-selection__dim {
  position: absolute;
  left: 50%;
  bottom: -22px;
  transform: translateX(-50%);
  padding: 2px 6px;
  border-radius: 4px;
  background: var(--ps-violet);
  color: #fff;
  font-family: var(--ps-mono-font);
  font-size: 0.66rem;
  font-weight: 600;
  white-space: nowrap;
}

/* Cursors --------------------------------------------------------- */
.ps-cursor {
  position: absolute;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  pointer-events: none;
  animation: ps-cursor-in 720ms ease both;
}

.ps-cursor svg {
  width: 18px;
  height: 18px;
  fill: currentColor;
  filter: drop-shadow(0 2px 4px rgba(15, 17, 22, 0.18));
}

.ps-cursor span {
  margin-top: 18px;
  padding: 3px 8px;
  border-radius: 5px;
  color: #fff;
  background: currentColor;
  font-family: var(--ps-display-font);
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: -0.005em;
}

.ps-cursor span::first-letter { color: #fff; }
.ps-cursor--coral { color: var(--ps-coral); top: 76px; right: 200px; animation-delay: 360ms; }
.ps-cursor--blue { color: #2aa7d6; top: 158px; right: 88px; animation-delay: 480ms; }
.ps-cursor--coral span,
.ps-cursor--blue span {
  color: #fff;
}

/* Comment cards --------------------------------------------------- */
.ps-comment {
  position: absolute;
  max-width: 220px;
  padding: 12px 14px 14px;
  border-radius: 14px;
  background: var(--ps-canvas);
  box-shadow: var(--ps-shadow-md);
  transition: transform 220ms ease;
  animation: ps-soft-rise 720ms ease both;
}

.ps-comment:hover {
  transform: translateY(-3px);
}

.ps-comment header {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 6px;
}

.ps-comment__avatar {
  display: inline-grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border-radius: 999px;
  background: var(--ps-coral);
  color: #fff;
  font-size: 0.66rem;
  font-weight: 700;
}

.ps-comment__avatar--alt {
  background: var(--ps-violet);
}

.ps-comment header strong {
  color: var(--ps-ink);
  font-size: 0.78rem;
  font-weight: 650;
}

.ps-comment header em {
  color: var(--ps-muted);
  font-size: 0.72rem;
  font-style: normal;
}

.ps-comment p {
  color: var(--ps-ink-soft);
  font-size: 0.82rem;
  font-weight: 450;
  line-height: 1.45;
}

.ps-comment::before {
  content: '';
  position: absolute;
  top: -10px;
  left: 18px;
  width: 0;
  height: 0;
  border-left: 8px solid transparent;
  border-right: 8px solid transparent;
  border-bottom: 10px solid var(--ps-canvas);
  filter: drop-shadow(0 -2px 2px rgba(15, 17, 22, 0.06));
}

.ps-comment--one {
  top: 18px;
  left: 36px;
  animation-delay: 520ms;
}

.ps-comment--two {
  right: 28px;
  bottom: 18px;
  animation-delay: 640ms;
}

.ps-comment--two::before {
  top: auto;
  bottom: -10px;
  left: auto;
  right: 20px;
  border-bottom: 0;
  border-top: 10px solid var(--ps-canvas);
}

/* Inspector ------------------------------------------------------- */
.ps-inspector__rows {
  display: grid;
  gap: 0;
  margin-bottom: 18px;
  border-top: 1px solid var(--ps-line-soft);
}

.ps-inspector__rows div {
  display: grid;
  grid-template-columns: 56px 1fr;
  gap: 8px;
  padding: 9px 4px;
  border-bottom: 1px solid var(--ps-line-soft);
}

.ps-inspector__rows dt {
  color: var(--ps-muted);
  font-family: var(--ps-mono-font);
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  text-transform: uppercase;
}

.ps-inspector__rows dd {
  color: var(--ps-ink);
  font-size: 0.78rem;
  font-weight: 500;
  letter-spacing: -0.005em;
}

.ps-inspector__palette {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 6px;
  margin-bottom: 16px;
}

.ps-swatch {
  aspect-ratio: 1;
  border-radius: 8px;
  box-shadow: inset 0 0 0 1px rgba(15, 17, 22, 0.06);
}

.ps-swatch--0 { background: var(--ps-coral); }
.ps-swatch--1 { background: var(--ps-yellow); }
.ps-swatch--2 { background: var(--ps-blue); }
.ps-swatch--3 { background: var(--ps-green); }
.ps-swatch--4 { background: var(--ps-lilac); }

.ps-inspector__autolayout {
  padding: 8px 10px;
  border-radius: 8px;
  background: rgba(108, 92, 255, 0.1);
  color: var(--ps-violet);
  font-family: var(--ps-mono-font);
  font-size: 0.72rem;
  font-weight: 600;
  margin-bottom: 12px;
}

.ps-inspector__bars {
  display: grid;
  gap: 6px;
}

.ps-inspector__bars span {
  display: block;
  height: 6px;
  border-radius: 999px;
  background: rgba(15, 17, 22, 0.08);
}

.ps-inspector__bars span:nth-child(2) {
  background: rgba(255, 118, 95, 0.4);
}

.ps-inspector__bars span:nth-child(3) {
  background: rgba(115, 215, 255, 0.55);
}

/* Metrics --------------------------------------------------------- */
.ps-metrics {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  margin-top: 28px;
}

.ps-metrics article {
  min-height: 112px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 18px;
  border: 1px solid var(--ps-line);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.7);
  box-shadow: var(--ps-shadow-sm);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}

.ps-metrics span {
  color: var(--ps-muted);
  font-family: var(--ps-mono-font);
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.ps-metrics strong {
  font-family: var(--ps-display-font);
  font-size: 1.55rem;
  font-weight: 600;
  letter-spacing: -0.018em;
  color: var(--ps-ink);
}

/* Roles ----------------------------------------------------------- */
.ps-roles {
  margin-top: 56px;
}

.ps-roles ul {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 12px;
}

.ps-roles__pill {
  min-height: 38px;
  display: inline-flex;
  align-items: center;
  padding: 0 16px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.78);
  border: 1px solid var(--ps-line);
  color: var(--ps-ink);
  font-size: 0.84rem;
  font-weight: 600;
  letter-spacing: -0.005em;
}

.ps-roles__pill--1 { background: rgba(255, 216, 77, 0.36); border-color: rgba(255, 216, 77, 0.7); }
.ps-roles__pill--3 { background: rgba(115, 215, 255, 0.32); border-color: rgba(115, 215, 255, 0.6); }
.ps-roles__pill--5 { background: rgba(255, 118, 95, 0.24); border-color: rgba(255, 118, 95, 0.5); }

/* Principles ------------------------------------------------------ */
.ps-principles {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 14px;
  margin-top: 56px;
}

.ps-principles article {
  display: flex;
  flex-direction: column;
  min-height: 260px;
  padding: 24px;
  border: 1px solid var(--ps-line);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.78);
  box-shadow: var(--ps-shadow-sm);
  position: relative;
  overflow: hidden;
}

.ps-principles article::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
}

.ps-principles article:nth-child(1)::before { background: var(--ps-coral); }
.ps-principles article:nth-child(2)::before { background: var(--ps-yellow); }
.ps-principles article:nth-child(3)::before { background: var(--ps-blue); }

.ps-principles span {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 24px;
  margin-bottom: 28px;
  border-radius: 999px;
  background: rgba(15, 17, 22, 0.06);
  color: var(--ps-ink);
  font-family: var(--ps-mono-font);
  font-size: 0.72rem;
  font-weight: 600;
}

.ps-principles h2 {
  font-family: var(--ps-display-font);
  font-size: 1.45rem;
  font-weight: 600;
  line-height: 1.14;
  letter-spacing: -0.018em;
  color: var(--ps-ink);
}

.ps-principles p {
  margin-top: 12px;
  color: var(--ps-muted);
  font-size: 0.92rem;
  font-weight: 450;
  line-height: 1.55;
}

/* Rules ----------------------------------------------------------- */
.ps-rules {
  display: grid;
  grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr);
  gap: 40px;
  align-items: start;
  margin-top: 56px;
  padding: 36px;
  border-radius: 22px;
  background: linear-gradient(180deg, #fafbfc, #f3f4f7);
  border: 1px solid var(--ps-line);
}

.ps-rules__head h2 {
  margin-top: 14px;
  font-family: var(--ps-display-font);
  font-size: clamp(1.9rem, 3.4vw, 2.55rem);
  font-weight: 600;
  line-height: 1.06;
  letter-spacing: -0.024em;
  color: var(--ps-ink);
}

.ps-rules ol {
  display: grid;
  gap: 10px;
  counter-reset: ps-rule;
}

.ps-rules li {
  counter-increment: ps-rule;
  display: grid;
  grid-template-columns: 30px 1fr;
  gap: 14px;
  align-items: center;
  min-height: 56px;
  padding: 12px 14px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.84);
  border: 1px solid var(--ps-line-soft);
  color: var(--ps-ink-soft);
  font-size: 0.92rem;
  font-weight: 500;
  line-height: 1.45;
}

.ps-rules li::before {
  content: counter(ps-rule, decimal-leading-zero);
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 999px;
  background: var(--ps-ink);
  color: var(--ps-paper-soft);
  font-family: var(--ps-mono-font);
  font-size: 0.7rem;
  font-weight: 600;
}

/* Prompt ---------------------------------------------------------- */
.ps-prompt {
  margin-top: 56px;
  border-radius: 22px;
  background: var(--ps-ink);
  color: var(--ps-paper-soft);
  overflow: hidden;
  box-shadow: var(--ps-shadow-md);
}

.ps-prompt__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 18px 22px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.12);
}

.ps-prompt h2 {
  font-family: var(--ps-display-font);
  font-size: 1.35rem;
  font-weight: 600;
  letter-spacing: -0.018em;
}

.ps-prompt button {
  min-height: 36px;
  padding: 0 16px;
  border: 0;
  border-radius: 999px;
  background: var(--ps-yellow);
  color: var(--ps-ink);
  font-size: 0.86rem;
  font-weight: 700;
}

.ps-prompt pre {
  padding: 24px;
  margin: 0;
  color: #e9eaee;
  font-family: var(--ps-mono-font);
  font-size: 0.84rem;
  line-height: 1.65;
  white-space: pre-wrap;
}

/* Footer + page-nav ---------------------------------------------- */
.ported-style-page--fusion-product-swiss .page-footer {
  width: min(1240px, calc(100vw - 40px));
  margin: 0 auto 18px;
  color: var(--ps-muted);
  font-size: 0.86rem;
}

.ported-style-page--fusion-product-swiss .page-footer a {
  color: var(--ps-ink);
  font-weight: 600;
}

.ported-style-page--fusion-product-swiss .page-nav {
  width: min(1240px, calc(100vw - 40px)) !important;
  display: grid !important;
  grid-template-columns: 1fr auto 1fr !important;
  align-items: stretch !important;
  margin: 0 auto 36px !important;
  border: 1px solid var(--ps-line) !important;
  border-radius: 18px !important;
  background: rgba(255, 255, 255, 0.78) !important;
  box-shadow: var(--ps-shadow-sm) !important;
  overflow: hidden;
}

.ported-style-page--fusion-product-swiss .page-nav a {
  display: flex !important;
  align-items: center !important;
  min-height: 64px !important;
  padding: 0 22px !important;
  color: var(--ps-ink) !important;
  font-weight: 650 !important;
}

.ported-style-page--fusion-product-swiss .page-nav a:last-child {
  justify-content: flex-end !important;
  text-align: right;
}

.ported-style-page--fusion-product-swiss .page-nav__label {
  display: block;
  margin-bottom: 4px;
  color: var(--ps-muted);
  font-family: var(--ps-mono-font);
  font-size: 0.66rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.ported-style-page--fusion-product-swiss .page-nav__divider {
  width: 1px !important;
  background: var(--ps-line-soft) !important;
}

/* Animations ----------------------------------------------------- */
.ps-hero,
.ps-canvas,
.ps-metrics article,
.ps-roles,
.ps-principles article,
.ps-rules,
.ps-prompt {
  animation: ps-soft-rise 720ms ease both;
}

.ps-canvas { animation-delay: 110ms; }
.ps-metrics article:nth-child(1) { animation-delay: 180ms; }
.ps-metrics article:nth-child(2) { animation-delay: 240ms; }
.ps-metrics article:nth-child(3) { animation-delay: 300ms; }
.ps-metrics article:nth-child(4) { animation-delay: 360ms; }
.ps-roles { animation-delay: 200ms; }
.ps-principles article:nth-child(1) { animation-delay: 260ms; }
.ps-principles article:nth-child(2) { animation-delay: 320ms; }
.ps-principles article:nth-child(3) { animation-delay: 380ms; }
.ps-rules { animation-delay: 320ms; }
.ps-prompt { animation-delay: 380ms; }

@keyframes ps-soft-rise {
  from {
    opacity: 0;
    transform: translateY(14px) scale(0.992);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes ps-cursor-in {
  from {
    opacity: 0;
    transform: translate(10px, 10px) scale(0.9);
  }
  to {
    opacity: 1;
    transform: translate(0, 0) scale(1);
  }
}

/* Responsive ------------------------------------------------------ */
@media (max-width: 1100px) {
  .ps-canvas__body {
    grid-template-columns: 168px minmax(0, 1fr) 196px;
  }
  .ps-mini__body {
    grid-template-columns: 1fr;
  }
  .ps-mini__product {
    grid-auto-rows: 54px;
  }
}

@media (max-width: 920px) {
  .ps-shell {
    width: min(100vw - 24px, 880px);
  }
  .ps-hero {
    padding: 72px 0 48px;
  }
  .ps-hero__foot {
    grid-template-columns: 1fr;
    align-items: start;
    gap: 24px;
  }
  .ps-actions {
    justify-self: start;
  }
  .ps-canvas__body {
    grid-template-columns: 1fr;
  }
  .ps-rail,
  .ps-inspector {
    display: none;
  }
  .ps-stage {
    min-height: 460px;
  }
  .ps-artboard {
    top: 50px;
    left: 20px;
    right: 20px;
    bottom: 20px;
  }
  .ps-selection {
    right: 40px;
    bottom: 60px;
    width: 168px;
    height: 110px;
  }
  .ps-comment--one { left: 22px; }
  .ps-comment--two { right: 22px; }
  .ps-metrics {
    grid-template-columns: repeat(2, 1fr);
  }
  .ps-principles {
    grid-template-columns: 1fr;
  }
  .ps-rules {
    grid-template-columns: 1fr;
    gap: 24px;
  }
}

@media (max-width: 640px) {
  .ps-shell {
    width: min(100vw - 18px, 620px);
    padding-top: 56px;
  }
  .ps-nav {
    flex-wrap: wrap;
    border-radius: 22px;
    padding: 10px 12px;
  }
  .ps-nav__links {
    order: 3;
    width: 100%;
    overflow-x: auto;
  }
  .ps-hero {
    padding: 36px 0 36px;
  }
  .ps-display {
    font-size: clamp(2.6rem, 12vw, 4rem);
  }
  .ps-canvas__chrome {
    flex-wrap: wrap;
    gap: 10px;
    padding: 12px;
  }
  .ps-canvas__share { display: none; }
  .ps-file__text small { display: none; }
  .ps-stage { min-height: 420px; }
  .ps-mini__body { padding: 18px; gap: 16px; }
  .ps-mini__copy h3 { font-size: 1.3rem; }
  .ps-selection { display: none; }
  .ps-cursor--coral { top: 56px; right: 30px; }
  .ps-cursor--blue { top: 240px; right: 30px; }
  .ps-comment {
    max-width: 180px;
    font-size: 0.78rem;
  }
  .ps-comment--one { top: 12px; left: 14px; }
  .ps-comment--two { right: 14px; bottom: 12px; max-width: 160px; }
  .ps-metrics {
    grid-template-columns: 1fr;
  }
  .ps-rules {
    padding: 22px;
  }
  .ported-style-page--fusion-product-swiss .page-footer,
  .ported-style-page--fusion-product-swiss .page-nav {
    width: min(100vw - 18px, 620px) !important;
  }
}

@media (max-width: 460px) {
  .ps-display {
    font-size: clamp(2.2rem, 11.5vw, 3rem);
  }
  .ps-canvas__chrome-left { gap: 8px; }
  .ps-traffic { display: none; }
  .ps-mini__product {
    grid-template-columns: 1fr;
    grid-auto-rows: 48px;
  }
  .ps-mini__card--lilac { grid-row: span 1; }
}

@media (prefers-reduced-motion: reduce) {
  .ported-style-page--fusion-product-swiss *,
  .ported-style-page--fusion-product-swiss *::before,
  .ported-style-page--fusion-product-swiss *::after {
    animation: none !important;
    transition-duration: 0.01ms !important;
  }
}

/* color-mode expansions */
.ported-style-page--console-launch .nav-actions .theme-toggle:not(.mode-toggle),
.ported-style-page--terminal-core .nav-actions .theme-toggle:not(.mode-toggle) {
  margin-top: 0;
  padding: 0;
  width: 34px;
  height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.ported-style-page--console-launch[data-color-mode="light"] {
  --bg: #f6f8fb !important;
  --panel: #ffffff !important;
  --surface: #edf2f7 !important;
  --line: #ccd6e3 !important;
  --text: #1d2733 !important;
  --muted: #637082 !important;
  --green: #0d8f57 !important;
  --accent: #0d8f57 !important;
  --accent-soft: #72d6a9 !important;
  --haze: rgba(13, 143, 87, 0.12) !important;
  background: #f6f8fb !important;
  background-image: radial-gradient(circle at 50% -20%, rgba(13, 143, 87, 0.12) 0%, transparent 40%) !important;
}
.ported-style-page--console-launch[data-color-mode="light"] .site-nav,
.ported-style-page--console-launch[data-color-mode="light"] .init-sequence,
.ported-style-page--console-launch[data-color-mode="light"] .boot-splash,
.ported-style-page--console-launch[data-color-mode="light"] .terminal-frame,
.ported-style-page--console-launch[data-color-mode="light"] .ide-window {
  box-shadow: 0 18px 44px rgba(40, 54, 73, 0.08);
}
.ported-style-page--console-launch[data-color-mode="light"] .init-sequence {
  background: linear-gradient(180deg, #ffffff, #edf2f7);
}
.ported-style-page--console-launch[data-color-mode="light"] .term-dot {
  background: #c7d1de;
}
.ported-style-page--console-launch[data-color-mode="light"] .term-body .t-sep,
.ported-style-page--console-launch[data-color-mode="light"] .line-num {
  color: #98a5b5;
}
.ported-style-page--console-launch[data-color-mode="light"] .code-comment {
  color: #7b8798;
}
.ported-style-page--console-launch[data-color-mode="light"] .file-item.active,
.ported-style-page--console-launch[data-color-mode="light"] .ide-statusbar {
  background: rgba(13, 143, 87, 0.1);
}
.ported-style-page--console-launch[data-color-mode="light"] .prompt {
  background: #ffffff;
  border-color: var(--line);
}
.ported-style-page--console-launch[data-color-mode="light"] .prompt pre {
  color: #445064;
}
.ported-style-page--console-launch[data-color-mode="light"] .foot {
  color: #748195;
}
.ported-style-page--console-launch[data-color-mode="light"] .page-back-link,
.ported-style-page--console-launch[data-color-mode="light"] .page-nav {
  background: rgba(255, 255, 255, 0.86);
  border-color: var(--line);
  color: var(--text);
}
.ported-style-page--console-launch[data-color-mode="light"] .page-nav a {
  color: var(--text);
}
.ported-style-page--console-launch[data-color-mode="light"] .page-nav__label {
  color: rgba(29, 39, 51, 0.5);
}
.ported-style-page--console-launch[data-color-mode="light"] .page-nav__divider {
  background: var(--line);
}

.ported-style-page--terminal-core[data-color-mode="light"] {
  --bg: #f5f7ef;
  --ink: #18351f;
  --line: #b9d2ba;
  --soft: #eef4e9;
  --warn: #5a7f18;
  background: repeating-linear-gradient(
    180deg,
    #eef4e9 0,
    #eef4e9 2px,
    #f8fbf4 2px,
    #f8fbf4 4px
  );
}
.ported-style-page--terminal-core[data-color-mode="light"] .terminal,
.ported-style-page--terminal-core[data-color-mode="light"] .crt-monitor {
  box-shadow:
    0 0 0 1px rgba(24, 53, 31, 0.12),
    0 18px 32px rgba(37, 55, 31, 0.12),
    inset 0 0 48px rgba(255, 255, 255, 0.42);
}
.ported-style-page--terminal-core[data-color-mode="light"] .bar,
.ported-style-page--terminal-core[data-color-mode="light"] .crt-bar,
.ported-style-page--terminal-core[data-color-mode="light"] .vim-bar {
  background: #e8f0df;
}
.ported-style-page--terminal-core[data-color-mode="light"] .screen,
.ported-style-page--terminal-core[data-color-mode="light"] .crt-screen,
.ported-style-page--terminal-core[data-color-mode="light"] .prompt {
  background: linear-gradient(180deg, #f8fbf4, #eef4e9);
}
.ported-style-page--terminal-core[data-color-mode="light"] .crt-monitor::after {
  background: repeating-linear-gradient(
    180deg,
    rgba(24, 53, 31, 0.04) 0,
    rgba(24, 53, 31, 0.04) 1px,
    transparent 1px,
    transparent 3px
  );
}
.ported-style-page--terminal-core[data-color-mode="light"] .crt-scanline {
  background: rgba(90, 127, 24, 0.1);
}
.ported-style-page--terminal-core[data-color-mode="light"] .glow,
.ported-style-page--terminal-core[data-color-mode="light"] .glow-strong {
  text-shadow: none;
}
.ported-style-page--terminal-core[data-color-mode="light"] .dim {
  opacity: 0.62;
}
.ported-style-page--terminal-core[data-color-mode="light"] button {
  color: #35550f;
  background: #e6efdc;
}
.ported-style-page--terminal-core[data-color-mode="light"] .nav-actions .theme-toggle {
  background: transparent;
  color: var(--ink);
}
.ported-style-page--terminal-core[data-color-mode="light"] .page-back-link,
.ported-style-page--terminal-core[data-color-mode="light"] .page-nav {
  background: rgba(248, 251, 244, 0.88);
  border-color: var(--line);
  color: var(--ink);
}
.ported-style-page--terminal-core[data-color-mode="light"] .page-nav a {
  color: var(--ink);
}
.ported-style-page--terminal-core[data-color-mode="light"] .page-nav a svg,
.ported-style-page--terminal-core[data-color-mode="light"] .page-back-link svg {
  stroke: var(--warn);
}
.ported-style-page--terminal-core[data-color-mode="light"] .page-nav__label {
  color: rgba(24, 53, 31, 0.5);
}
.ported-style-page--terminal-core[data-color-mode="light"] .page-nav__divider {
  background: var(--line);
}
